(window.GIM_TS=window.GIM_TS||{})["Chullin.8"]={"from":192,"a":[["לא בביצה שאין בה אלא מימיה, כי אם \u0003בביצת אפרוח,\u0004 כלומר, בביצה שכבר היה בה אפרוח, שכיון שהוא בשר הריהו נותן טעם, \u0003אבל\u0004 ביצה \u0003טמאה\u0004 סתם (ביצת עוף טמא, האסורה באכילה) שאין בה אפרוח — \u0003לא\u0004 נותנת טעם במתבשל עימה, ואינה אוסרתו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב אידי בר אבין לאביי ממה ששנינו בברייתא: \u0003ביצים טהורות\u0004 (כשרות לאכילה) \u0003ששלקן\u0004 (בישל אותן) \u0003עם ביצים טמאות\u0004 (אסורות באכילה), \u0003אם יש בהן\u0004 (בביצים האסורות) כשיעור שיש בו \u0003בנותן טעם\u0004 בביצים הכשרות — \u0003כולן אסורות.\u0004 הרי איפוא שאף ביצים סתם, בלא אפרוח, נותנות טעם! השיב לו אביי: אין זו שאלה, שכן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בביצת אפרוח. ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 התנא \u0003לה\u0004 לביצה האסורה באכילה בכינוי \u0003\"טמאה\",\u0004 אף שהיא באה מעוף טהור? \u0003כיון דאית\u0004 \u0005[שיש]\u0006 \u0003בה אפרוח,\u0004 לכך \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה \"טמאה\",\u0004 שמחמת האפרוח הריהי אסורה באכילה.","ושואלים על תירוץ זה: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה בסופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003ביצים ששלקן ונמצא אפרוח באחת מהן, אם יש בהן\u0004 בביצים הללו שיעור \u0003ב\u0004כדי שהאפרוח \u0003נותן טעם\u0004 בהן — \u0003כולן אסורות, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבראשה,\u0006 בתחילת אותה ברייתא\u0005],\u0006 באופן \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה אפרוח עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ואיסורה באכילה משום שהיא באה מעוף טמא!","ודוחים: לא, אין לדייק כן. כיון שאין סוף הברייתא בא כדין נפרד, אלא \u0003פירושי קא מפרש\u0004 \u0005[פירוש הוא שמפרש],\u0006 את ששנינו קודם. וכך יש לשנות את הברייתא: \u0003ביצים טהורות ששלקן עם ביצים טמאות, אם יש בהן בנותן טעם\u0004 — \u0003כולן אסורות, כיצד? כגון ששלקן ונמצא אפרוח באחת מהן.\u0004","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להעמיד את הברייתא, שסופה מפרש את תחילתה: \u0003דאי סלקא דעתך\u0004 \u0005[ש\u0006כן \u0005אם עולה על דעתך]\u0006 לומר כי \u0003רישא דלית\u0004 \u0005[ראשה,\u0006 תחילתה מדברת בביצה \u0005שאין]\u0006 \u0003בה אפרוח,\u0004 אלא הבאה מעוף טמא, אם כן יש לתהות: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ששנינו כבר כי ביצה זו \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה אפרוח,\u0004 הריהי \u0003אסורה\u0004 (ואוסרת את הביצים הטהורות, בנתינת טעם). ביצה \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה אפרוח, מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהריהי אוסרת?! אלא יש לומר שסוף הברייתא בא לפרש את ראשיתה, ולהעמידה בביצה הבאה מעוף טהור שיש בה אפרוח.","ודוחים הוכחה זו: \u0003אי משום הא, לא איריא\u0004 \u0005[אם משום כך,\u0006 ראיה זו בלבד, הסקנו כי סוף הברייתא מפרשת את תחילת הברייתא, \u0005אינו שייך],\u0006 שכן באותה מידה ניתן לומר כי \u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005סוף\u0006 הברייתא כדי \u0005לגלות\u0006 על \u0005התחלת\u0006 הברייתא\u0005],\u0006 ולומר שדווקא סוף הברייתא עוסקת בביצת אפרוח ולא תחילתה. וכדי \u0003שלא תאמר\u0004 כי \u0003רישא\u0004 \u0005[תחילת]\u0006 הברייתא מדברת בביצה \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה אפרוח, אבל\u0004 ביצה ש\u0003לית\u0004 \u0005[אין]\u0006 \u0003בה אפרוח\u0004 — הריהי \u0003שריא\u0004 \u0005[מותרת,\u0006 שאינה אוסרת את שאר הביצים\u0005],\u0006 לכך \u0003תנא סיפא דאית\u0004 \u0005[שנה\u0006 ב\u0005סוף\u0006 הברייתא במפורש שמדובר בביצה \u0005שיש]\u0006 \u0003בה אפרוח,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שתחילת\u0006 הברייתא\u0005]\u0006 עוסקת בביצה \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה אפרוח, ואפילו הכי אסירא\u0004 \u0005[כך\u0006 היא \u0005אסורה,\u0006 אוסרת\u0005].\u0006","ועוד בדרך ביטול איסור בהיתר. \u0003ההוא כזיתא תרבא דנפל בדיקולא דבשרא\u0004 \u0005[כזית אחד של חלב שנפל בתוך סיר של בשר],\u0006 \u0003סבר רב אסי\u0004 שיש \u0003לשעוריה במאי דבלע דיקולא\u0004 \u0005[לשער אותו,\u0006 את ההיתר הנמצא בתוך הסיר, \u0005בבשר ו\u0006\u0005במה שבלע הסיר\u0006 מהבשר שהתבשל בו\u0005],\u0006 \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרב אשי\u0004 בשאלה: \u0003אטו דהיתרא\u0004 \u0005[וכי של היתר]\u0006 בלבד \u0003בלע\u0004 הסיר, ואילו \u0003דאיסורא\u0004 \u0005[של איסור,\u0006 החלב\u0005]\u0006 \u0003לא בלע\u0004 הסיר?","ועוד מסופר, \u0003ההוא פלגא דזיתא דתרבא דנפל בדיקולא דבשרא\u0004 \u0005[חצי זית אחד של חלב שנפל בסיר של בשר],\u0006 ומאחר והיה בו כחצי זית בלבד, \u0003סבר מר בר רב אשי\u0004 כי די \u0003לשעוריה בתלתין פלגי דזיתא\u0004 \u0005[לשער אותו\u0006 לענין ביטולו \u0005בשלושים חצאי זיתים],\u0006 ולא בששים חצאי זיתים. \u0003אמר ליה אבוה\u0004 \u0005[לו אביו]\u0006 רב אשי: \u0003לאו אמינא לך\u0004 \u0005[וכי לא אמרתי לך]\u0006 \u0003לא תזלזל\u0004 \u0003בשיעורין\u0004 באיסורים מ\u0003דרבנן\u0004 \u0005[של חכמים]?\u0006 שאף חצי זית של איסור, גם כן יש להצריך פי ששים כדי לבטלו. \u0003ועוד, האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוחנן\u0004 כי \u0003חצי שיעור\u0004 הריהו \u0003אסור מן התורה\u0004 ולא מדברי חכמים בלבד. ולכך אין להתיר \u0003את הבשר שנפל בו חצי זית של חלב, אלא בזמן שיש בו פי ששים נגד חצי זית זה.\u0004","ועוד בדיני ביטול איסור בהיתר. \u0003אמר רב שמן בר אבא, אמר רב אידי בר אידי בר גרשם, אמר לוי בר פרטא, אמר ר' נחום, אמר ר' ביריים משום\u0004 (בשם) \u0003זקן אחד, ור' יעקב שמיה\u0004 \u0005[שמו],\u0006 \u0003דבי נשיאה אמרו\u0004 \u0005[בבית הנשיא היו אומרים]:\u0006 \u0003ביצה\u0004 האסורה באכילה שהתערבה \u0003בששים\u0004 ביצים — תערובת זו \u0003אסורה,\u0004 ואולם אם התערבה ביצת האיסור \u0003בששים ואחת\u0004 ביצים — התערובת \u0003מותרת.\u0004","\u0003אמר ר' זירא לרב שמן בר אבא: ראה\u0004 (שים לב לדבריך) \u0003שאתה מטיל\u0004 (קובע) \u0003בה\u0004 בתערובת זו מהו \u0003גבול היתר,\u0004 בששים ואחת ביצים. ואולם לא פירשת בדבריך אם ששים ואחת אלה כוללים את ביצת האיסור או שאינם כוללים אותה. \u0003שהרי שני גדולי הדור\u0004 דנו בדבר זה, והם \u0003לא פירשו את הדבר.\u0004 ומיהם שני גדולי הדור הללו? \u0003ר' יעקב בר אידי ור' שמואל בר נחמני, תרוייהו משמיה\u0004 \u0005[שניהם משמו]\u0006 של \u0003ר' יהושע בן לוי אמרי\u0004 \u0005[אומרים]\u0006 כך: \u0003ביצה\u0004 של איסור שהתערבה \u0003בששים\u0004 ביצים — התערובת \u0003אסורה,\u0004 ביצה של איסור שהתערבה \u0003בששים ואחת\u0004 ביצים — התערובת \u0003מותרת.\u0004","\u0003ואיבעיא להו\u0004 \u0005[ונשאלה להם]\u0006 השאלה למה הכוונה \u0003בששים ואחת,\u0004 האם \u0003בהדי דידה\u0004 \u0005[יחד איתה],\u0006 עם ביצת האיסור, \u0003או דילמא לבר מינה\u0004 \u0005[שמא חוץ ממנה]?\u0006 \u0003ולא פשיט\u0004 \u0005[פתרו]\u0006 את הבעיה, \u0003ומר פשיט לה מפשט\u0004 \u0005[ואדוני אומר כדבר פתור,\u0006 הפשוט וברור, \u0005אותה,\u0006 את הבעיה הזו\u0005],\u0006 שעשוי שמדבריך משמע שהכוונה לששים ואחת כולל ביצת האיסור. שהרי לא אמרת שיש ספק בדבר!","ובענין זה מביאים נוסח הוראה מוגדר, \u0003אתמר\u0004 \u0005[נאמר],\u0006 שכך \u0003אמר ר' חלבו, אמר רב הונא: ביצה\u0004 של איסור שהתערבה \u0003בששים\u0004 ביצים \u0003והיא\u0004 — התערובת \u0003אסורה,\u0004 ואולם אם התערבה \u0003בששים ואחת\u0004 ביצים \u0003והיא\u0004 — התערובת \u0003מותרת.\u0004","ועוד בדיני ביטול איסור בתערובת היתר. \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003רבן גמליאל בר רבי,\u0004 ובידו דבר איסור בשיעור חצי זית שהתערב בהיתר. \u0003אמר לו\u0004 רבן גמליאל לאותו אדם: אף לפני \u0003אבא\u0004 (רבי) בא מעשה כזה, והוא \u0003לא שיער ב\u0004היתר אלא פי \u0003ארבעים ושבע\u0004 כנגד האיסור, והתיר על סמך זאת. \u0003ו\u0004אף \u0003אני\u0004 מתיר לך תערובת זו, אף ש\u0003אשער ב\u0004היתר שבה רק פי \u0003ארבעים וחמש\u0004 כנגד האיסור.","ובדומה לזה מסופר, \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003ר' שמעון בר רבי,\u0004 ובידו תערובת איסור והיתר. \u0003אמר לו\u0004 ר' שמעון בר רבי לאותו אדם: אף לפני \u0003אבא\u0004 (רבי) בא מעשה שכזה, והוא \u0003לא שיער ב\u0004היתר אלא פי \u0003ארבעים וחמש\u0004 כנגד האיסור. \u0003ו\u0004אף \u0003אני\u0004 אתיר לך תערובת זו, אף ש\u0003אשער ב\u0004היתר שבה רק פי \u0003ארבעים ושלש\u0004 כנגד האיסור.","ועוד מסופר, \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003ר' חייא,\u0004 ובידו תערובת איסור והיתר. \u0003אמר לו\u0004 ר' חייא לאותו אדם: \u0003כלום\u0004 (האם) \u0003יש\u0004 בהיתר שבתערובת זו שיעור \u0003פי\u0004 \u0003שלשים\u0004 כנגד האיסור?","ודנים בדבריו: האם יש לומר כי \u0003טעמא דליכא\u0004 \u0005[הטעם\u0006 לאסור את התערובת הוא רק משום \u0005שאין]\u0006 בהיתר שיעור פי \u0003שלשים.\u0004 נגד האיסור. ואולם \u0003הא איכא\u0004 \u0005[הרי\u0006 אם \u0005יש]\u0006 שיעור פי \u0003שלשים\u0004 — \u0003משערין\u0004 אנו כן, ומתירים את התערובת? \u0003אמר ר' חנינא:\u0004 לא לשם דיוק ההלכה אמר ר' חייא כן, אלא \u0003גוזמא\u0004 (בהפרזה) אמר, שאפילו שלושים אין בה, ובוודאי לא שישים שאפשר יהיה להתיר.","ועוד בדין ביטול איסור בתערובת היתר. \u0003אמר ר' חייא בר אבא, אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: כל איסורין שבתורה\u0004 שבדקנום ואין הם נותנים טעם בהיתר, או אלה שאין אפשרות לבודקם אם נתנו טעם (כגון תערובת מין במינו) — הריהם בטלים \u0003בששים. אמר לפניו ר' שמואל בר רב יצחק: רבי, אתה אומר כן\u0004 בשמו של ר' יהושע בן לוי שאמר בשמו של בר קפרא? ואולם \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב אסי, אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: כל איסורין שבתורה\u0004 — בטלים \u0003במאה!\u0004","ומעירים: \u0003ושניהם לא למדוה\u0004 את ההלכה הזו \u0003אלא מ\u0004הכתוב \u0003\"זרוע בשלה\"\u0004 האמור בתורה בדין קרבנות הנזיר. שבין הקרבנות שהריהו מביא עם גמר נזירותו, מביא קרבן איל לשלמים. וקרבן זה נאכל לבעליו (ככל קרבן שלמים), מלבד זרוע האיל המונפת וניתנת לכהן לאכילה, וישראל אסור באכילתה. \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ולקח הכהן את הזרוע בשלה\u0004 מן האיל... והניף אותם הכהן תנופה לפני ה' קודש הוא לכהן\" (במדבר ו, יט—כ), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 על כתוב זה: \u0003\"בשלה\"\u0004"],["— \u0003אין \"בשלה\"\u0004 זו \u0003אלא שלימה,\u0004 שצריכה הזרוע הבשלה המונפת להיות שלימה. \u0003ר' שמעון בן יוחאי אומר: אין\u0004 הכתוב \u0003\"בשלה\"\u0004 בא \u0003אלא\u0004 להורות \u0003ש\u0004הזרוע \u0003נתבשלה עם האיל\u0004 כולו.","ומעתה דנים במחלוקת זו, \u0003דכולי עלמא בהדי\u0004 \u0005[לדעת הכל, יחד עם]\u0006 ה\u0003איל\u0004 הוא \u0003מבשל לה\u0004 \u0005[אותה,\u0006 את הזרוע\u0005],\u0006 ואולם בכך נחלקו, שכן \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]\u0006 כי בהתחלה הוא \u0003מחתך לה\u0004 \u0005[אותה]\u0006 את הזרוע מן \u0003האיל,\u0004 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 הוא \u0003מבשל לה\u0004 \u0005[אותה]\u0006 עם האיל באותה קדירה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון בן יוחאי, \u0005סבור]\u0006 כי בהתחלה הוא \u0003מבשל לה\u0004 \u0005[אותה]\u0006 את הזרוע עם האיל, \u0003והדר\u0004 \u0005[אחר כך]\u0006 הוא \u0003מחתך לה\u0004 \u0005[אותה]\u0006 מן האיל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בהתחלה הוא \u0003מחתך לה\u0004 \u0005[אותה]\u0006 את הזרוע מן האיל, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 הוא \u0003מבשל לה\u0004 \u0005[אותה],\u0006 \u0003מיהו\u0004 \u0005[ואולם],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון בן יוחאי, \u0005סבור]:\u0006 כי \u0003בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003איל\u0004 הוא \u0003מבשל לה\u0004 \u0005[אותה],\u0006 \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 כי \u0003בקדרה אחרת\u0004 הוא \u0003מבשל לה\u0004 \u0005[אותה].\u0006","ונסכם: \u0003ללישנא קמא\u0004 \u0005[ללשון הראשונה]\u0006 בהסבר מחלוקת חכמים ור' שמעון בן יוחאי, שלדעת הכל מבשלים את הזרוע עם האיל — \u0003אליבא\u0004 \u0005[לשיטתם]\u0006 ל\u0003דברי הכל\u0004 יש ללמוד מ\"זרוע בשלה\" דין ביטול איסור בהיתר. שהרי אף כאן התבשלה זרוע (האסורה באכילה למי שאינו כהן) עם איל השלמים (המותר לאכילה לבעליו, הישראליים), ולא נאסר בשר האיל בגלל הזרוע שהתבשלה אתו, ומשום שבטל טעמה. ואילו \u0003ללישנא בתרא\u0004 \u0005[ללשון אחרונה]\u0006 — רק \u0003אליבא\u0004 \u0005[לשיטתו]\u0006 של \u0003ר' שמעון בן יוחאי\u0004 יש ללמוד כן. שהרי לדעת חכמים בלשון זו, אין הזרוע מתבשלת עם בשר האיל.","ועתה נפרט במה נחלקו הדעות בשיעור ביטול נתינת טעם: שכן בזרוע יש בשר ועצמות, ואולם העצמות הן מרובות, ואילו הבשר הוא מועט. ומעתה, \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 שבטל הטעם \u0003בששים, סבר\u0004 \u0005[סבור]\u0006 כי \u0003בשר ועצמות\u0004 של הזרוע \u0003בהדי\u0004 \u0005[יחד עם]\u0006 \u0003בשר ועצמות\u0004 של \u0003האיל\u0004 \u0003משערינן\u0004 \u0005[משערים אנו],\u0006 \u0003והוה ליה\u0004 \u0005[והריהו]\u0006 \u0003בששים,\u0004 שכן שיערו חכמים שיש פי ששים בבשר ועצמות האיל נגד בשר ועצמות הזרוע. ואילו \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 ששיעור הביטול הוא \u0003במאה, סבר\u0004 \u0005[סבור]\u0006 כי \u0003בשר\u0004 הזרוע \u0003בהדי\u0004 \u0005[יחד עם]\u0006 \u0003בשר\u0004 האיל \u0003משערינן\u0004 \u0005[משערים אנו],\u0006 \u0003והוה ליה\u0004 \u0005[והריהו]\u0006 \u0003במאה,\u0004 שכן שיערו חכמים שבבשר האיל יש פי מאה מבשר הזרוע.","ושואלים: \u0003ומי ילפינן מינה\u0004 \u0005[והאם למדים אנו ממנה],\u0006 מבישול זרוע באיל נזיר הלכה כללית לשיעור ביטול איסור? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בהגדרת איל נזיר שנבלע בו מטעם הזרוע, ובכל זאת הריהו מותר באכילה למי שאינו כהן: \u0003זהו\u0004 מקרה של \u0003היתר\u0004 אכילה שהתירה התורה, \u0003הבא מכלל איסור.\u0004 וההדגשה \u0003\"זהו\"\u0004 מורה כי יש \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרים אחרים, בהם לא התירה התורה, ומעתה נשאל: \u0003מאי\u0004 \u0005[מה]\u0006 בא זה למעט? \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 \u0003כל איסורין\u0004 \u0003שבתורה,\u0004 שאינם בטלים כדרך שהזרוע בשלה בטלה. ולפיכך אין ללמוד מכאן לענין שיעור ביטול איסור!","\u0003אמר אביי\u0004 בתשובה: \u0003לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 הדגשה ממעטת זו \u0003אלא ל\u0004דעת \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 כי בתערובת איסור והיתר \u0003מין במינו\u0004 — \u0003לא בטיל\u0004 \u0005[בטל]\u0006 האיסור כלל, בכל שיעור \u0003שהוא. לכך\u0004 התנא שבברייתא \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003דהכא\u0004 \u0005[שכאן],\u0006 בזרוע בשלה שהתבשלה עם האיל, אף שהיא תערובת מין במינו, האיסור \u0003בטיל\u0004 \u0005[בטל].\u0006","ושואלים: ולשיטת ר' יהודה שאין ביטול בתערובת מין במינו, \u0003וליגמר מיניה\u0004 \u0005[ושילמד ממנו,\u0006 מזרוע בשלה\u0005]\u0006 שגם מין במינו בטל! ומשיבים: לדעת ר' יהודה \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 בנאמר בסדר עבודת הכהן הגדול ביום הכיפורים, שלאחר ששוחט את פר החטאת ואת שעיר החטאת ומזה מדמם בקודש הקדשים, נאמר \u0003\"ולקח מדם הפר ומדם השעיר\u0004 ונתן על קרנות המזבח\" (ויקרא טז, יח), ומתוך שהם ממשיכים להיקרא בשמם \"דם הפר ודם השעיר\", אף שדם הפר מרובה הרבה מדם השעיר, וצריך היה דם השעיר להתבטל בו, סימן הוא ש\u0003תרוייהו בהדי הדדי נינהו ולא בטלי\u0004 \u0005[שני\u0006 הדמים הללו \u0005הם ביחד,\u0006 שמערבב זה עם \u0005זה,\u0006 \u0005ו\u0006בכל זאת הם \u0005לא בטלים],\u0006 ומכאן ראיה שאין מין במינו בטל.","ושואלים: \u0003ומאי חזית דגמרית מהאיך, ליגמר מהאי\u0004 \u0005[ומה ראית שלמדת מכאן,\u0006 מהאמור בדם הפר ודם השעיר, והסקת שאין מין במינו בטל, \u0005למד מכאן,\u0006 מזרוע בשלה, ותסיק \u0005שמין במינו בטל\u0006\u0005]?\u0006 ומשיבים: דין זה שבזרוע \u0003בשלה,\u0004 שהתירה התורה לבשל דבר האסור באכילה (למי שאינו כהן) עם דבר המותר באכילה, \u0003חדוש הוא,\u0004 שהרי אין מבטלים איסור לכתחילה, \u0003ומחדוש לא גמרינן\u0004 \u0005[אין אנו למדים].\u0006","ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחידוש הוא, אף \u0003ל\u0004ענין ביטול איסור בשיעור \u0003מאה ו\u0004בשיעור \u0003ששים\u0004 (כשיטות השונות של חכמים) \u0003נמי לא ליגמר\u0004 \u0005[גם כן לא נלמד]!\u0006","ומשיבים: \u0003אטו אנן לקולא גמרינן\u0004 \u0005[וכי אנו להקל למדים]\u0006 מזרוע בשלה?! והרי \u0003לחומרא גמרינן\u0004 \u0005[להחמיר למדים אנו]\u0006 מכאן. שכן \u0003מדאורייתא ברובא בטיל\u0004 \u0005[מן התורה היה בטל ברוב]\u0006 סתם, ולא היה צריך לא מאה ולא שישים. ומחמירים אנו שיהא הביטול רק בשיעורים אלה.","\u0003רבא אמר\u0004 הסבר אחר בדברי הברייתא שבענין זרוע בשלה \"זהו היתר שבא לכלל איסור\": \u0003לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 הדגשה זו להורות לנו \u0003אלא ל\u0004ענין \u0003טעם כעיקר,\u0004 שהטעם נחשב כמו עיקר האיסור עצמו, ש\u0003בקדשים\u0004 טעם איסור שנבלע בהיתר הריהו \u0003אסור,\u0004 והיה מקום לומר שאף זרוע הבשלה שנתנה טעם באיל תאסור אותו בכך, לכך \u0003קא משמע לן דהכא שרי\u0004 \u0005[הוא משמיע לנו שכאן\u0006 במקרה הזה שלנו \u0005הוא\u0006 \u0005מותר].\u0006"],["ושואלים על דברי רבא: \u0003וליגמר מיניה\u0004 \u0005[ושנלמד ממנו]\u0006 מהכתוב ב\"זרוע בשלה\" אף לענין שאר קדשים שנאסרו, שהתבשלו בהיתר אם יש בהיתר פי ששים או פי מאה, שיבטלו את האיסור! ומשיבים: \u0003גלי רחמנא גבי\u0004 \u0005[גילתה התורה אצל]\u0006 הנאמר בקרבן \u0003חטאת \"כל אשר יגע בבשרה יקדש\"\u0004 (ויקרא ו, כ) — ללמדנו שכל הנוגע בה, ובלע ממנה, הרי נעשה \u0003להיות כמוה, שאם פסולה\u0004 היא החטאת באחד מפסולי הקדשים — \u0003תפסל\u0004 גם החתיכה הנוגעת בה, \u0003ואם כשרה\u0004 היא החטאת — \u0003תאכל\u0004 אותה חתיכה שבלעה, \u0003כ\u0004דין ה\u0003חמור שבה\u0004 שבין שני הקרבנות הללו.","ושואלים: \u0003ומאי חזית דגמרינן מהאיך, ליגמר מהאי\u0004 \u0005[ומה ראית שלומדים\u0006 דין טעם כעיקר בקדשים, ולאסור \u0005מ\u0006פסוק \u0005זה\u0006 האמור בחטאת, \u0005למד מ\u0006כתוב \u0005זה\u0006 האמור בזרוע בשלה, ולהתיר\u0005]?\u0006 ומשיבים: \u0003חדוש הוא\u0004 בזרוע בשלה, \u0003ומחדוש לא גמרינן\u0004 \u0005[אין אנו לומדים].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שחידוש הוא ואין למדים ממנו, אף \u0003ל\u0004ענין ביטול איסורים בשיעור \u0003מאה ו\u0004כן בשיעור \u0003ששים\u0004 (לשיטות השונות של חכמים) \u0003נמי לא ליגמר\u0004 \u0005[גם כן לא נלמד]!\u0006 ומשיבים: \u0003אטו אנן\u0004 \u0003לקולא קא גמרינן\u0004 \u0005[וכי אנו להקל אנו לומדים]\u0006 מזרוע בשלה?! והרי \u0003לחומרא קא גמרינן\u0004 \u0005[להחמיר אנו לומדים],\u0006 \u0003דמדאורייתא ברובא בטיל\u0004 \u0005[ש\u0006הרי \u0005מן התורה ברוב\u0006 בלבד הוא \u0005בטל],\u0006 ואנו למדים מכאן להוסיף עד שישים או מאה. ומביאים עוד הסבר בדברי הברייתא שבענין זרוע בשלה \"זהו היתר שבא לכלל איסור\".","\u0003רבינא אמר:\u0004 \u0003לא נצרכא\u0004 אמירה זו להורות לנו \u0003אלא ל\u0004ענין \u0003מקום חתך\u0004 הזרוע מן האיל. שכן ככלל \u0003אמר\u0004 החכם כי \u0003מקום חתך בעלמא\u0004 \u0005[בסתם]\u0006 איסור והיתר שהיו מחוברים זה לזה, ונחתך האיסור מן ההיתר שמקום החתך \u0003אסור.\u0004 \u0003ו\u0004אילו \u0003הכא שרי\u0004 \u0005[כאן,\u0006 בזרוע בשלה הנחתכת מהאיל, \u0005מותר].\u0006","ושבים לבירור דברי רב שמואל בר רב יצחק שאמר כי בכל איסורים שבתורה, אין ההיתר שבלע מן האיסור מותר אלא אם כן יש בו פי מאה כנגד האיסור. ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[והיה אומר את אותה הלכה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004כי \u0003כל איסורין שבתורה\u0004 בטלים \u0003במאה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003למה\u0004 (אימתי) \u0003אמרו\u0004 חכמים כי \u0003כל המחמץ\u0004 עיסת חולין על ידי שהכניס לתוכה שאור של תרומה, \u0003ו\u0004כן ה\u0003מתבל\u0004 תבשיל של חולין בתבלין של תרומה, \u0003ו\u0004כן ה\u0003מדמע\u0004 (מערב) תרומה בחולין, שבכל אלה יש \u0003להחמיר\u0004 — הרי זה אמור בתערובת חולין ותרומה דווקא של \u0003מין ומינו.\u0004 ואימתי אמרו שיש \u0003להקל ולהחמיר\u0004 — הרי זה בתערובת \u0003מין ושאינו מינו.\u0004","\u0003וקתני סיפא\u0004 \u0005[ושנינו\u0006 ב\u0005סופה]\u0006 של אותה משנה, וכהסבר לדברים שנשנו בה מקודם: הנהגה זו של \u0003להקל ולהחמיר\u0004 השנויה בתערובת \u0003מין ושאינו מינו, כיצד\u0004 היא? \u0003גריסין\u0004 של תרומה \u0003שנתבשלו עם העדשים\u0004 של חולין. \u0003אם יש בהם\u0004 בגריסים הללו שיעור \u0003ב\u0004כדי שיהא \u0003נותן טעם\u0004 בעדשים, \u0003בין יש בהן\u0004 בעדשים כדי \u0003להעלות\u0004 (לבטל) \u0003במאה ואחד, בין אין בהן להעלות במאה ואחד\u0004 — \u0003אסור\u0004 הכל להיאכל כחולין, וזה שאינו כהן אינו יכול לאוכלו. והרי זה \"להחמיר\" — שאסור הדבר אף שיש בחולין פי מאה כנגד התרומה.","ואולם אם \u0003אין בהן\u0004 בגריסים \u0003בנותן טעם\u0004 בעדשים, \u0003בין שיש בהן להעלות במאה ואחד, בין אין בהן להעלות במאה ואחד\u0004 — \u0003מותר.\u0004 והרי זה \"להקל\" — שמותר הדבר אף שאין בחולין כדי שיעור ביטול במאה.","ויש לשאול: זה ששנינו שכאשר אין התרומה נותנת בהם טעם, אף ש\u0003אין בהן להעלות במאה ואחד,\u0004 החולין מותרים, \u0003אלא במאי\u0004 \u0005[במה],\u0006 באיזה שיעור בטלה התרומה? \u0003לאו\u0004 \u0005[האם לא]\u0006 שהיא בטלה \u0003בששים,\u0004 ושלא כדברי רב שמואל \u0003בר רב יצחק!\u0004"],["השיב רב דימי על שאלת אביי: \u0003לא,\u0004 אין הכוונה לביטול בששים, אלא לביטול \u0003במאה.\u0004","שאל אביי: אם כן כיצד ניתן להסביר את סוף הברייתא, \u0003והא מדרישא\u0004 \u0005[והרי מתוך שראשה,\u0006 תחילתה\u0005]\u0006 של הברייתא, בדינו של מין במינו שמחמירים בו, עוסקת בביטול \u0003במאה, הוי סיפא\u0004 \u0005[הרי\u0006 מכאן נסיק \u0005כי\u0006 \u0005סופה]\u0006 של הברייתא שמדובר בה במין בשאינו מינו, הוא בביטול \u0003בששים,\u0004 שבזה יש להבחין בין ראשית הברייתא שמחמירים בה, לבין סוף הברייתא שיש בה צד להקל. \u0003דקתני רישא\u0004 \u0005[ש\u0006כן \u0005שנויה תחילת\u0006 הברייתא\u0005]:\u0006 \u0003להחמיר מין ומינו, כיצד? שאור של חטין\u0004 של תרומה \u0003שנפל לעיסת\u0004 (בצק) \u0003חטין\u0004 של חולין, והרי זו איפוא תערובת מין במינו, \u0003ויש בו\u0004 בשאור זה \u0003שיעור\u0004 \u0003כדי לחמץ\u0004 את העיסה — \u0003בין יש בו\u0004 בבצק שיעור \u0003כדי להעלות\u0004 (לבטל) את השאור \u0003במאה ואחד, בין אין בו\u0004 שיעור שיש בו \u0003כדי להעלות\u0004 את השאור \u0003במאה ואחד,\u0004 בצק העיסה \u0003אסור.\u0004","וכיוצא בדבר, אם \u0003אין בו\u0004 בבצק העיסה שיעור שיש בו כדי \u0003להעלות\u0004 את השאור \u0003במאה ואחד, בין שיש בו\u0004 בשאור \u0003כדי לחמץ\u0004 את העיסה, \u0003בין\u0004 אם \u0003אין בו כדי לחמץ\u0004 את העיסה — בצק העיסה \u0003אסור,\u0004 משמע ש\u0003רישא וסיפא\u0004 \u0005[תחילתה וסופה]\u0006 עוסקים בביטול \u0003במאה!\u0004","השיב רב דימי: \u0003לא,\u0004 אין לדייק כך בדברי הברייתא, שכן יש מקום לומר כי \u0003רישא\u0004 \u0005[תחילת\u0006 הברייתא\u0005]\u0006 המחמירה בדין במין במינו, עוסקת בביטול \u0003במאה וחד\u0004 \u0005[ואחד],\u0006 \u0003ו\u0004אילו \u0003סיפא\u0004 \u0005[סוף\u0006 הברייתא\u0005]\u0006 המקילה בדין במין שאינו במינו, עוסקת בביטול \u0003במאה.\u0004 שאלו אביי: אם כדבריך שתחילת הברייתא עוסקת בביטול במאה ואחד של היתר, כיצד זה אומרת הברייתא שאם היה בשאור כדי לחמץ את העיסה אוסר אותה בכך, אף בשיעור של מאה ואחד.","ומעתה יש לתמוה, \u0003וכי יש\u0004 אפשרות שכזו שיהיה \u0003בו\u0004 בשאור \u0003כדי לחמץ\u0004 עיסה \u0003ב\u0004שיעור כה גדול של \u0003מאה וחד\u0004 \u0005[ואחד]\u0006 — מסתבר שלא, ואם כן \u0003אמאי לא בטיל\u0004 \u0005[מדוע אינו בטל\u0006 השאור\u0005]?\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב דימי, שלא היתה בידו תשובה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב דימי: יש לך לומר כי \u0003דלמא שאני\u0004 \u0005[שמא שונה,\u0006 מיוחד משאר איסורים\u0005]\u0006 הוא ה\u0003שאור\u0004 שיכולת \u0003חימוצו קשה\u0004 (חזק ביותר), ולכך עשוי הוא שיחמיץ אף עיסה שיש בה מאה ואחד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי לאביי: עתה \u0003אדכרתן מילתא\u0004 \u0005[הזכרתני דבר\u0006 הלכה\u0005]\u0006 ש\u0003אמר ר' יוסי בר' חנינא\u0004 בדין ביטול איסורים: \u0003לא כל השיעורין\u0004 לענין ביטול איסורים \u0003שוין, שהרי ציר\u0004 (רוטב) היוצא מדג האסור באכילה, שהתערב בהיתר, \u0003שיעורו\u0004 הוא \u0003קרוב ל\u0004פי \u0003מאתים\u0004 של היתר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דג טמא, צירו אסור.\u0004 ובכמה הוא מתבטל — \u0003ר' יהודה אומר:\u0004 שיעור \u0003רביעית\u0004 של ציר הדג בטל \u0003בסאתים\u0004 של היתר, שיש בהן קרוב למאתיים רביעיות (ובדיוק, מאה תשעים ושתים רביעיות).","\u0003ושואלים\u0004 : \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהודה\u0004 כי תערובת איסור בהיתר של \u0003מין במינו לא בטיל\u0004 \u0005[לא בטל]\u0006 האיסור, וכיצד בטל הציר? ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד משאר איסורים\u0005]\u0006 הוא ה\u0003ציר,\u0004 שכן \u0003זיעה בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא,\u0004 שאינו ממש דבר מן הדג עצמו, ולכך הריהו בטל, אף לשיטת ר' יהודה, אפילו במינו.","שנינו במשנתנו שירך שהתבשלה עם גיד הנשה שבתוכה אסורה אם הגיד נתן בה טעם. והסבירה המשנה \u0003כיצד משערינן\u0004 \u0005[משערים אנו]\u0006 אם יש בה טעם גיד? — כבשר בלפת. ובהסבר דברי המשנה הללו \u0003אמר רב הונא:\u0004 הכוונה היא \u0003כבשר\u0004 שמתבשל \u0003ב\u0004קדירה עם \u0003ראשי\u0004 ה\u0003לפתות.\u0004 ואומרים עוד בהסבר משנתנו כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 האומרת שגיד הנשה נותן טעם בדבר שהתבשל עמו, היא ש\u0003לא כ\u0004שיטת \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: אין בגידין בנותן טעם\u0004 כלל.","ומספרים \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003ר' חנינא\u0004 לשאול שאלה בדינה של ירך שהתבשלה עם גיד הנשה שבתוכה. \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ר' יהודה בר זבינא אבבא\u0004 \u0005[בשער]\u0006 ביתו של ר' חנינא. \u0003כי נפק\u0004 \u0005[כאשר יצא]\u0006 אותו אדם מלפני ר' חנינא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה בר זבינא לאותו אדם, בשאלה: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר לך\u0004 ר' חנינא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שריא ניהליה\u0004 \u0005[התיר לי]\u0006 את הירך באכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה בר זבינא לאותו אדם: \u0003הדר עייליה לקמיה\u0004 \u0005[חזור\u0006 ו\u0005הכנס\u0006 את השאלה הזו \u0005לפניו]\u0006 שמא לא בדק יפה! לכשבא אותו אדם שוב לפני ר' חנינא, \u0003אמר\u0004 ר' חנינא: \u0003מאן האי דקא מצער לי\u0004 \u0005[מיהו זה שמצער אותו]?\u0006 \u0003זיל אימא ליה למאן דיתיב אבבא\u0004 \u0005[לך אמור לו למי שיושב בשער]\u0006 כי \u0003אין בגידין בנותן טעם.\u0004 ולכך, די להשליך את גיד הנשה, והשאר מותר.","ומספרים עוד בענין זה, \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' אמי\u0004 בשאלה על ירך שהתבשלה עם גיד הנשה, \u0003משדר להו לקמיה\u0004 \u0005[היה שולח אותם לפני]\u0006 \u0003ר' יצחק בן חלוב, דמורי\u0004 \u0005[שהיה מורה]\u0006 \u0003בה להיתירא\u0004 \u0005[להיתר]\u0006 \u0003משום\u0004 (בשם) \u0003ר' יהושע בן לוי, וליה לא סבירא ליה\u0004 \u0005[ו\u0006אילו \u0005הוא עצמו,\u0006 ר' אמי, \u0005לא היה סבור כן],\u0006 אבל לא היה רוצה לאסור לאדם אחר, ולכן שלח אותו לחכם המתיר. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003אין בגידין בנותן טעם.\u0004","שנינו במשנתנו כי \u0003גיד הנשה שנתבשל\u0004 עם גידים של היתר, ואין הוא מכיר את גיד הנשה בתוכם, שנאסרו בכך כל הגידים (אף שיש בהם כדי לבטל טעמו של גיד הנשה). ושואלים: \u0003וליבטול ברובא\u0004 \u0005[ושיתבטל\u0006 הגיד \u0005ברוב]!\u0006"],["ומשיבים: גיד הנשה הריהו \u0003בריה\u0004 (דבר שלם לעצמו), \u0003ו\u0004\u0003שאני\u0004 \u0005[שונה]\u0006 דינה של בריה משאר איסורים, שאין היא בטילה ברוב.","\u0003ו\u0004עוד שנינו במשנתנו כי בדומה לדין גיד הנשה שהתבשל עם גידים המותרים באכילה, \u0003כן\u0004 הוא דינה של \u0003חתיכה של\u0004 בשר \u0003נבלה\u0004 שהתבשלה עם חתיכות בשר המותרות באכילה. שאם הוא מכיר את החתיכה האסורה, הריהו מוציאה מן התערובת, ואין היא אוסרת את שאר התבשיל אלא אם כן היה בה כדי לתת בו טעם. ושואלים: \u0003ותבטיל ברובא\u0004 \u0005[ותיבטל\u0006 חתיכת בשר האיסור ברוב ההיתר שהתבשל עימה\u0005]!\u0006","\u0003הניחא למאן דאמר\u0004 \u0005[זה נוח,\u0006 אין זו שאלה, \u0005לשיטת מי שאומר]\u0006 כי \u0003כל\u0004 דבר \u0003שדרכו לימנות\u0004 (להימנות. שלפעמים מונים כל יחידה שבו לעצמה) \u0003שנינו\u0004 בו שכל דבר כזה מוגדר כדבר חשוב, ולכך אינו מתבטל ברוב. ואף חתיכות בשר, מאחר שלפעמים הן נימנות כל אחת לעצמה, הריהן נחשבות כדבר חשוב, ולכך אינה מתבטלת. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי דווקא \u0003את\u0004 זה \u0003שדרכו\u0004 תמיד \u0003לימנות שנינו\u0004 שרק זה נחשב דבר חשוב, שאינו מתבטל ברוב. אבל דבר שרק לעיתים מונים אותו לעצמו, הריהו מתבטל ברוב. ואם כן חתיכת בשר זו, שלא תמיד היא נמנית לעצמה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 מדוע אין היא בטילה ברוב? ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא דינה של \u0003חתיכה\u0004 בשר, משום שהיא נחשבת דבר חשוב, שאינו בטל ברוב, \u0003הואיל וראויה\u0004 היא \u0003להתכבד בה לפני האורחים. ו\u0004מסבירים:","\u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר ההלכה שאין חתיכת בשר נבילה בטילה, וכן נצרכה להיאמר ההלכה שאין גיד הנשה בטל, ולא היה די בהשמעת אחת מהן. משום \u0003דאי אשמעינן\u0004 \u0005[שאם\u0006 התנא \u0005היה משמיע לנו]\u0006 דין זה רק ב\u0003גיד\u0004 הנשה — היינו אומרים שהרי זו הלכה בגיד הנשה בלבד, \u0003משום\u0004 ש\u0003בריה היא, אבל חתיכה\u0004 של בשר נבילה, שאינה בריה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שהריהי בטילה ברוב.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 דין זה רק ב\u0003חתיכה,\u0004 הייתי אומר שאינה מתבטלת — \u0003הואיל וראויה להתכבד בה לפני האורחים, אבל גיד\u0004 הנשה, שאין ראוי להתכבד בו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כך הוא דינו, והריהו בטל ברוב. לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר ההלכה בשני המקרים.","ועוד בדיני ביטול ברוב של חתיכת איסור שהתבשלה עם חתיכות היתר, \u0003דרש רבה בר בר חנה: חתיכה של\u0004 בשר \u0003נבלה, ו\u0004כן חתיכה \u0003של דג טמא,\u0004 שהתבשלה עם חתיכות היתר, אם מזהה את החתיכה האסורה ומסירה מן התבשיל — \u0003אינה אוסרת\u0004 את התערובת, \u0003עד שתתן טעם ברוטב\u0004 (המיצים היוצאים מחתיכות הבשר והדגים והמתבשל עימן) \u0003ובקיפה\u0004 (פירורים ותבלינים, כבצל ושום, הניתנים בתבשיל להשבחת טעמו) \u0003ובחתיכות.\u0004","ונמסר כי \u0003אוקי\u0004 \u0005[העמיד]\u0006 \u0003רב\u0004 בבית המדרש \u0003אמורא עליה\u0004 \u0005[מתורגמן עליו,\u0006 לפניו\u0005],\u0006 שיחזור על דבריו בקול רם לפני הרבים, להודיע שאין הלכה כדעת רבה בר בר חנה, \u0003ו\u0004כך \u0003דרש\u0004 רב: \u0003כיון שנתן\u0004 האיסור \u0003טעם בחתיכה\u0004 האחרת של היתר שהתבשלה עימה לבדה — אותה \u0003חתיכה עצמה נעשת נבלה\u0004 (ונעשית אסורה לעצמה) \u0003ו\u0004אם תתבשל חתיכה זו עם חתיכות אחרות, הריהי \u0003אוסרת\u0004 את \u0003כל החתיכות כולן, מפני שהן מינה\u0004 של חתיכת ההיתר, ולכך אין היא מתבטלת בהן. ודנו חכמים בדברי רב אלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לאביי: מכדי\u0004 \u0005[הרי]\u0006 \u0003רב כ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[את הלכתו]\u0006 זו? \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 בדיני ביטול ברוב, ש\u0003אמר\u0004 כי \u0003מין\u0004 איסור שהתערב \u0003ב\u0004היתר שהוא \u0003מינו\u0004 — \u0003לא בטיל\u0004 \u0005[אינו בטל],\u0006 אולם אם כן, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע אמר רב את הלכתו זו \u0003כי\u0004 \u0005[כאשר,\u0006 באופן\u0005]\u0006 שהתבשלו חתיכות האיסור וההיתר יחד ו\u0003נתן טעם\u0004 האיסור בהיתר? והרי \u0003אפילו כי\u0004 \u0005[כאשר]\u0006 לא התבשלו החתיכות יחד אלא רק התערבו \u0003לא נתן טעם\u0004 \u0003נמי\u0004 \u0005[גם כן],\u0006 לדעת ר' יהודה אין האיסור מתבטל! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב ספרא בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בשקדם וסלקו\u0004 את האיסור ממקום בישולו, ושוב אין חתיכת האיסור מעורבת עם חתיכות ההיתר. ולכך, אם הספיקה חתיכת האיסור לתת טעם בהיתר — הרי החתיכה שנתנה בה טעם נאסרת, ואוסרת אחרות. ואם לא הספיקה לתת טעם בהיתר — אין ההיתר נאסר.","\u0003רבא אמר\u0004 הסבר אחר לשיטתו זו של רב:"],["\u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שאמר רב את דבריו באופן זה ש\u0003לא קדם וסלקו\u0004 את חתיכת האיסור מן הקדירה לפני שנתן בה את חתיכות ההיתר, בכל זאת שאר החתיכות אסורות, כי \u0003הוי\u0004 \u0005[הרי זה]\u0006 המקרה שלפנינו תערובת \u0003מין ומינו\u0004 (החתיכה הנבילה וחתיכת ההיתר שבלעה ממנה) \u0003ודבר אחר\u0004 (התבלין והרוטב).","\u0003ו\u0004\u0003כלל הוא כי ב\u0004\u0003כל\u0004 תערובת שיש בה \u0003מין ומינו ודבר אחר\u0004 שאינו ממינו — \u0003סלק את מינו,\u0004 וראה אותו \u0003כמי שאינו\u0004 לפנינו, \u0003ו\u0004אותו דבר ההיתר \u0003שאין\u0004 הוא מ\u0003מינו\u0004 של דבר האיסור — אם הוא \u0003רבה עליו, ו\u0004הרי הוא \u0003מבטלו.\u0004 ובמקרה שלפנינו, אף שחתיכת הנבילה כשלעצמה היתה יכולה להתבטל ברוטב ובתבלין, ואולם מאחר שהיא אסרה את חתיכת ההיתר בבליעתה (לפני שעדיין לא התרבו בתבשיל התבלינים והרוטב), הרי הן מעתה כשתי \u0003חתיכות נבילה, ואינן מתבטלות.\u0004","איסור גיד הנשה \u0003נוהג\u0004 דווקא \u0003ב\u0004בהמה ובחיה \u0003טהורה, ואינו נוהג ב\u0004בהמה ובחיה \u0003טמאה.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 איסור גיד הנשה נוהג \u0003אף בטמאה.\u0004 ו\u0003אמר ר' יהודה\u0004 בטעם דבריו: \u0003והלא\u0004 כבר \u0003מ\u0004זמנם של \u0003בני יעקב\u0004 אבינו \u0003נאסר גיד הנשה,\u0004 וכמבואר בתורה בעקבות מלחמת יעקב במלאך \"על כן לא יאכלו בני ישראל את גיד הנשה\" (בראשית לב, לב), \u0003ו\u0004באותה עת \u0003עדיין בהמה טמאה\u0004 היתה \u0003מותרת להן\u0004 לישראל, ונאסר מאז גם גיד הנשה של הבהמה (והחיה) הטמאה. \u0003אמרו לו\u0004 חכמים לר' יהודה: איסור גיד הנשה בעת מתן תורה \u0003בסיני נאמר,\u0004 ואף הכתוב \"על כן לא יאכלו בני ישראל את גיד הנשה\" נאמר אז, \u0003אלא שנכתב במקומו,\u0004 במלחמת יעקב, אבל לא שהאיסור התחיל באותם הזמנים.","שנינו במשנתנו כי נחלקו חכמים בדין גיד הנשה בבהמה ובחיה הטמאה, שלדעת ר' יהודה נוהג איסור זה אף בטמאה. ומשמע כי לדעת ר' יהודה האוכל גיד הנשה של הטמאה חייב משום איסור גיד הנשה, מלבד שחייב משום אכילת טמא? ושואלים על כך: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003איסור חל על איסור,\u0004 ולכך איסור גיד הנשה חל על הדבר שאסור כבר באכילה משום טומאה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: יכול תהא\u0004 אכילת \u0003נבלת עוף טמא מטמא\u0004 את ה\u0003בגדים\u0004 שעל האדם האוכל בזמן שהיא נמצאת \u0003בבית הבליעה\u0004 שלו, וכדין האוכל נבלת עוף טהור?","\u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"נבלה וטרפה לא יאכל לטמאה בה\"\u0004 (ויקרא כב, ח) — להורות כי אין טומאה זו נוהגת אלא ב\u0003מי שאיסורו\u0004 הוא \u0003משום \"בל תאכל נבלה\", יצא זה\u0004 (עוף טמא) \u0003שאין איסורו משום \"בל תאכל נבלה\", אלא משום \"בל תאכל טמאה\"!\u0004 הרי שלדעת ר' יהודה אין איסור חל על איסור, וכיצד חל איסור גיד הנשה בדבר שיש עליו איסור בהמה טמאה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בהסבר שיטת ר' יהודה כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003אין בגידין בנותן טעם,\u0004 שהריהם יבשים כעץ, ואינם בכלל מאכל, \u0003ו\u0004לכך \u0003בטמאה נמי\u0004 \u0005[גם כן],\u0006 \u0003איסור גיד\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 בה, שהרי האיסור הזה הוא איסור לעצמו, שאינו כשאר איסורי אכילה האמורים דווקא בדבר הנאכל, ואולם \u0003איסור\u0004 אכילת דבר \u0003טומאה\u0004 — \u0003ליכא\u0004 \u0005[אין\u0006 כאן\u0005],\u0006 משום שגיד הנשה הוא דבר שאין בו טעם. ואולם האם אכן","\u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003אין בגידין בנותן טעם? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003האוכל גיד הנשה של בהמה טמאה\u0004 — \u0003ר' יהודה מחייב שתים\u0004 (שתי סדרות של מלקות), \u0003ור' שמעון פוטר.\u0004 משמע שדעת ר' יהודה היא שיש בגיד בנותן טעם! ומשיבים:","\u0003לעולם\u0004 תאמר ש\u0003קסבר\u0004 \u0005[סבור הוא\u0006 ר' יהודה\u0005]\u0006 כי \u0003יש בגידין בנותן טעם,\u0004 אלא \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שאיסור גיד הנשה \u0003נוהג\u0004 גם \u0003ב\u0004שלב שבו בעל החיים הוא \u0003שליל,\u0004 ומעתה, \u0003איסור גיד ואיסור טומאה בהדי הדדי קאתי\u0004 \u0005[ביחד,\u0006 זה עם זה, \u0005הם באים].\u0006","ושואלים: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 שלדעת ר' יהודה איסור זה \u0003נוהג בשליל, והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה שבראש פרקנו\u0005]\u0006 שלדעת חכמים גיד הנשה \u0003נוהג בשליל,\u0004 ואילו \u0003ר' יהודה אומר\u0004 ש\u0003אינו נוהג בשליל,\u0004 \u0003אלא משעת לידה,\u0004 \u0003ו\u0004כן \u0003חלבו\u0004 של השליל \u0003מותר!\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 בשיטת ר' יהודה אמורים דווקא \u0003גבי\u0004 \u0005[אצל]\u0006 בהמה \u0003טהורה, דרחמנא אמר\u0004 \u0005[ש\u0006כן \u0005התורה אמרה]:\u0006 \"ו \u0003כל... בבהמה\u0004 אותה \u0003תאכלו\"\u0004 (דברים יד, ו) — ללמדנו שכל מה שיש בתוך בעל החיים הטהור הנשחט (ובכלל זה העובר), מותר באכילה, ובכלל זה אף גיד הנשה שבשליל. \u0003אבל בטמאה נוהג\u0004 איסור גיד הנשה אף בשליל.","ושואלים על הסבר זה בשיטת ר' יהודה: \u0003ומי מצית אמרת דתרוייהו בהדי הדדי קאתו\u0004 \u0005[והאם יכול אתה לומר ששניהם,\u0006 איסור טומאה ואיסור גיד הנשה, \u0005ביחד,\u0006 זה עם זה \u0005הם באים],\u0006 שהם נוצרים באותה עת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003על אלו טומאות\u0004 מת \u0003הנזיר\u0004 שנטמא \u0003מגלח\u0004 (וסותר את נזירותו, ומונה נזירות חדשה): \u0003על ה\u0004טומאה ב\u0003מת, ועל\u0004 הטומאה ב\u0003כזית\u0004 בשר \u0003מן המת.\u0004","\u0003וקשיא לן\u0004 \u0005[והיה קשה לנו]\u0006 כשלמדנו זאת: אם \u0003על כזית\u0004 בשר \u0003מן המת\u0004 הריהו \u0003מגלח, על ה\u0004טומאה ב\u0003מת כולו לא כל שכן\u0004 שהריהו מגלח, ומה טעם שנינו אף זאת? \u0003ואמר ר' יוחנן\u0004 בהסבר הדברים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא ל\u0004ענין ה\u0003נפל ש\u0004עדיין \u0003לא נתקשרו אבריו בגידין\u0004 והוא קטן מאד. שאין בכולו כזית בשר, ואולם כיון שהריהו יצור שלם הריהו מטמא באוהל כמת. ומכאן למדים אנו כי יצירת האיברים קודמת ליצירת הגידים. \u0003אלמא\u0004 \u0005[מכאן עולה]\u0006 ש\u0003איסור טומאה קדים\u0004 \u0005[קודם],\u0006 לאיסור גיד הנשה!","משיבים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003איסור טומאה קדים\u0004 \u0005[קודם]\u0006 לאיסור גיד הנשה, \u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור גיד\u0004 ו\u0003חייל עליה\u0004 \u0005[חל עליו].\u0006 וטעם הדבר, \u0003שכן איסורו\u0004 של גיד הנשה חמור ביותר, שהרי הוא \u0003נוהג\u0004 אפילו \u0003בבני נח.\u0004","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 הסבר זה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 במשנתנו, \u0003אמר ר' יהודה: והלא מבני יעקב נאסר גיד הנשה, ועדיין בהמה טמאה מותרת להם.\u0004 משמע שטעם שיטת ר' יהודה באיסור גיד הנשה אף בטמאה, הינו משום שהרי זה איסור חמור, שכן הוא נוהג גם בבני נח.","למעלה הובאה מחלוקת ר' יהודה ור' שמעון בדין האוכל גיד הנשה של בהמה טמאה, ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[גופה,\u0006 עצמה\u0005].\u0006 שנינו: \u0003האוכל גיד הנשה של בהמה טמאה\u0004 — \u0003ר' יהודה מחייב שתים,\u0004"],["\u0003ור' שמעון פוטר\u0004 ממלקות, שאינו לוקה אף לא על אחד מאיסורים אלה.","\u0003ו\u0004דנים בשיטת \u0003ר' שמעון: מה נפשך\u0004 \u0005[מה רצונך,\u0006 באיזה אופן נסביר את דבריו\u0005]?\u0006 שכן \u0003אי\u0004 \u0005[אם]\u0006 הוא סבור שיש בגידים בנותן טעם, וכמו כן הריהו סבור ש\u0003איסור חל על איסור\u0004 — על האוכל גיד הנשה זה להתחייב סדרת מלקות אחת על אכילת בהמה טמאה, וכן \u0003ליחייב נמי\u0004 \u0005[שיחייב גם כן]\u0006 סדרת מלקות נוספת \u0003משום\u0004 אכילת \u0003גיד\u0004 הנשה. ואף \u0003אי\u0004 \u0005[אם]\u0006 ר' שמעון סבור ש\u0003אין איסור חל על איסור\u0004 — \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 מלקות לפחות \u0003משום\u0004 אכילת דבר \u0003טומאה דקדים\u0004 \u0005[שקדם]\u0006 איסור זה לאיסור גיד הנשה. \u0003ואי\u0004 \u0005[ואם]\u0006 סבור ר' שמעון ש\u0003אין בגידין בנותן טעם,\u0004 ומשום כך אין הוא מתחייב מלקות על אכילת הגיד משום בשר בהמה טמאה — \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 מלקות \u0003משום\u0004 אכילת \u0003גיד\u0004 הנשה, שאסרה התורה את אכילתו אף שאין בו טעם!","\u0003אמר רבא\u0004 בהסבר שיטת ר' שמעון: \u0003לעולם\u0004 תפרש כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' שמעון ש\u0003אין בגידים בנותן טעם, ו\u0004חייב אדם על אכילת גיד הנשה של בעל חיים טהור, אף שאין בו בנתינת טעם. ואולם \u0003שאני התם\u0004 \u0005[ושונה,\u0006 מיוחד הוא \u0005שם,\u0006 דין גיד הנשה בבהמה טמאה\u0005]\u0006 \u0003דאמר קרא\u0004 \u0005[ש\u0006כן \u0005אמר הכתוב]:\u0006 \u0003\"על כן לא יאכלו בני ישראל את גיד הנשה\"\u0004 (בראשית לב, לב), ללמד: רק \u0003מי שגידו אסור\u0004 באכילה \u0003ובשרו מותר\u0004 באכילה, הוא זה שחל בו איסור גיד הנשה, \u0003יצתה\u0004 (יצאה) \u0003זו\u0004 הבהמה הטמאה, שאם נאסור את אכילת גיד הנשה שבה, יימצא איפוא בעל חיים זה \u0003ש\u0004גם \u0003גידו אסור ו\u0004גם \u0003בשרו אסור,\u0004 ושלא כהגדרת איסור גיד הנשה.","מקודם שנינו מחלוקתם של חכמים בדין האוכל גיד הנשה של בהמה טמאה, ועתה מביאים ממה ש\u0003אמר רב יהודה, אמר רב\u0004 במחלוקתם של חכמים בדין \u0003האוכל גיד הנשה של\u0004 בהמה טהורה שהיא \u0003נבלה\u0004 ובשרה אסור באכילה. ש\u0003ר' מאיר מחייב\u0004 את האוכל גיד הנשה שלה \u0003שתים\u0004 (שתי סדרות של מלקות), כמי שעבר על שני איסורים, אכילת גיד הנשה ואכילת בשר נבילה, \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 ש\u0003אינו חייב אלא\u0004 סדרת מלקות \u0003אחת,\u0004 ומשום אכילת גיד הנשה. ואולם על אכילת בשר נבילה אינו חייב, שכן אין איסור חל על איסור.","\u0003ו\u0004אולם \u0003מודים חכמים לר' מאיר ב\u0004דין ה\u0003אוכל גיד הנשה של\u0004 בהמת קרבן \u0003עולה ושל שור הנסקל, ש\u0004הוא \u0003חייב שתים.\u0004 שכן מחמת חומרת איסור אכילת עולה ושור הנסקל (שאסורים הם אף בהנאה) חל גם איסור אכילה על גיד הנשה שלהם.","ושואלים: \u0003ומאן האי\u0004 \u0005[ומיהו זה]\u0006 ה\u0003תנא\u0004 הסבור שאמנם \u0003באיסור כולל\u0004 (באופן שבו האיסור המאוחר מקיף יותר מהאיסור הראשון) — \u0003איסור חל על איסור לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור כן\u0005],\u0006 ואולם האם \u0003איסור כולל,\u0004 שיחול גם איסור גיד הנשה מתוך שחל עליו איסור חמור של עולה או שור הנסקל, כמו במקרה שלפנינו, \u0003באיסור חמור\u0004 באופן שבו האיסור המאוחר חמור מהאיסור הראשון) \u0003אית ליה\u0004 \u0005[יש לו],\u0006 שהוא סבור שאיסור חל על איסור?","\u0003אמר רבא:\u0004 שיטת \u0003ר' יוסי הגלילי היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת זבחים\u0005]:\u0006 אדם \u0003טמא שאכל\u0004 בשר \u0003קדש, בין\u0004 שהיה זה \u0003קדש טמא בין\u0004 שהיה זה \u0003קדש טהור\u0004 — הריהו \u0003חייב\u0004 כרת אם עשה זאת במזיד, וקרבן עולה ויורד אם עשה זאת בשוגג.","ואילו \u0003ר' יוסי הגלילי אומר:\u0004 אדם \u0003טמא שאכל את\u0004 בשר קודש \u0003הטהור\u0004 — \u0003חייב,\u0004 אבל אדם \u0003טמא שאכל את\u0004 בשר קודש \u0003הטמא\u0004 — \u0003פטור,\u0004 כיון \u0003שלא אכל אלא דבר טמא.\u0004","\u0003אמרו לו\u0004 חכמים, החולקים עליו: לשיטתך, \u0003אף טמא שאכל את הטהור\u0004 יהיה פטור, שהרי \u0003כיון שנגע בו\u0004 בבשר הקודש, \u0003טמאהו\u0004 בכך, ונמצא שאוכל דבר טמא!","ושואלים: \u0003שפיר קא אמרי ליה רבנן\u0004 \u0005[יפה אמרו לו חכמים]\u0006 \u0003לר' יוסי הגלילי,\u0004 ומה הוא משיב על כך? \u0003ואמר\u0004 על כך \u0003רבא:\u0004 אכן באופן שבו \u0003נטמא\u0004 \u0003טומאת\u0004 \u0003הגוף\u0004 (שנטמא האדם), \u0003ואחר כך נטמא בשר\u0004 הקודש — \u0003כולי עלמא לא פליגי דחייב\u0004 \u0005[הכל,\u0006 ואף ר' יוסי הגלילי בכלל, \u0005אינם חולקים ש\u0006הוא \u0005חייב],\u0006 שכן \u0003איסור\u0004 אכילת בשר הקודש בטומאת הגוף איסור חמור הוא שעונשו \u0003כרת,\u0004 שכבר \u0003קדים\u0004 \u0005[קדם]\u0006 וחל איסור זה, ושוב אין הוא פוקע גם אם נטמא הקודש.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו\u0006 חכמים ור' יוסי הגלילי\u0005]\u0006 הרי זה \u0003ב\u0004מקרה ש\u0003נטמא\u0004 ה\u0003בשר\u0004 קודם ונאסר באכילה, \u0003ואחר כך נטמא הגוף.\u0004 ואלה טעמיהם: \u0003רבנן אית להו\u0004 \u0005[חכמים יש להם,\u0006 הריהם סבורים\u0005]\u0006 שאף שבכלל אין איסור חל על איסור, הרי כאן איסור אכילת קדשים בטומאת הגוף — \u0003איסור כולל\u0004 הוא, \u0003דמגו דמיחייב\u0004 \u0005[שמתוך ש\u0006הוא \u0005מתחייב]\u0006 באיסור זה על \u0003חתיכות\u0004 בשר \u0003טהורות דעלמא\u0004 \u0005[בכלל],\u0006 הריהו \u0003מיחייב נמי\u0004 \u0005[מתחייב גם כן]\u0006 על \u0003חתיכה\u0004 של בהמה \u0003טמאה. ו\u0004אילו","\u0003ר' יוסי הגלילי לית ליה\u0004 \u0005[אין לו]\u0006 סברה זו האומרת שאיסור חל על איסור גם כשיש בו \u0003איסור כולל,\u0004 משום שלדעתו \u0003\"מגו\" לא אמרינן\u0004 \u0005[\"מתוך\" אין אנו אומרים].\u0006","\u0003ו\u0004תוהים על שיטת \u0003ר' יוסי הגלילי: נהי\u0004 \u0005[אם אמנם]\u0006 שלדעתו \u0003איסור כולל לית ליה\u0004 \u0005[אין לו,\u0006 אין הוא מקבל\u0005],\u0006 ואולם מכל מקום \u0003באיסור קל\u0004 יש לומר ש\u0003יבא איסור חמור יחול על איסור קל, ומאי ניהו\u0004 \u0005[ומי הוא]\u0006 איסור חמור זה? — \u0003טומאת הגוף, שהרי טומאת הגוף\u0004 היא \u0003ב\u0004עונש \u0003כרת,\u0004 ותחול על האיסור הקל שבאכילת טומאת בשר!","\u0003אמר רב אשי\u0004 בתשובה: \u0003מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 ש\u0003טומאת הגוף חמורה\u0004 יותר, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003טומאת בשר חמורה\u0004 יותר, שאף שעונשה אינו גדול כעונש טומאת הגוף, מכל מקום יש בה צד חומרה שאין בטומאת הגוף: \u0003דלית ליה\u0004 \u0005[שאין לה]\u0006 לטומאה זו אפשרות של \u0003טהרה\u0004 באמצעות טבילה \u0003במקוה.\u0004 מה שאין כן בטומאת הגוף, שיש לה טהרה."],["ושואלים: \u0003ו\u0004האם \u0003ר' יוסי הגלילי לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שאיסור חל על איסור כאשר האיסור השני הוא \u0003איסור כולל?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 חלו \u0003שבת ויום הכפורים\u0004 באותו יום (שזו וזה אסורים במלאכה), ו\u0003שגג ועשה מלאכה\u0004 ביום זה, \u0003מנין ש\u0004הוא \u0003חייב\u0004 קרבן חטאת \u0003על זה בעצמו ועל זה בעצמו? תלמוד לומר\u0004 (לכך נאמר) במצות יום השבת \"כל מלאכה לא תעשו \u0003שבת היא\u0004 לה' בכל מושבותיכם\" (ויקרא כג, ג), ובא הלשון \"היא\" להורות שהריהי עומדת לעצמה, אף כשחל בה יום אחר האסור במלאכה. וכן ביום הכפורים נאמר \u0003\"יום הכפורים הוא\"\u0004 (שם כז), שאף הוא עומד לעצמו ומצוותיו עמו, גם כאשר חל בשבת שהיא אסורה במלאכה. אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 שכן אין איסור חל על איסור. הרי שר' יוסי הגלילי סבור שאיסור חל על איסור במקרה של איסור כולל (כאיסור יום הכיפורים המכיל עניינים שאינם באיסור שבת, כאיסור אכילה ושתיה) ושל איסור מוסיף (כאיסור שבת המוסיף על איסור יום הכיפורים, שהרי איסור שבת עונשו במיתת בית דין, ואילו איסור יום כיפורים עונשו בכרת)! ומשיבים: בעניינה של משנה זו כבר","\u0003שלח רבין משום\u0004 (בשם) \u0003ר' יוסי בר' חנינא\u0004 ואמר כי בודאי \u0003כך\u0004 הוא \u0003הצעה של משנה\u0004 זו, שאין שיבוש במשנה זו בשיטות בהלכה השנויות בה, \u0003ו\u0004אולם \u0003איפוך\u0004 \u0005[הפוך]\u0006 את שמות החכמים החלוקים בה. שהדעה המיוחסת במשנה לר' יוסי הגלילי היא של ר' עקיבא, ואילו הדעה המיוחסת בה לר' עקיבא היא דעתו של ר' יוסי הגלילי. ונמצא לפי זה שסבור ר' יוסי הגלילי כי אין איסור חל על איסור אף באיסור כולל ומוסיף.","למעלה הובאו דברי ר' יוסי הגלילי, ודנים עוד בדבריו. \u0003שלח רב יצחק בר יעקב בר גיורי משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוחנן: לדברי ר' יוסי הגלילי, למאי דאפכן\u0004 \u0005[למה,\u0006 לאופן זה \u0005שהפכנו]\u0006 את שמות החכמים שבברייתא, אם אדם עשה מלאכה בשבת שחל בה יום הכיפורים, וכגון ש\u0003שגג בשבת,\u0004 ששכח ששבת היא, \u0003ו\u0004אולם \u0003הזיד ביום הכפורים\u0004 (שידע שיום זה הוא יום הכיפורים, ואסור הוא במלאכה) — הריהו \u0003חייב\u0004 קרבן חטאת. אבל אם עשה מלאכה ביום זה ובאופן ש\u0003הזיד בשבת,\u0004 שידע שהוא שבת ואסורה היא במלאכה, \u0003ו\u0004אולם \u0003שגג ביום הכפורים\u0004 — הריהו \u0003פטור\u0004 מקרבן חטאת.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר אביי: שבת קביעא וקיימא\u0004 \u0005[קבועה ועומדת],\u0006 והיא מתקדשת מעצמה, וקדמה קדושתה לקדושת \u0003יום הכפורים,\u0004 שאותו \u0003בי דינא דקא קבעי ליה\u0004 \u0005[בית הדין הוא שקובעים אותו].\u0006 שהרי הוא נקבע בהתאם לזמן שבו התקדש החודש על ידי חכמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 נימוק זה אינו מועיל, כי \u0003סוף סוף,\u0004 בפועל \u0003תרוייהו בהדי הדדי קאתו\u0004 \u0005[שתיהן,\u0006 קדושת שבת וקדושת יום הכיפורים, \u0005ביחד הן באות]\u0006 שהרי נקבע יום כיפור זה ביום השבת! \u0003אלא אמר רבא,\u0004 הטעם שאינו חייב אלא על חילול השבת: \u0003שמדא הוה\u0004 \u0005[\u0006זמן \u0005שמד היה]\u0006 זה, תקופה שהמלכות הטילה גזירות על קיום המצוות, \u0003ושלחו\u0004 חכמים \u0003מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]\u0006 הודעה זו: \u0003דיומא דכפורי דהא שתא\u0004 \u0005[שיום כיפור של שנה זו]\u0006 לא יחול בזמנו הראוי באותה שנה, באחד מימי אמצע השבוע, אלא ביום \u0003שבתא\u0004 \u0005[שבת]\u0006 \u0003הוא\u0004 יצויין. שינהגו ביום שבת כדרך שנוהגים ביום הכיפורים. ולכך זה שעשה מלאכה ביום זה, חייב רק משום שבת. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין וכל נחותי\u0004 \u0005[\u0006אלה \u0005היורדים]\u0006 שבאו מארץ ישראל לבבל, \u0003אמרוה\u0004 \u0005[פירשו אותה]\u0006 \u0003כ\u0004דעת \u0003רבא.\u0004","שנינו במשנתנו שנחלק ר' יהודה עם חכמים בדינו של גיד הנשה בטמאה, ו\u0003אמר ר' יהודה\u0004 לחכמים: \u0003והלא\u0004 כבר \u0003מ\u0004זמנם של \u0003בני יעקב\u0004 נאסר גיד הנשה, ובאותה עת היתה בהמה טמאה מותרת להם לאכילה. ומכאן שגיד הנשה נוהג אף בטמאה.","ומביאים עוד בענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו\u0004 חכמים \u0003לר' יהודה\u0004 בתשובה לדבריו: \u0003וכי נאמר \"על כן לא יאכלו בני יעקב\u0004 את גיד הנשה?\"\u0003והלא לא נאמר אלא\u0004 \"על כן לא יאכלו \u0003בני ישראל\u0004 את גיד הנשה\" (בראשית לב, לב), \u0003ולא נקראו \"בני ישראל\" עד\u0004 מתן תורה ב\u0003סיני! אלא\u0004 מלשון זו משמע שאיסור גיד הנשה רק משעת מתן תורה \u0003בסיני נאמר, אלא שנכתב במקומו\u0004 בספר בראשית, כדי \u0003לידע מאיזה טעם נאסר להם\u0004 לאחר מכן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על הנאמר בברייתא זו שלא נקראו \"בני ישראל\" לפני מתן תורה: והרי נאמר \u0003\"וישאו בני ישראל את יעקב אביהם\"\u0004 (בראשית מו, ה), והיה זה בשעת ירידת בני ישראל למצרים, ולפני מתן תורה! ומשיבים: ירידת בני ישראל למצרים היתה \u0003לאחר מעשה\u0004 זה שנאבק יעקב במלאך, ולאחר מכן קרא הקדוש ברוך הוא ליעקב בשם \"ישראל\", כנאמר \"שמך יעקב לא יקרא שמך עוד יעקב כי אם ישראל יהיה שמך\" (בראשית לה, י), ובניו הם איפוא בני ישראל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 מעתה, שבזמן ירידת בני ישראל למצרים החלו להיקרא בשם \"בני ישראל\", \u0003מההיא שעתא ליתסר\u0004 \u0005[מאותה שעה שיאסר\u0006 להם גיד הנשה\u0005],\u0006 ולא מזמן מתן תורה, ושלא כדעת חכמים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי בתשובה: \u0003וכי\u0004 ה\u0003תורה פעמים פעמים ניתנה,\u0004 ו\u0003ההוא שעתא\u0004 \u0005[אותה שעה]\u0006 של ירידת בני ישראל למצרים, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003שעת מעשה\u0004 (מאבקו של יעקב במלאך) \u0003הואי\u0004 \u0005[היתה],\u0006 \u0003ולא שעת מתן תורה הואי\u0004 \u0005[היתה],\u0006 ולכן אין סברה \u0003לומר שאז יתחיל האיסור.\u0004","במשנתנו שנינו מחלוקתם של חכמים בדין גיד הנשה בטמאה, ומביאים מחלוקת בענין דומה, באיסור אבר מן החי. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 איסור \u0003אבר מן החי נוהג בבהמה חיה ועוף, בין\u0004 \u0003טמאין ובין טהורין,\u0004 אלו \u0003דברי ר' יהודה ור' אלעזר. ו\u0004אילו \u0003חכמים אומרים: אינו נוהג אלא בטהורין.\u0004","\u0003אמר ר' יוחנן: ושניהן,\u0004 שתי הדעות החולקות, \u0003מקרא אחד דרשו,\u0004 שנאמר: \u0003\"רק חזק לבלתי אכול הדם כי הדם הוא הנפש,\u0004"],["והמשך הכתוב \u0003\"לא תאכל הנפש עם הבשר\"\u0004 (דברים יב, כג), ובכך נחלקו: \u0003ר' יהודה ור' אלעזר\u0004 האומרים שאיסור אבר מן החי נוהג אף בבעלי חיים טמאים, \u0003סברי\u0004 \u0005[סבורים]\u0006 שהכתוב מלמדנו ש\u0003כל\u0004 בעל חיים \u0003שאתה מצווה על דמו\u0004 שלא לאוכלו, כמו כן אף \u0003אתה מצווה על אבריו\u0004 מן החי שלא לאוכלם. \u0003והני\u0004 \u0005[ואלה]\u0006 בעלי החיים ה\u0003טמאין נמי\u0004 \u0005[גם כן],\u0006 \u0003הואיל ואתה מצווה על\u0004 אכילת \u0003דמן\u0004 — כמו כן הרי \u0003אתה מצווה על\u0004 אכילת \u0003אברין\u0004 מן החי של אלה.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 האומרים שאין איסור אבר מן החי נוהג אלא בבעלי חיים טהורים בלבד, \u0003סברי\u0004 \u0005[סבורים]\u0006 שהכתוב \u0003\"לא תאכל הנפש עם הבשר\"\u0004 כוונתו לומר שאין לאכול את בשר בעל החיים בעודו חי, כשעדיין נפש חיים בקרבו, \u0003אלא\u0004 יש לאוכלו כ\u0003בשר לחודיה\u0004 \u0005[לעצמו],\u0006 כשאין בו עוד נפש חיים. ומכאן נלמד: \u0003כל\u0004 בעל חיים \u0003שבשרו מותר\u0004 (לאחר שחיטה) — \u0003אתה מצווה על\u0004 אכילת \u0003אבריו\u0004 בעודו בחיים. \u0003וכל\u0004 בעל חיים \u0003שאין בשרו מותר\u0004 — \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מצווה על אבריו.\u0004","ושואלים: \u0003ו\u0004לדעת \u0003ר' יהודה,\u0004 הסבור שאיסור חל על איסור במקרה שהאיסור השני חמור מהאיסור הראשון, מעתה \u0003למה ליה קרא\u0004 \u0005[למה לו מקרא]\u0006 מיוחד ללמדנו שנוהג איסור אבר מן החי אף בטמאים, \u0003ליתי\u0004 \u0005[יבוא]\u0006 \u0003איסור אבר\u0004 מן החי \u0003ליחול\u0004 \u0005[שיחול]\u0006 \u0003על איסור טומאה\u0004 של בעל חיים טמא, \u0003שכן איסורו\u0004 של אבר מן החי חמור מאיסור אכילת טומאה, שכן הוא \u0003נוהג\u0004 אפילו \u0003בבני נח!\u0004","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך\u0006 הוא באמת, \u0005גם כן],\u0006 ולשיטת ר' יהודה אמנם אין אנו נזקקים ללימוד זה מן המקרא ללמדנו הלכה זו, \u0003וכי איצטריך קרא\u0004 \u0005[וכאשר נצרך המקרא]\u0006 ללמדנו כן, הרי זה \u0003ל\u0004שיטת \u0003ר' אלעזר,\u0004 שאינו סבור שאיסור חל על איסור בזמן שהאיסור השני חמור מן הראשון, ואולם אף הוא סבור שאיסור אבר מן החי חל על בעל החיים הטמא, ומשום מקרא זה.","ומביאים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שזו דרשתו של ר' אלעזר, ולא של ר' יהודה: איסור אכילת \u0003אבר מן החי נוהג בבהמה חיה ועוף, בין טמאה בין טהורה, שנאמר \"רק חזק לבלתי אכול הדם\"\u0004 (שם, שם) —","\u0003כל שאתה מצווה על\u0004 אכילת \u0003דמו, אתה מצווה על\u0004 אכילת \u0003אבריו\u0004 מן החי. \u0003וכל שאי\u0004 \u0005[שאין]\u0006 \u0003אתה מצווה על\u0004 אכילת \u0003דמו\u0004 — \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מצווה על\u0004 אכילת \u0003אבריו,\u0004 אלו \u0003דברי ר' אלעזר.\u0004","\u0003וחכמים אומרים: אינו נוהג אלא בטהורין, ש\u0004כן \u0003נאמר \"לא תאכל הנפש עם הבשר\", אלא\u0004 יש לאכול את ה\u0003בשר לחודיה\u0004 \u0005[לעצמו],\u0006 כשאין בו עוד נפש חיים \u0003כל שבשרו מותר\u0004 באכילה לאחר שחיטה — \u0003אתה מצווה על\u0004 אכילת \u0003אבריו\u0004 מן החי. \u0003וכל שאין בשרו מותר\u0004 באכילה לאחר שחיטה — \u0003אין אתה מצווה על\u0004 אכילת \u0003אבריו\u0004 מן החי.","\u0003ר' מאיר אומר:\u0004 איסור אבר מן החי \u0003אינו נוהג אלא בבהמה טהורה בלבד.\u0004","\u0003(סימן\u0004 לדברי החכמים, שדבריהם יובאו להלן, המסבירים את דעת ר' מאיר בדין אבר מן החי: \u0003שמואל, שילא, שימי).\u0004","\u0003אמר רבה בר שמואל אמר רב חסדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 גם באופן אחר ש\u0003אמר\u0004 זאת \u0003רבה בר שילא אמר רב חסדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בלשון זו: ש\u0003רבה בר שימי אמר\u0004 זאת בשם \u0003רב חסדא,\u0004 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר\u0004 הסבור שאיסור אבר מן החי נוהג רק בבהמה טהורה — שכן","\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וזבחת מבקרך ומצאנך\"\u0004 (דברים יב, כא), שהן בהמות טהורות. ולאחר מכן (שם בפסוק כג) נאמר איסור אבר מן החי, להורות שאיסור זה נוהג רק בבהמות טהורות.","למעלה הובאו שיטותיהם של חכמים החלוקים בדין אבר מן החי בטמאים, ומבררים את דבריהם. \u0003אמר רב גידל, אמר רב: מחלוקת\u0004 זו של חכמים ור' יהודה ור' אלעזר אם נוהג איסור אבר מן החי אף בטמאים, היא רק ביחס ל\u0003ישראל, אבל בבן נח\u0004 — ל\u0003דברי הכל\u0004 הריהו \u0003מוזהר על\u0004 אכילת אבר מן החי של \u0003הטמאין כ\u0004של ה\u0003טהורין.\u0004","ומביאים ראיה לדבר, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אבר מן החי\u0004 — \u0003בן נח מוזהר עליו על הטמאים כטהורים, וישראל אינו מוזהר אלא על הטהורין בלבד.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח ברייתא זו \"אלא על ה\u0003טהורה\u0004 בלבד\", \u0003ו\u0004הרי זו כשיטת \u0003ר' מאיר\u0004 הסבור שאיסור זה נוהג רק בבהמה טהורה. ו\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח הברייתא \u0003\"אלא על ה\u0004\u0003טהורים\u0004 בלבד\", \u0003ו\u0004הרי זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שנוהג איסור זה בכל הטהורים, ואף בחיות ובעופות.","\u0003אמר רב שיזבי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 במשנה\u0005]\u0006 שבן נח אסור באכילת אבר מן החי אף בבעל חיים טמא, שכן אמרו במשנה מי ש\u0003אכל אבר מן החי ממנה\u0004 (מן העוף הטמא) \u0003אינו סופג ארבעים\u0004 מלקות, \u0003ואין שחיטה מטהרתה.\u0004","ונברר: \u0003במאי\u0004 \u0005[במה]\u0006 ביחס למי המדובר במשנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003ב\u0004יחס לאדם מ\u0003ישראל\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר ש\u0003אין שחיטה מטהרתה,\u0004 שהרי היא אסורה. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 המדובר \u0003בבני נח, מכלל\u0004 \u0005[מכאן נסיק]\u0006 שבן נח \u0003אסור\u0004 באכילת אבר מן החי אף בבעל חיים טמא.","ועוד בבירור דברי משנה זו, \u0003ר' מני בר פטיש רמי רישא אסיפא\u0004 \u0005[השליך,\u0006 הראה סתירה בין דברי המשנה ב\u0005התחלה והסוף],\u0006 \u0003ומשני\u0004 \u0005[ו\u0006היה \u0005מתרץ]:\u0006 \u0003רישא\u0004 \u0005[תחילתה]\u0006 מדברת \u0003בישראל, וסיפא\u0004 \u0005[וסופה]\u0006 מדברת \u0003בבן נח,\u0004 וכשיטת חכמים.","ומביאים עוד בדיני אבר מן החי, \u0003אמר רב: אבר מן החי צריך\u0004 שיעור \u0003כזית\u0004 כדי שיעבור עליו. שגם אם אכל אבר שלם, כיון שאין בו שיעור כזית, אינו מתחייב על כך. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אכילה כתיבה ביה\u0004 \u0005[כתובה בו],\u0006 ואין אכילה אלא בשיעור כזית.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב עמרם\u0004 מדברי המשנה שהובאה למעלה: \u0003אכל אבר מן החי ממנה\u0004 (מעוף טמא זה) — \u0003אינו סופג את הארבעים, ואין שחיטה מטהרתה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בחיוב על אכילת אבר מן החי, שיאכל שיעור \u0003כזית,\u0004 מדוע ה\u0003אוכל פטור ממלקות,\u0004","\u0003והרי\u0004 \u0003תיפוק ליה דקאכל\u0004 \u0005[יצא לו\u0006 חיוב \u0005מלקות על שום\u0006 \u0005שהוא אכל]\u0006 \u0003כזית\u0004 מדבר טמא! ומשיבים: \u0003כ\u0004דרך ש\u0003אמר רב נחמן\u0004 בענין אחר, שמדובר כאן לא שהיה בזה כזית בשר, אלא \u0003במשהו בשר\u0004 והשאר \u0003גידין ועצמות\u0004 המשלימים לשיעור כזית. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שמדובר \u0003במשהו בשר,\u0004 ו\u0003גידין ועצמות\u0004 משלימים לשיעור כזית. ולכך אין כאן אכילה בשיעור כזית של דבר טמא.","ודנים בדברי רב יהודה בשמו של רב, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר רב:\u0004"],["מי ש\u0003אכל צפור טהורה\u0004 (ממין הכשר לאכילה), אם אכלה \u0003בחייה,\u0004 בלא שנשחטה — עובר אף \u0003ב\u0004אכילת שיעור \u0003כל שהוא\u0004 ממנה, משום איסור אבר מן החי. אם אכלה \u0003במיתתה\u0004 (שמתה בלא שנשחטה) — עובר עליה \u0003ב\u0004אכילת שיעור \u0003כזית. ו\u0004אם אכל ציפור \u0003טמאה,\u0004 ממין שאינו כשר, \u0003בין\u0004 שאכלה \u0003בחייה בין\u0004 שאכלה \u0003במיתתה\u0004 — חייב \u0003ב\u0004אכילת שיעור \u0003כל שהוא\u0004 ממנה, ומשום אכילת דבר טומאה. הרי שלדעת רב חייבים על אכילת אבר מן החי בשיעור כל שהוא, ושלא כדברי רב יהודה בשמו, שצריך שיעור כזית! ומשיבים: \u0003הכא\u0004 \u0005[כאן],\u0006 בדברי רב שחייבים על אכילה בשיעור כל שהוא \u0003נמי\u0004 \u0005[גם כן]\u0006 המדובר \u0003במשהו בשר,\u0004 אבל \u0003גידים ועצמות\u0004 משלימים את הבשר לשיעור כזית.","ומביאים עוד ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שלא כשיטת רב יהודה בשם רב: \u0003נטל צפור\u0004 חיה הכשרה לאכילה, \u0003שאין בו\u0004 כשיעור \u0003כזית, ואכלו\u0004 — \u0003רבי פוטר\u0004 ממלקות, שלא עבר זה על איסור אבר מן החי, שלדעתו אין עוף שלם בכלל \"אבר\". \u0003ו\u0004אילו ר' אלעזר בר ר' שמעון מחייב, \u0003שלדעתו העוף השלם נחשב כ\"אבר\", אף שאין בו שיעור כזית, ומתחייב עליו בכך.\u0004 ו\u0003אמר ר' אלעזר בר' שמעון\u0004 בהסבר שיטתו \u0003:\u0004 \u0003קל וחומר\u0004 הוא, אם \u0003על אבר ממנה\u0004 מעוף זה — הריהו \u0003חייב, על כולה\u0004 — \u0003לא כל שכן!\u0004 ואם \u0003חנקה\u0004 (המית את העוף שלא בשחיטה), והריהו עתה נבילה, \u0003ואכלה\u0004 — ל\u0003דברי הכל\u0004 (ואף לדעת ר' אלעזר בר' שמעון) אינו חייב אלא \u0003ב\u0004שיעור \u0003כזית,\u0004 וכדין האוכל מבשר הנבילה. ומעתה נדון בדברים:","\u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 רבי ור' אלעזר בר' שמעון \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אלעזר בר' שמעון, \u0005סבור]\u0006 כי כל בעל חיים, כבהמה וכעוף, כבר \u0003בחייה ל\u0004בתירת \u0003אברים\u0004 היא \u0003עומדת,\u0004 שכל אבר ואבר שבה, מוגדר כבר אז כ\"אבר\". \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]\u0006 כי \u0003בחייה לאו\u0004 \u0005[לא]\u0006 \u0003לאברים\u0004 היא \u0003עומדת.\u0004","ואולם \u0003דכולי עלמא מיהא לא בעינן\u0004 \u0005[לדעת הכל על כל פנים אין אנו צריכים]\u0006 שיעור \u0003כזית\u0004 כדי לחייב על אכילת אבר מן החי, ושלא כשיטת רב יהודה בשם רב! \u0003אמר רב נחמן\u0004 בדחיית הראיה: דברי ברייתא זו אמורים בציפור שיש בה רק \u0003משהו בשר,\u0004 ומשלימים ה\u0003גידים ועצמות\u0004 לשיעור כזית.","ותוהים על הסבר זה: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר\u0006 כזה\u0005],\u0006 \u0003דבכוליה לית ביה\u0004 \u0005[שבכל\u0006 היצור \u0005כולו אין בו]\u0006 \u0003כזית בשר, ובחד אבר אית\u0004 \u0005[ובאבר אחד יש]\u0006 \u0003כזית\u0004 המורכב \u0003ב\u0004צירוף של \u0003משהו בשר\u0004 ו\u0003גידין ועצמות? אמר רב שרביא: אין\u0004 \u0005[כן],\u0006 \u0003בקלניתא\u0004 שהוא עוף רזה מאד.","ומקשים על העמדת דברי הברייתא בקלניתא: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]\u0006 ששנינו בה שאם \u0003חנקה ואכלה\u0004 — \u0003דברי הכל\u0004 הריהו עובר \u0003בכזית, והא\u0004 \u0005[והרי]\u0006 \u0003קלניתא עוף טמא הוא, ו\u0004בענין זה \u0003אמר רב:\u0004 ציפור \u0003טמאה, בין בחייה בין במיתתה\u0004 עובר \u0003במשהו! אלא\u0004 יש לומר שאין המדובר בקלניתא ממש (שהוא עוף טמא), אלא בעוף טהור שהוא \u0003כעין קלניתא,\u0004 שהריהו רזה ביותר.","שנינו למעלה מחלוקתם של רבי ור' אלעזר בר' שמעון בדינו של האוכל ציפור טהורה שלימה שאין בה כזית, שרבי פוטרו ממלקות על איסור אבר מן החי, שכן אין עוף שלם נקרא \"אבר\", ואילו ר' אלעזר בר' שמעון מחייבו. ובשיטת רבי \u0003אמר רבא: אם תמצא לומר\u0004 (אם נניח) ש\u0003סבר רבי\u0004 כי \u0003מחשבת אוכלין\u0004 (מחשבה שאדם חשב לאכול דבר שאין דרכו להיאכל) \u0003שמה מחשבה\u0004 (שייחשב זה לדבר מאכל), מעתה אם בתחילה \u0003חישב\u0004 אדם \u0003לאוכלה\u0004 לציפור זו בחייה \u0003אבר אבר, ו\u0004לבסוף לא עשה כן אלא \u0003אכלה כולה\u0004 כאחת — אף לשיטת רבי, הוא \u0003חייב\u0004 על אכילה זו משום אבר מן החי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא בשאלה: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר],\u0006 ש\u0003אילו אכיל ליה\u0004 \u0005[אוכל אותו]\u0006 אדם \u0003אחר\u0004 (שלא חשב לאוכלה אבר אבר) — ההוא \u0003לא מיחייב\u0004 \u0005[אינו מתחייב]\u0006 בכך. \u0003ו\u0004אם \u0003אכיל ליה האי\u0004 \u0005[אוכל אותו\u0006 אדם \u0005זה]\u0006 (שחשב לאוכלה), הריהו \u0003מיחייב\u0004 \u0005[מתחייב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 רבא בתשובה: אין זו תמיהה, שכן \u0003זה\u0004 מתחייב \u0003לפי מחשבתו\u0004 (שחשב לאוכלה אבר אבר), \u0003וזה\u0004 נפטר \u0003לפי מחשבתו\u0004 (שחשב לאוכלה בשלמותה).","\u0003ו\u0004כן \u0003אמר רבא\u0004 בשיטת ר' אלעזר בר' שמעון: \u0003אם תמצא לומר\u0004 (אם נניח) ש\u0003סבר ר' אלעזר בר ר' שמעון\u0004 כי \u0003מחשבת אוכלין שמה מחשבה,\u0004 מעתה, אם \u0003חישב לאוכלה\u0004 לציפור זו כשהיא \u0003מתה, ו\u0004לבסוף \u0003אכלה\u0004 כשהיא \u0003חיה\u0004 — הריהו \u0003פטור\u0004 מאיסור אבר מן החי, שכן לפי מחשבתו אין הציפור עומדת לנתיחת אבריה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא בשאלה: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר],\u0006 ש\u0003אילו אכיל ליה\u0004 \u0005[אוכל אותו]\u0006 אדם \u0003אחר\u0004 (שחשב לאוכלה בחייה) הרי הוא \u0003מחייב\u0004 \u0005[מתחייב]\u0006 בכך, \u0003ואכיל ליה האי\u0004 \u0005[ואוכל אותו\u0006 אדם \u0005זה]\u0006 (שחשב בתחילה לאוכלה לאחר מותה), והריהו \u0003פטור\u0004 (אף שלבסוף אכלה כשהיא חיה)? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: אין זו תמיהה, שכן \u0003זה\u0004 מתחייב \u0003לפי מחשבתו, וזה\u0004 נפטר \u0003לפי מחשבתו.\u0004","למעלה נדון איסור אבר מן החי, ועתה מביאים דברי חכמים ביחס למקור איסור זה. \u0003אמר ר' יוחנן:\u0004 משמע הכתוב \u0003\"לא תאכל הנפש עם הבשר\"\u0004 (דברים יב, כג) — \u0003זה אבר מן החי,\u0004 שכן הריהו נקרא נפש שעודה עם הבשר (מצויה בבשר, בגוף החי). ואילו משמע הכתוב \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל) — \u0003זה בשר\u0004 היוצא \u0003מן החי\u0004 (כבשר שפרש מבעל חיים ונמצא \u0003בשדה),\u0004 \u0003ו\u0004כן \u0003בשר מן\u0004 בעל החיים \u0003הטרפה. ו\u0004אילו","\u0003ר' שמעון בן לקיש אמר:\u0004 משמע הכתוב \u0003\"לא תאכל הנפש עם הבשר\"\u0004 — \u0003זה אבר מן החי, ובשר מן החי.\u0004 ואילו משמע הכתוב \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 — \u0003זה בשר מן הטרפה.\u0004","ומעתה מבררים את הבדלי הדינים שבין שיטת ר' יוחנן ושיטת ריש לקיש: \u0003אכל אבר מן החי ובשר מן החי\u0004 — \u0003ל\u0004דעת \u0003ר' יוחנן\u0004 הריהו \u0003חייב שתים\u0004 (שתי סדרות מלקות), שהרי עבר על שני איסורים הנלמדים מכתובים שונים. ואילו \u0003ל\u0004דעת \u0003ר' שמעון בן לקיש אינו חייב אלא אחת,\u0004 שהרי לדעתו שני איסורים אלה נלמדים מכתוב אחד. ואם \u0003אכל בשר מן החי ובשר מן הטרפה\u0004 — \u0003ל\u0004דעת \u0003ר' שמעון בן לקיש\u0004 הריהו \u0003חייב שתים,\u0004 שכן אלה נלמדים מכתובים שונים, ואילו \u0003ל\u0004דעת \u0003ר' יוחנן אינו חייב אלא אחת.\u0004 אכן זה ש\u0003אכל אבר מן החי ובשר מן הטרפה\u0004 — \u0003לדברי הכל חייב שתים,\u0004 שלדברי הכל מקורם בשני כתובים שונים.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על מה ששנינו כי האוכל אבר מן החי ובשר מן הטריפה חייב שתים לדברי הכל, ממה ששנינו:"],["\u0003אכל אבר מן החי מן\u0004 הבהמה \u0003הטרפה\u0004 החיה — \u0003ר' יוחנן אמר:\u0004 הריהו \u0003חייב שתים\u0004 (שני סדרות מלקות), לפי שעבר על שני איסורים שונים, \u0003ו\u0004אילו \u0003ר' שמעון בן לקיש אמר: אינו חייב אלא אחת.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 הרי זה \u0003ניחא\u0004 \u0005[נוח]\u0006 מדוע הוא חייב שתי סדרות מלקות, שלשיטתו שני איסורים אלה נלמדים מכתובים שונים. \u0003אלא לר' שמעון בן לקיש\u0004 האומר כי אינו חייב אלא סדרה אחת של מלקות, \u0003קשיא\u0004 \u0005[קשה],\u0006 שהרי שנינו למעלה כי לדברי הכל באופן זה הריהו לוקה שתיים!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 — מדובר \u0003בבהמה אחת, כאן\u0004 מדובר — \u0003בשתי בהמות.\u0004 ומפרט רב יוסף את דבריו: האוכל אבר מן החי ובשר מן הטריפה \u0003בשתי בהמות,\u0004 שאכל מאחת אבר מן החי ומן האחרת בשר מן הטריפה, הריהו \u0003מיחייב\u0004 \u0005[חייב]\u0006 \u0003שתים\u0004 לדברי הכל. ואולם האוכל אבר מן החי ובשר מן הטריפה \u0003בבהמה אחת פליגי\u0004 \u0005[חלוקים]\u0006 בכך ר' יוחנן וריש לקיש.","ושואלים: ובזה האוכל את שני אלה \u0003בבהמה אחת, במאי פליגי\u0004 \u0005[במה,\u0006 בדיוק, הם \u0005חלוקים]?\u0006 \u0003אמר אביי: כגון שנטרפה\u0004 הבהמה בשעת לידתה, \u0003עם יציאת רובה\u0004 ממעי אמה. ובכך נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי ה\u0003בהמה\u0004 כבר \u0003בחייה,\u0004 עוד בטרם נלקח ממנה האבר, \u0003לאברים\u0004 (חתיכות) היא \u0003עומדת,\u0004 וחל עליה איסור אבר מן החי משעת לידתה. \u0003ו\u0004בהמה זו שנטרפה באותה שעה, \u0003איסור טרפה ואיסור אבר\u0004 מן החי \u0003בהדי הדדי קאתו\u0004 \u0005[זה עם זה הם באים],\u0006 וחלו שניהם, והתחייב האוכל בשתיים.","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003בהמה בחייה לאו\u0004 \u0005[לא]\u0006 \u0003לאברים עומדת,\u0004 ואין איסור אבר מן החי חל אלא כאשר נלקח אבר ממנה, \u0003ו\u0004מאחר וכבר היא אסורה באיסור טריפה, לכך \u0003לא אתי\u0004 \u0005[אין בא]\u0006 \u0003איסור אבר\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור טרפה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר את הסבר מחלוקת ר' יוחנן וריש לקיש: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בהמה בחייה לאו\u0004 \u0005[לא]\u0006 \u0003לאברים עומדת,\u0004 ואין איסור אבר מן החי חל אלא משעה שנלקח האבר מגוף החי, ונמצא איפוא כי איסור טריפה קודם לאיסור אבר מן החי, \u0003ו\u0004אולם \u0003במיתי\u0004 \u0005[בבואו]\u0006 של \u0003איסור אבר מיחל\u0004 \u0005[ויחול]\u0006 על \u0003איסור טרפה קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 שבכך נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' \u0005יוחנן,\u0006 \u0005סבור]\u0006 כי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור אבר\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור טרפה,\u0004 ולכך האוכל חייב שתיים. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003לא אתי\u0004 \u0005[אין בא]\u0006 \u0003איסור אבר\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור טרפה.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר למחלוקת ר' יוחנן וריש לקיש: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בהמה בחייה לאברים עומדת,\u0004 וחל איפוא \u0003איסור אבר מן החי משעת לידתה של הבהמה. ו\u0004מדובר כאן כשאיסור טריפה בא לאחר מכן, \u0003וכגון שנטרפה\u0004 הבהמה \u0003לאחר מכאן\u0004 (לאחר לידתה). \u0003ובמיתי\u0004 \u0005[ובבואו]\u0006 של \u0003איסור טרפה\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור אבר קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003אתי וחייל\u0004 \u0005[בא\u0006 איסור טריפה \u0005וחל]\u0006 על איסור אבר מן החי. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003לא אתי וחייל\u0004 \u0005[אינו בא וחל].\u0006","\u0003רבא אמר\u0004 הסבר אחר למחלוקת ר' יוחנן וריש לקיש: מדובר כאן \u0003כגון שתלש ממנה אבר וטרפה בו,\u0004 כלומר, בתלישה זו עשה אותה טריפה. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003בהמה בחייה לאברים אינה עומדת,\u0004 ולכן אין איסור אבר מן החי חל בה אלא משעה שנלקח האבר מגופה, ומעתה נמצא כי \u0003איסור אבר ואיסור טרפה בהדי הדדי קאתו\u0004 \u0005[זה עם זה הם באים],\u0006 וחלו שניהם, ולכך האוכל לוקה שתיים.","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003בהמה בחייה לאברים עומדת,\u0004 ולכן איסור אבר מן החי כבר חל עליה, \u0003ולא אתי\u0004 \u0005[ואין בא]\u0006 \u0003איסור טרפה\u0004 ו\u0003חייל\u0004 \u0005[חל]\u0006 על \u0003איסור אבר\u0004 מן החי.","ועוד בדין אכילת אבר מן החי, \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: אכל חלב\u0004 שנלקח \u0003מן\u0004 בעל החיים \u0003החי מן הטרפה\u0004 — הריהו \u0003חייב\u0004 על אכילה זו \u0003שתים,\u0004 שתי סדרות מלקות. שאף שיש כאן שלושה איסורי אכילה, אבר מן החי וחלב וטריפה, אינו חייב אלא על שנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי\u0004 לר' חייא בר אבא: \u0003ולימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 בשם ר' יוחנן שחייב \u0003שלש\u0004 סדרות מלקות, ומשום שלושת איסורים אלה, \u0003ש\u0004כן \u0003אני אומר\u0004 בגירסת שמועתו של ר' יוחנן שחייב \u0003שלש.\u0004 ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כגירסתו של ר' אמי, \u0003אמר ר' אבהו, אמר ר' יוחנן: אכל חלב מן החי מן הטרפה\u0004 — \u0003חייב שלש.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה ענין \u0005הם,\u0006 ר' חייא בר אבא ור' אמי, \u0005חלוקים],\u0006 אם לחייב את האוכל חלב מן החיה מן הטריפה שתים או שלוש? \u0003כגון שנטרפה\u0004 (נעשתה טריפה) \u0003עם יציאת רובה\u0004 (בשעת לידתה). \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שחייב \u0003שלש,\u0004 וכשיטת ר' אמי ור' אבהו — \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 כי \u0003בהמה\u0004 כבר \u0003בחייה ל\u0004בתירת \u0003אברים\u0004 היא \u0003עומדת,\u0004 שכל אבר ואבר שבה מוגדר כבר אז כ\"אבר\", ולכך \u0003איסור חלב ואיסור אבר ואיסור טרפה בהדי הדדי קאתו\u0004 \u0005[זה עם זה,\u0006 ביחד, \u0005הם באים],\u0006 וחלים שלושתם.","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שחייב האוכל \u0003שתים\u0004 בלבד, וכשיטת ר' חייא בר אבא — \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 כי \u0003בהמה בחייה לאו\u0004 \u0005[לא]\u0006 \u0003לאברים עומדת, ו\u0004לכן \u0003איסור חלב ואיסור טרפה\u0004 — \u0003איכא\u0004 \u0005[יש],\u0006 אבל \u0003איסור אבר\u0004 — \u0003לא אתי חייל\u0004 \u0005[אינו בא וחל]\u0006 על שני איסורים אלה, שחל רק משעה שפרש האבר מגוף הבהמה, ולכך אין לוקים עליו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר במחלוקת חכמים אלה: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בהמה בחייה לאו\u0004 \u0005[לא]\u0006 \u0003לאברים עומדת, וב\u0004ענין \u0003מיתי\u0004 \u0005[בואו]\u0006 של \u0003איסור אבר וחייל\u0004 \u0005[ויחול]\u0006 על \u0003איסור חלב ו\u0004על \u0003איסור טרפה קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אמי ור' אבהו, \u0005סבור]\u0006 כי \u0003אתי חייל\u0004 \u0005[בא\u0006 איסור אבר ו\u0005חל]\u0006 על איסור טריפה, ולכך לוקה אף עליו. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' חייא בר אבא, \u0005סבור]\u0006 כי \u0003לא אתי חייל\u0004 \u0005[אינו בא\u0006 ו\u0005חל],\u0006 ולכך אינו לוקה עליו, אלא לוקה שתים בלבד.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בהמה בחייה לאברים עומדת, ו\u0004מדובר כאן \u0003כגון שנטרפה\u0004 (נעשתה טריפה) \u0003לאחר מכאן,\u0004 לאחר לידתה, \u0003ובמיתי\u0004 \u0005[ובבואו]\u0006 של \u0003איסור טרפה מיחל\u0004 \u0005[\u0006ו\u0005יחול]\u0006 על \u0003איסור אבר קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אמי ור' אבהו, \u0005סבור]\u0006 כי \u0003אתי חייל\u0004 \u0005[בא\u0006 איסור טריפה ו\u0005חל]\u0006 על איסור אבר, והרי זה \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 באיסור \u0003חלב,\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003התורה אמרה, יבא איסור נבלה יחול על איסור חלב, ויבא איסור טרפה יחול על איסור חלב.\u0004","\u0003ו\u0004אילו \u0003אידך\u0004 \u0005[\u0006החכם \u0005האחר,\u0006 ר' חייא בר אבא\u0005]\u0006 אומר כי על איסור ה\u0003חלב הוא\u0004 שחל איסור טריפה ו\u0003חייב\u0004 על שניהם, ומפני ש\u0003הותר\u0004"],["\u0003מכללו,\u0004 שהרי החלב מותר בחיה, \u0003אבל\u0004 איסור \u0003אבר\u0004 מן החי ש\u0003לא הותר מכללו,\u0004 שנוהג אף בחיה — \u0003לא\u0004 חל איסור נבילה וטריפה.","ועוד בענין איסור אכילת אבר מן החי. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 לחכמים ש\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' שמעון בן לקיש מר' יוחנן:\u0004 אם נטל אדם אבר מן החי שיש בו שיעור כזית ו\u0003חלקו\u0004 לשני חלקים עוד בהיותו \u0003מבחוץ\u0004 לפיו, לפני שנתן את האבר בפיו לאוכלו, ואכל בתחילה חלק אחד ולאחר מכן את החלק האחר, \u0003מהו\u0004 דינו להתחייב על כך. האם מצטרפים שני חצאי הזית לחייבו, כבשאר איסורי אכילה שמצטרפים חלקי האכילה לחייבו (אם נאכלו שניהם בפרק זמן \"כדי אכילת פרס\"). או שמא מאחר ואיסור אבר מן החי חידוש דין הוא, שהרי בשאר איסורי אכילה אין מחייבים על אכילת גידים ועצמות, ובאיסור זה מחייבים על כך. שמא אין לך בו אלא חידושו, ואין מתחייבים אלא על אכילת אבר הנעשית בבת אחת, ולא כשנעשתה בזה אחר זה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' שמעון בן לקיש: הריהו \u0003פטור\u0004 על אכילה זו.","חזר ושאל ר' שמעון בן לקיש: אם נתן כזית שלם לתוך פיו, ואולם חילקו \u0003מבפנים\u0004 (בתוך פיו), ומשבאו שני החלקים סמוך לבית בליעתו בלע אותם בזה אחר זה, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' שמעון בן לקיש: \u0003חייב.\u0004 וכיוצא בזה נמסר \u0003ש\u0004\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר: חלקו מבחוץ\u0004 — \u0003פטור\u0004 לדעת הכל. חילקו \u0003מבפנים\u0004 — \u0003ר' יוחנן אמר\u0004 שהריהו \u0003חייב, ו\u0004אילו \u0003ריש לקיש אמר\u0004 שאף באופן זה \u0003פטור.\u0004 ומסבירים את שיטותיהם: \u0003ר' יוחנן אמר\u0004 שזה שחילק בתוך פיו הריהו \u0003חייב\u0004 — ש\u0003הרי נהנה גרונו\u0004 בסך הכל \u0003בכזית. וריש לקיש\u0004 ש\u0003אמר\u0004 שזה שחילק את הכזית בתוך פיו הריהו \u0003פטור\u0004 על כך — \u0003אכילה במעיו\u0004 שיש בה שיעור כזית \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 כדי לחייב על כך, \u0003ו\u0004במקרה זה שלפנינו \u0003ליכא\u0004 \u0005[אין כאן]\u0006 אכילת מעיים שיש בה בבת אחת שיעור כזית. ושואלים: לשיטת ר' יוחנן ברור הדבר מדוע אדם מתחייב על אכילת אבר מן החי, אף שבשעה שהאבר נמצא בפיו הריהו נחלק לחלקים. \u0003אלא ל\u0004שיטת \u0003ר' שמעון בן לקיש\u0004 הפוטר בכל מקרה בו הדבר הנאכל נחלק בתוך פיו של האוכל, מעתה \u0003היכי משכחת לה דמחייב\u0004 \u0005[כיצד אתה מוצא אותה\u0006 אפשרות \u0005ש\u0006הוא \u0005מתחייב],\u0006 באכילתו, שהרי תמיד נחלק המאכל בזמן אכילתו? \u0003אמר רב כהנא: בגרומיתא זעירתא\u0004 \u0005[בעצם זעירה]\u0006 שהוא יכול לבלוע אותה בשלימות, בלא שתיחלק. למעלה למדנו כי מוסכם על ר' יוחנן וריש לקיש שזה שחילק את האבר מן החי מחוץ לפיו, ולאחר מכן אכל את החלקים בזה אחר זה, הריהו פטור. \u0003ו\u0004בענין זה מביאים כי \u0003ר' אלעזר אמר\u0004 כי \u0003אפילו\u0004 זה ש\u0003חלקו מבחוץ נמי\u0004 \u0005[גם כן]\u0006 הריהו \u0003חייב\u0004 על כך, וטעם הדבר — שלדעתו כל דבר שהריהו \u0003מחוסר קריבה\u0004 (שחלקיו השונים אינם קרובים זה לזה, כדוגמת שני חלקי כזית האבר מן החי הללו, שחילקם מחוץ לפיו ונאכלו בזה אחר זה) \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כמחוסר מעשה דמי\u0004 \u0005[נחשב]\u0006 הדבר, שאין זה נחשב כאילו אכל רק חצי זית, ולאחר מכן שוב אכל חצי זית, אלא כאילו אכל כזית שלם בבת אחת. מתוך שנידונה למעלה מחלוקת ר' יוחנן וריש לקיש באכילת אבר מן החי, מביאים עוד ממחלוקתם בענין דרך האכילה המחייבת באיסורי אכילה. \u0003אמר ר' שמעון בן לקיש:\u0004 שיעור \u0003כזית שאמרו\u0004 חכמים בכל אכילות של איסור שמתחייב בו האוכל, הכוונה לשיעור הנבלע שהוא כזית, \u0003חוץ\u0004 (מלבד) \u0003משל\u0004 האיסור שנותר לאחר הלעיסה \u0003בין השינים,\u0004 שמה שנשאר בין השיניים אינו נחשב להצטרף לשיעור המחייב. \u0003ו\u0004אילו ר' יוחנן אמר: \u0003אף עם\u0004 של \u0003בין השינים.\u0004","","","","","","\u0003אמר רב פפא\u0004 בהסבר מחלוקתם: \u0003ב\u0004חלק המאכל \u0003של בין\u0004 ה\u0003שינים\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים],\u0006 ואף ר' יוחנן מודה שאינו מצטרף לשיעור כזית המחייב, \u0003כי פליגי\u0004 \u0005[כאשר\u0006 ר' יוחנן וריש לקיש \u0005חולקים]\u0006 הרי זה ביחס לחלק האוכל שנמצא \u0003בין החניכיים,\u0004 שהרי הגרון נהנה ממנו, ואולם אין המעיים נהנות ממנו. ובכך נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 שמצטרף חלק זה לשיעור כזית, ש\u0003הרי נהנה גרונו בכזית. ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 שאין חלק זה מצטרף לשיעור המחייב, שכן \u0003אכילה במעיו\u0004 של שיעור כזית \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 וחלק זה שבחניכיים לא נכנס למעיו. למעלה למדנו כי לדעת ר' יוחנן אדם חייב באכילת איסור על הנאת גרונו שיש בה שיעור כזית, ועוד בענין זה \u0003אמר ר' אסי אמר ר' יוחנן: אכל\u0004 דבר איסור ששיעורו \u0003חצי זית, והקיאו, וחזר ואכל חצי זית אחר\u0004 — הריהו \u0003חייב\u0004 על כך, אף שבסופו של דבר לא בא למעיו כזית איסור שלם. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — סוף סוף \u0003הרי נהנה גרונו בכזית. בעא\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר מר' אסי:\u0004 אם \u0003אכל\u0004 דבר איסור בשיעור \u0003חצי זית, והקיאו, וחזר ואכלו\u0004 לאותו חצי זית של איסור, \u0003מהו\u0004 הדין? ותוהים על שאלת ר' אלעזר: \u0003מאי קא מיבעיא ליה\u0004 \u0005[מה היא השאלה שנשאלה לו]?\u0006 \u0003אי הוי\u0004 \u0005[אם\u0006 חצי זית זה שנאכל ולאחר מכן הוקא \u0005נחשב]\u0006 כ\u0003עיכול,\u0004 אם כן שוב אינו נחשב דבר אוכל אלא כפרש ואין לחייב על האכילה השניה, \u0003אי לא הוי\u0004 \u0005[או אין הוא נחשב]\u0006 \u0003עיכול,\u0004 יש לחייבו אף על האכילה השניה. \u0003ו\u0004אולם אם זו היא בעייתו, \u0003תיבעי ליה\u0004 \u0005[תישאל לו\u0006 שאלתו\u0005]\u0006 ב\u0003כזית\u0004 שלם שאכלו והקיאו וחזר ואכלו, אם חייב הוא על כך סדרה אחת של מלקות או שתי סדרות מלקות!","","","\u0003אלא\u0004 השאלה היתה: \u0003אי בתר\u0004 \u0005[אם אחר]\u0006 הנאת \u0003גרונו אזלינן\u0004 \u0005[הולכים אנו],\u0006 והרי זה שאכל והקיא וחזר ואכל, בסופו של דבר נהנה גרונו בשיעור כזית, ויתחייב על אכילתו זו. \u0003אי בתר\u0004 \u0005[או אחר]\u0006 הנאת \u0003מעיו אזלינן\u0004 \u0005[הולכים אנו],\u0006 והרי לא נהנו מעיו מכזית שלם. ושואלים: \u0003ותפשוט ליה\u0004 \u0005[ותפתור לו]\u0006 את הבעיה הזו \u0003מ\u0004מה שאמר \u0003ר' אסי\u0004 עצמו שהולכים אנו אחר הנאת גרונו! ומשיבים: ר' אלעזר כשלעצמו לא הוצרך לשאול שאלות אלה, שכן פשוט לו דינן. ואולם שמע ר' אלעזר את \u0003ר' אסי\u0004 ש\u0003גמריה\u0004 \u0005[לימודו]\u0006 בענין זה ששמע מפי ר' יוחנן, \u0003איעקר ליה\u0004 \u0005[נעקר,\u0006 נשכח \u0005לו\u0006 לר' אסי\u0005],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אלעזר לאדכוריה\u0004 \u0005[להזכיר לו],\u0006 ומשום כבודו של ר' אסי לא אמר לו במפורש אלא בדרך שאלה, \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]:\u0006 \u0003למה לי\u0004 לומר שאכל \u0003חצי זית אחר, לימא מר בדידיה\u0004 \u0005[יאמר אדוני בעצמו]\u0006 באותו חצי זית, \u0003דאיכא למשמע מינה תרתי\u0004 \u0005[שאפשר לשמוע מכאן שנים]:\u0006 \u0003שמעינן מינה דלא הוי\u0004 \u0005[שומעים אנו ממנה שאינו נחשב]\u0006 \u0003עיכול, ושמעינן מינה\u0004 \u0005[ושומעים אנו ממנה]\u0006 ש\u0003הרי נהנה גרונו בכזית!\u0004","","\u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' אסי \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר לר' אסי, בדרך של כבוד, \u0003מופת הדור,\u0004 האם \u0003לא זימנין סגיאין\u0004 \u0005[פעמים רבות]\u0006 \u0003אמרת קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 שאף באותו חצי זית הריהו חייב, \u0003ואמר לך\u0004 ר' יוחנן כדבריך, ש\u0003הרי נהנה גרונו בכזית,\u0004 ואין זה נחשב עיכול.","","\u0003כל\u0004 סוגי \u0003הבשר\u0004 הכשר לאכילה (של בהמה חיה ועוף) \u0003אסור לבשל\u0004 אותם \u0003ב\u0004כל \u0003חלב\u0004 הבא מן בעל החיים הכשר לאכילה. \u0003חוץ מבשר דגים וחגבים,\u0004 שאין בשרם של אלו נחשב כבשר לענין איסור בשר בחלב. \u0003ו\u0004בדומה לכך גזרו חכמים \u0003כי\u0004 \u0003אסור להעלות\u0004 כל בשר ממיני הבשרים \u0003עם\u0004 דבר מאכל הבא מן \u0003ה\u0004חלב, כגון \u0003גבינה, על\u0004 אותו \u0003השלחן,\u0004 שמא יבואו לאוכלם ביחד, כאשר הם נוגעים ובולעים זה מזה. \u0003חוץ מבשר דגים וחגבים\u0004 שמותר להעלות את בשרם על השולחן בו נאכלת גבינה."],["ודין נוסף: כל \u0003הנודר\u0004 שלא יאכל \u0003מן הבשר,\u0004 הריהו אסור באכילת בשר בהמה חיה ועוף, ואולם הריהו \u0003מותר ב\u0004אכילת \u0003בשר דגים וחגבים,\u0004 שאין אלה נכללים בלשון נדרו.","שנינו במשנתנו כי כל בשר אסור לבשלו בחלב, ובכלל הבשר הריהו בשר בהמה חיה ועוף. ודנים בדבר: מתוך שלא הבחינה המשנה בין בשר בהמה וחיה לבין בשר עוף, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נסיק כי בשר \u0003עוף אסור\u0004 בבישול בחלב \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 כדרך שאסור בשר הבהמה. ומעתה יש לשאול: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא משנתנו? ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא, דאי\u0004 \u0005[שאם]\u0006 היא כשיטת \u0003ר' עקיבא, האמר\u0004 \u0005[הרי אמר]\u0006 כי איסור בשר \u0003חיה ועוף\u0004 בחלב \u0003אינו מן התורה.\u0004","ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]\u0006 ששנינו בה: \u0003הנודר מן הבשר\u0004 — הריהו \u0003מותר בבשר דגים וחגבים,\u0004 ומכאן נדייק: דווקא בבשר דגים וחגבים הוא מותר, \u0003הא\u0004 \u0005[הרי]\u0006 שבבשר \u0003עוף\u0004 הריהו \u0003אסור\u0004 — ומעתה \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' עקיבא,\u0004 שכן \u0003אמר\u0004 ר' עקיבא כי \u0003כל מילי דמימליך עליה\u0004 \u0005[דבר ש\u0006אין \u0005ברורה בו כוונת דברי המשלח, ולכך\u0006 \u0005נמלך עליו]\u0006 ה\u0003שליח\u0004 — \u0003בר מיניה\u0004 \u0005[בן מינו]\u0006 \u0003הוא\u0004 זה. ומה ענינו?","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של \u0003הנודר\u0004 שלא לאכול \u0003מן הירק,\u0004 ש\u0003מותר ב\u0004אכילת \u0003דלועין,\u0004 שכן אין הדלועים בכלל ירק. \u0003ו\u0004אילו \u0003ר' עקיבא אוסר\u0004 אכילת דלועים, שאף אלה לדעתו בכלל לשון הנדר. \u0003אמרו לו\u0004 חכמים \u0003לר' עקיבא\u0004 בתמיהה: \u0003והלא\u0004 דבר מצוי הוא \u0003ש\u0004\u0003אומר אדם לשלוחו \"קח\u0004 (קנה) \u0003לנו ירק\", והוא\u0004 השליח חוזר ו\u0003אומר\u0004 למשלח: \u0003\"לא מצאתי אלא דלועין\",\u0004 הרי שדלועים אינם בכלל ירק!","\u0003אמר להן\u0004 ר' עקיבא לחכמים: \u0003כן הדבר,\u0004 ודווקא מכאן יש להוכיח כשיטתי, שהרי \u0003כלום\u0004 (האם) \u0003אומר\u0004 השליח שנשלח לקנות ירק \u0003\"לא מצאתי אלא קטנית?!\" אלא\u0004 מעתה שאומר השליח \"לא מצאתי אלא דלועים\" הרי זה מוכיח \u0003שדלועין\u0004 \u0003בכלל ירק,\u0004 ולכן הוא מתייעץ עם משלחו ביחס לדלועים, שאפשר שכן היתה דעת המשלח, \u0003ואין קטנית בכלל ירק.\u0004 ונמצא איפוא ש\u0003רישא\u0004 \u0005[ראשה,\u0006 תחילת\u0005]\u0006 המשנה היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' עקיבא, \u0003ו\u0004אילו \u0003סיפא\u0004 \u0005[סוף\u0006 המשנה\u0005]\u0006 הוא כשיטת \u0003ר' עקיבא!\u0004","\u0003אמר רב יוסף:\u0004 אין זו קושיה, שכן משנתנו כולה כשיטת \u0003רבי היא, ונסיב לה אליבא דתנאי\u0004 \u0005[ולקח אותה לפי שיטת תנאים\u0006 שונים\u0005],\u0006 שכן בסוף המשנה \u0003ב\u0004ענין \u0003נדרים, סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' עקיבא,\u0004 ואילו בתחילת המשנה \u0003ב\u0004ענין \u0003בשר בחלב, סבר לה כרבנן\u0004 \u0005[סבור הוא כחכמים].\u0006","ואילו \u0003רב אשי אמר\u0004 הסבר אחר: המשנה \u0003כולה\u0004 כשיטת \u0003ר' עקיבא היא,\u0004 וכעולה מדברי סוף המשנה בענין נדרים. \u0003ו\u0004באשר לתחילת המשנה, \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא, \u0005אומר]:\u0006 \u0003כל הבשר אסור לבשל בחלב, מהן\u0004 שאסורים \u0003מדברי תורה\u0004 (כבשר בהמה), \u0003ומהן\u0004 שאינם אסורים אלא \u0003מדברי סופרים\u0004 (כבשר חיה ועוף, וכשיטת ר' עקיבא). \u0003חוץ מבשר דגים וחגבים, שאינם\u0004 אסורים בבישול בחלב \u0003לא מדברי תורה ולא מדברי סופרים.\u0004","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003אסור להעלות\u0004 על השולחן עם הגבינה את כל סוגי הבשר, ובכללם בשר עוף. שגזרו חכמים שמא יבוא לאוכלם יחד. ובענין זה \u0003אמר רב יוסף: שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבישול ואכילת \u0003בשר עוף בחלב\u0004 הריהו איסור \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003דאי סלקא דעתך דרבנן\u0004 \u0005[שאם עולה על דעתך\u0006 לומר שהוא איסור \u0005מדברי סופרים\u0006 בלבד, ומגזירת חכמים\u0005],\u0006 הרי \u0003אכילה\u0004 של בשר עוף בחלב \u0003גופה\u0004 (עצמה) אסורה רק משום \u0003גזירה,\u0004 שמא יבוא לאכול אף בשר בהמה בחלב, \u0003ואנן נגזר\u0004 \u0005[ואנו נגזור]\u0006 \u0003העלאה\u0004 על השולחן של בשר עוף וגבינה יחד, \u0003אטו\u0004 \u0005[משום]\u0006 \u0003אכילה,\u0004 והלא אין גוזרים גזירה לגזירה!","\u0003ומנא תימרא דלא גזרינן\u0004 \u0005[ומנין אתה אומר שאין אנו גוזרים]\u0006 \u0003גזירה לגזירה? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלת חוצה לארץ\u0004"],["\u0003נאכלת עם הזר\u0004 (מי שאינו כהן), האסור באכילת חלה, \u0003על\u0004 אותו \u0003השלחן\u0004 בו הכהן אוכלה, שאין אנו גוזרים שמא יבוא הזר לאכול ממנה. לפי שכל הפרשת חלה בחוצה לארץ אינה אלא מגזירת חכמים, ואין גוזרים גזירה לגזירה. \u0003ו\u0004כמו כן חלת חוצה לארץ \u0003ניתנת לכל כהן שירצה\u0004 בעל הבית לתיתה לו, ואפילו הוא עם הארץ שאינו משמר את החלה בטהרתה (שלא כחלת ארץ ישראל, שאינה ניתנת אלא לכהנים השומרים דיני טהרה).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בדחיית ראייתו: \u0003בשלמא אי אשמועינן\u0004 \u0005[זה נוח,\u0006 והיתה זו ראיה, \u0005אם היה משמיע לנו]\u0006 התנא את הדין הזה ב\u0003חלת חוצה לארץ\u0004 שהובאה מחוצה לארץ והריהי עתה \u0003בארץ,\u0004 שנאכלת עם הזר על שולחן אחד. ואפשר היה להוכיח מכאן שאין גוזרים גזירה לגזירה, \u0003דאיכא למיגזר\u0004 \u0005[ש\u0006כן \u0005יש מקום לגזור]\u0006 שלא להעלותה על שולחן אחד עם הזר \u0003משום\u0004 החשש שיבואו להעלות כן אף ב\u0003חלת הארץ,\u0004 שהינה \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004בכל זאת \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 כן — מעתה \u0003איכא למשמע מינה\u0004 \u0005[אפשר ללמוד מכאן]\u0006 שאין גוזרים גזירה לגזירה.","\u0003אלא\u0004 עתה שהשמיענו התנא את דינו בחלת \u0003חוצה לארץ\u0004 שבחוצה לארץ — אין מכאן הוכחה, שהרי הטעם שהותר הדבר \u0003משום דליכא למיגזר\u0004 \u0005[שאין מקום לגזור]\u0006 \u0003הוא,\u0004 כי אין איסור תורה נוהג בחלת חוצה לארץ. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בנאמר במשנתנו בהעלאת בשר עוף וגבינה על שולחן אחד\u0005],\u0006 \u0003אי שרית ליה לאסוקי\u0004 \u0005[אם תתיר לו להעלות]\u0006 בשר \u0003עוף וגבינה, אתי לאסוקי\u0004 \u0005[יבואו להעלות]\u0006 גם \u0003בשר\u0004 בהמה \u0003וגבינה\u0004 על שולחן אחד, \u0003ומיכל\u0004 \u0005[ולאכול]\u0006 \u0003בשר בחלב\u0004 האסור \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת:\u0004 והרי גם אם נאמר כי בשר עוף בחלב אסור מן התורה, עדיין יש בדבר משום גזירה לגזירה. שכן איסור ההעלאה על שולחן אחד הריהו גזירת חכמים, ואף האכילה עצמה של בשר בחלב יחד אסורה רק מדברי חכמים, שכן \u0003סוף סוף\u0004 (עדיין), \u0003צונן בצונן הוא,\u0004 ובדבר זה אין איסור מן התורה! \u0003אמר אביי: גזירה שמא יעלה\u0004 בשר בהמה עם הגבינה \u0003באילפס רותח,\u0004 והרי זה דרך בישול, האסור מן התורה.","ומקשים: \u0003סוף סוף,\u0004 אפילו אילפס רותח, והרי אין זה אלא \u0003כלי שני\u0004 (כלי שהוסר מן האש) \u0003הוא, ו\u0004כלל הוא ש\u0003כלי שני אינו מבשל!\u0004 אלא צריך לומר: \u0003גזירה שמא יעלה באילפס\u0004 שהוא כלי \u0003ראשון,\u0004 שעמד על האש, ובדבר זה אסור בשר בהמה בחלב מן התורה.","בשר \u0003העוף עולה עם הגבינה\u0004 \u0003על\u0004 אותו \u0003השולחן, ו\u0004אולם \u0003אינו\u0004 \u0003נאכל\u0004 יחד איתה, אלו \u0003דברי בית שמאי.\u0004 \u0003ובית הלל אומרים:\u0004 בשר העוף \u0003לא עולה\u0004 על שולחן אחד עם הגבינה, \u0003ולא נאכל\u0004 איתה. \u0003אמר ר' יוסי:\u0004 מחלוקת \u0003זו\u0004 שבין בית שמאי לבית הלל היא מן המחלוקות שהן \u0003מקולי בית שמאי ומחומרי בית הלל.\u0004","ומסבירים: \u0003באיזה שולחן אמרו\u0004 שאסור להניח עליו בשר עוף וגבינה? דווקא \u0003בשולחן שאוכל עליו, אבל בשולחן שסודר עליו את התבשיל\u0004 לפני שהוא מוגש לאכילה — הריהו \u0003נותן\u0004 בשר וגבינה \u0003זה בצד זה, ואינו חושש\u0004 שמא יתערבו, ויבוא לאוכלם כאחד.","שנינו במשנתנו שאמר ר' יוסי שמחלוקת זו בית שמאי הם המקילים בה, ובית הלל הם המחמירים. ותוהים: מה בא \u0003ר' יוסי\u0004 להשמיענו, והרי \u0003היינו תנא קמא\u0004 \u0005[זהו\u0006 הנאמר במפורש בדברי \u0005התנא הראשון,\u0006 שהביא את מחלוקתם של בית שמאי ובית הלל\u0005]?\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שלענין \u0003אכילה גופה\u0004 \u0005[עצמה]\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 בין התנא הראשון ובין ר' יוסי\u0005]\u0006 מחלוקת, \u0003דקאמר תנא קמא\u0004 \u0005[שאומר התנא הראשון]\u0006 כי \u0003בהעלאה קא מיפלגי\u0004 \u0005[\u0006בית שמאי ובית הלל, \u0005חלוקים],\u0006 ואולם \u0003באכילה לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי\u0004 כי ב\u0003אכילה גופה\u0004 \u0005[עצמה]\u0006 של בשר עוף בחלב נחלקו בית שמאי ובית הלל, והריהי \u0003מקולי בית שמאי ומחומרי בית הלל\u0004 — אי אפשר לומר כן,","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: ששה דברים\u0004 הם \u0003מקולי בית שמאי ומחומרי בית הלל, וזו אחת מהן\u0004 — בשר \u0003עוף עולה עם הגבינה על השולחן, ו\u0004אולם \u0003אינו נאכל\u0004 עמה. אלו \u0003דברי בית שמאי. ו\u0004אילו \u0003בית הלל אומרים\u0004 כי בשר עוף \u0003לא עולה\u0004 על שולחן אחד עם הגבינה, \u0003ולא נאכל\u0004 עמה. הרי שסבור ר' יוסי כי אף לדעת בית שמאי אין בשר עוף נאכל עם הגבינה!","\u0003אלא, הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה הוא,\u0006 התנא במשנתנו \u0005משמיע לנו]:\u0006 \u0003מאן תנא קמא\u0004 \u0005[מיהו התנא הראשון]?\u0006 הוא \u0003ר' יוסי,\u0004 ולמה צריך לומר זאת? ש\u0003כל האומר דבר בשם אומרו, מביא גאולה לעולם,\u0004 וראיה לדבר \u0003ש\u0004כן \u0003נאמר\u0004 בהצלתו של אחשורוש מידי בגתן ותרש \u0003\"ותאמר אסתר למלך בשם מרדכי\"\u0004 (אסתר ב, כב), ולאחר מכן גאולת ישראל מגזירת המן החלה בגלל ידיעה זו שהדברים באו מאת מרדכי (כמבואר שם ו, ג).","ועוד בענין אכילת בשר עוף וגבינה, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003אגרא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003ר' אבא:\u0004 בשר \u0003עוף וגבינה נאכלין באפיקורן\u0004 (באופן חופשי, שאין צורך להקפיד הרבה בדבר). ומעירים: \u0003הוא\u0004 אגרא זה ש\u0003תני לה\u0004 \u0005[שנה אותה]\u0006 אותה ברייתא, \u0003והוא\u0004 זה ש\u0003אמר\u0004 (פירש) \u0003לה\u0004 \u0005[אותה],\u0006 בשר עוף וגבינה נאכלים \u0003בלא\u0004 צורך ב\u0003נטילת ידים ובלא\u0004 צורך ב\u0003קינוח הפה\u0004 בין אכילתו של זה לאכילתו של זה.","ומסופר כי \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי, אייתו ליה\u0004 \u0005[הביאו לו]\u0006 \u0003גבינה\u0004 לאכול — \u0003אכל\u0004 אותה. לאחר מכן \u0003אייתו ליה בשרא\u0004 \u0005[הביאו לו בשר\u0006 בהמה\u0005]\u0006 לאכול — \u0003אכל\u0004 את הבשר, \u0003ולא משא ידיה\u0004 \u0005[נטל ידיו]\u0006 לפני אכילת הבשר. \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 בני ביתו של רב אשי: \u0003והא תאני\u0004 \u0005[והרי שנה]\u0006 \u0003אגרא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003ר' אבא: עוף וגבינה נאכלין באפיקורן,\u0004 ויש לדייק מדבריו כי דווקא באכילת \u0003עוף וגבינה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אין צורך בנטילת ידים, אבל באכילת \u0003בשר וגבינה\u0004 — \u0003לא,\u0004 שצריך האוכל ליטול ידיו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 של אגרא חמיו של ר' אבא אמורים \u0003בליליא\u0004 \u0005[בלילה],\u0006 שאין אדם רואה, ויש לחשוש שדבק בידיו מהמאכל הקודם, ולכך נצרך הוא לנטילת ידיו. \u0003אבל ביממא\u0004 \u0005[ביום],\u0006 שניתן לראות את ידיו, \u0003הא חזינא\u0004 \u0005[הרי רואה אני]\u0006 שלא נדבק דבר בידי, ואין אני נצרך לנטילת ידים.","ועוד בהנהגה הראויה בין אכילת בשר וגבינה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003בית שמאי אומרים:\u0004 בין אכילת בשר וגבינה \u0003מקנח\u0004 האוכל את פיו. \u0003ובית הלל אומרים:\u0004 הריהו \u0003מדיח\u0004 את פיו. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקנח\", ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"מדיח\"?\u0004"],["\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונת הדברים היא ש\u0003בית שמאי אומרים\u0004 שהריהו \u0003מקנח\u0004 את פיו בדבר מוצק, \u0003ולא בעי\u0004 \u0005[ואינו צריך]\u0006 שיהא \u0003מדיח\u0004 את פיו במים, שכן לדעתם הקינוח מועיל יותר מן ההדחה. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 שהריהו \u0003מדיח\u0004 את פיו במים, \u0003ולא בעי\u0004 \u0005[ואינו צריך]\u0006 שיהא \u0003מקנח\u0004 את פיו, שלדעתו אין הקינוח מועיל כדרך שההדחה מועילה — אין לומר כן, שכן \u0003אלא\u0004 מעתה \u0003הא דאמר\u0004 \u0005[זו שאמר]\u0006 \u0003ר' זירא: אין קינוח פה אלא בפת, כמאן\u0004 \u0005[כמי]\u0006 אם כן אמר זאת? לכאורה \u0003כ\u0004דעת \u0003בית שמאי\u0004 הסבורים שהאוכל בשר צריך לקנח פיו לפני אכילת גבינה, ושלא כשיטת בית הלל הסבורים שנצרך הוא להדחה, ולא לקינוח, ואין זה מסתבר שיורה ר' זירא הלכה כבית שמאי ולא כבית הלל!","\u0003אלא\u0004 צריכים לפרש כך את מחלוקתם של בית שמאי ובית הלל, ש\u0003בית שמאי אומרים\u0004 כי די בכך שיהא \u0003מקנח\u0004 את פיו לאחר אכילת בשר, \u0003ולא בעי\u0004 \u0005[ואינו צריך]\u0006 שיהא גם \u0003מדיח\u0004 את פיו. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 כי מלבד שהוא מקנח הריהו \u0003אף מדיח\u0004 — ואולם אף זאת אין לומר, שכן \u0003הוי ליה\u0004 \u0005[הרי זה]\u0006 מחלוקת בית שמאי ובית הלל, שיש בה אם כן \u0003מקולי בית שמאי ומחומרי בית הלל, ולתנייה\u0004 \u0005[ו\u0006צריך \u0005שישנה אותה\u0006 התנא במסכת עדיות\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 שאר מחלוקותיהם השנויות שם כ\u0003קולי בית שמאי וחומרי בית הלל!\u0004","\u0003אלא\u0004 צריך לפרש כך את מחלוקתם, ש\u0003בית שמאי אומרים\u0004 בדינו של האוכל בשר, שהריהו \u0003מקנח\u0004 את פיו לפני אכילת גבינה, \u0003והוא הדין למדיח,\u0004 שנצרך הוא לקינוח ולהדחה. \u0003ובית הלל אומרים\u0004 שהריהו \u0003מדיח והוא הדין למקנח,\u0004 שנצרך הוא אף לכך. ונמצא לפי זה כי \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003אמר חדא\u0004 \u0005[\u0006דבר \u0005אחד],\u0006 \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003אמר חדא\u0004 \u0005[\u0006דבר \u0005אחד],\u0006 \u0003ו\u0004למעשה הם \u0003לא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 זה עם זה.","למעלה הובאה הלכה בשם ר' זירא, אגב בירור שיטות בית שמאי ובית הלל, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה].\u0006 ש\u0003אמר ר' זירא: אין קינוח הפה אלא בפת.\u0004 ומפרטים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא \u0003ב\u0004פת העשויה מקמח \u0003דחיטי\u0004 \u0005[של חיטים],\u0006 \u0003אבל ב\u0004פת העשויה \u0003מקמח\u0004 \u0003דשערי\u0004 \u0005[של שעורים]\u0006 — \u0003לא,\u0004 שכן פת זו מתפוררת בתוך הפה, ואינה מוצקה דייה כדי לקנח יפה את הפה.","\u0003ו\u0004מוסיפים: אף פת \u0003דחיטי נמי לא אמרן\u0004 \u0005[של חיטים גם כן לא אמרנו]\u0006 שהריהי מועילה לקינוח הפה \u0003אלא\u0004 דווקא \u0003ב\u0004זו שהיא \u0003קרירא\u0004 \u0005[קרה],\u0006 \u0003אבל ב\u0004פת חיטים שהיא \u0003חמימא\u0004 \u0005[חמה]\u0006 אינה מועילה לקינוח, כי \u0003משטר שטרי\u0004 \u0005[מתרככת ונדבקת]\u0006 היא בחיך, ואינה מקנחת כראוי. \u0003ו\u0004עוד מוסיפים כי אף בפת חיטים קרירה \u0003הני מילי ברכיכא\u0004 \u0005[דברים אלה אמורים\u0006 דווקא \u0005ב\u0006פת \u0005רכה],\u0006 \u0003אבל באקושא\u0004 \u0005[בקשה]\u0006 — \u0003לא, ש\u0004אינה מקנחת כראוי. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא כי \u0003בכל מילי הוי\u0004 \u0005[בכל דבר הרי זה]\u0006 \u0003קינוח, לבר מקמחא תמרי וירקא\u0004 \u0005[חוץ מקמח, תמרים\u0006 \u0005וירק].\u0006","ועוד בבירור דין אכילת גבינה לאחר אכילת בשר, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אסי מר' יוחנן: כמה\u0004 זמן \u0003ישהה בין\u0004 אכילת \u0003בשר ל\u0004אכילת \u0003גבינה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולא כלום,\u0004 שאינו צריך להמתין כלל. ותוהים: \u0003איני\u0004 \u0005[כן הוא]\u0006 הלכה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חסדא:\u0004 מי ש\u0003אכל בשר\u0004 — \u0003אסור\u0004 לו \u0003לאכול\u0004 מיד \u0003גבינה,\u0004 מי שאכל \u0003גבינה\u0004 — \u0003מותר\u0004 לו \u0003לאכול\u0004 מיד \u0003בשר\u0004 אחריה! \u0003אלא\u0004 יש לומר שכך שאל רב אסי את ר' יוחנן: \u0003כמה\u0004 זמן \u0003ישהה בין\u0004 אכילת \u0003גבינה ל\u0004אכילת \u0003בשר?\u0004 ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה: \u0003ולא כלום,\u0004 שאינו צריך להמתין כלל.","למעלה הובאה הלכה משמו של רב חסדא בבירור הוראתו של ר' יוחנן, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה],\u0006 ובנוסחה המורחב. \u0003אמר רב חסדא: אכל בשר\u0004 — \u0003אסור לאכול\u0004 מיד אחר כן \u0003גבינה,\u0004 ומשום שהבשר מפריש שומן הנדבק בפה והמשמר עדיין בפיו את טעם הבשר. אבל אם אכל \u0003גבינה\u0004 — \u0003מותר לאכול בשר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר יוסף לרב חסדא\u0004 בשאלה: \u0003בשר שבין השינים מהו\u0004 דינו לענין אכילת גבינה אחרי כן, האם הריהו נחשב כבשר, ואין לאכול גבינה כל עוד הוא נתון בתוך פיו?","\u0003קרי\u0004 \u0005[קרא]\u0006 רב חסדא את המקרא הזה \u0003עליה\u0004 \u0005[עליו,\u0006 כתשובה לשאלתו זו של רב אחא בר יוסף\u0005]\u0006 \u0003\"הבשר עודנו בין שיניהם\"\u0004 (במדבר יא, לג) — הרי שאף הבשר שבין השיניים נקרא \"בשר\", וממילא אין לאכול גבינה כל עוד הוא נתון בין השיניים.","ועוד נאמר בענין שיעור המתנה שבין אכילת בשר לבין אכילת גבינה, \u0003אמר מר עוקבא: אנא, להא מלתא, חלא בר חמרא\u0004 \u0005[אני, לענין זה,\u0006 כמו \u0005חומץ בן יין]\u0006 \u0003לגבי אבא\u0004 \u0005[אצל אבי],\u0006 ש\u0003אילו אבא\u0004 \u0005[אבי]\u0006 \u0003כי הוה אכיל בשרא האידנא, לא הוה אכל\u0004 \u0005[כאשר היה אוכל בשר היום, לא היה אוכל]\u0006 \u0003גבינה עד למחר עד השתא\u0004 \u0005[עתה,\u0006 באותה שעה\u0005].\u0006 \u0003ואילו אנא\u0004 \u0005[אני]\u0006 \u0003בהא סעודתא\u0004 \u0005[בסעודה זו]\u0006 שאכל בה \u0003בשר\u0004 \u0003הוא דלא אכילנא\u0004 \u0005[שאין אני אוכל]\u0006 גבינה, ואולם \u0003לסעודתא אחריתא\u0004 \u0005[לסעודה אחרת]\u0006 היום — \u0003אכילנא\u0004 \u0005[אני אוכל]\u0006 גבינה.","בדרך דומה \u0003אמר שמואל: אנא, להא מלתא, חלא בר חמרא לגבי אבא\u0004 \u0005[אני, לענין זה,\u0006 כ\u0005חומץ בן יין לגבי אבי],\u0006 ש\u0003אילו אבא\u0004 \u0005[אבי]\u0006 \u0003הוה סייר נכסיה תרי זמני ביומא\u0004 \u0005[היה מסייר,\u0006 עובר ובודק \u0005נכסיו שתי פעמים ביום],\u0006 \u0003ואנא לא סיירנא אלא חדא זימנא\u0004 \u0005[ואני איני מסייר אלא פעם אחת\u0006 ביום\u0005].\u0006 ומעירים: בענין זה \u0003שמואל\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר שמואל: מאן דסייר נכסיה כל יומא משכח אסתירא\u0004 \u0005[מי שמסייר נכסיו בכל יום מוצא מטבע].\u0006","וכן מסופר כי \u0003אביי הוה סייר נכסיה כל יומא ויומא\u0004 \u0005[היה מסייר נכסיו כל יום ויום],\u0006 \u0003יומא חד פגע באריסיה דדרי פתכא דאופי\u0004 \u0005[יום אחד פגש את אריסו שנושא משא של עצים]\u0006 שהתכוון לקחת לעצמו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לאריס: \u0003הני להיכא\u0004 \u0005[אלה\u0006 העצים \u0005להיכן]\u0006 אתה נושאם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 האריס: \u0003לבי מר\u0004 \u0005[לבית אדוני],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי, שידע באריס שרצה לקחת את העצים לעצמו, \u0003כבר קדמוך רבנן\u0004 \u0005[חכמים]\u0006 שאמרו הוראה זו שצריך לסייר נכסיו, ומשום כך לא הצליחה לך מחשבתך הראשונה לגנוב את העצים.","וכן מסופר כי \u0003רב אסי הוה סייר נכסיה כל יומא\u0004 \u0005[היה מסייר נכסיו כל יום],\u0006 \u0003אמר: היכא נינהו כל הני אסתירי\u0004 \u0005[היכן הם כל אותן המטבעות]\u0006 של \u0003מר שמואל?\u0004 שהסיור לא הועיל לי דבר. \u0003יומא חד חזא צינורא דבדקא בארעיה\u0004 \u0005[יום אחד ראה אמת המים\u0006 שנפרצה, וזורמים מים \u0005בשדהו].\u0006 \u0003שקליה לגלימיה\u0004 \u0005[פשט את גלימתו],\u0006 \u0003כרכיה אותביה בגוה\u0004 \u0005[כרך אותה ושם אותה בתוכה,\u0006 כדי לסוכרה\u0005].\u0006 \u0003רמא קלא, אתו אינשי סכרוה\u0004 \u0005[הרים\u0006 את \u0005קולו\u0006 לעזרה, \u0005באו אנשים\u0006 ו\u0005סכרוה\u0006 את הפירצה\u0005],\u0006 אמר רב אסי: \u0003אשכחתינהו לכולהו איסתרי\u0004 \u0005[מצאתי\u0006 עכשיו \u0005את כל המטבעות הללו]\u0006 של \u0003מר שמואל,\u0004 שאלמלא סיירתי בשדה, הייתי מאבד ממון רב.","בעמוד הקודם הוזכר דין נטילת ידים שבתוך הסעודה, ועתה מרחיבים דברים בענין זה. \u0003אמר רב אידי בר אבין,\u0004 \u0003אמר רב יצחק בר אשיין:\u0004 נטילת ידים של \u0003מים ראשונים,\u0004 שלפני \u0003אכילת פת\u0004 — הריהי \u0003מצוה\u0004 מדברי חכמים. \u0003ו\u0004אילו נטילת ידים במים \u0003אחרונים\u0004 בסוף הסעודה, לפני ברכת המזון — הריהי \u0003חובה,\u0004 החמורה מן המצוה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב אידי בר אבין ממה ששנינו בברייתא: \u0003מים ראשונים ואחרונים\u0004 — הריהם \u0003חובה,\u0004 ואילו מים \u0003אמצעיים\u0004 שבתוך הסעודה, בין מנות תבשילי האוכל — הריהם \u0003רשות.\u0004 הרי איפוא שגם מים ראשונים הריהם חובה, ולא מצוה! ואומרים: אין זו סתירה, כי \u0003מצוה לגבי\u0004 \u0005[אצל,\u0006 ביחס\u0005]\u0006 \u0003רשות\u0004 — \u0003\"חובה\" קרי לה\u0004 \u0005[קורא אותה],\u0006 ולכך קרא התנא למים ראשונים \"חובה\" בהשוואה למים אמצעיים. ואולם הגדרתה העצמית של נטילת מים ראשונים היא כ\"מצוה\" ולא כ\"חובה\".","למעלה הובאו דברי הברייתא בבירור דברי רב אידי בר אבין, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה],\u0006 ובנוסחה המורחב: \u0003מים ראשונים ו\u0004כן מים \u0003אחרונים\u0004 — הריהם \u0003חובה,\u0004 ואילו מים \u0003אמצעיים\u0004 — הריהם \u0003רשות.\u0004 ועוד הבדל בין סוגי המים הללו: מים \u0003ראשונים\u0004 — \u0003נוטלין בין ב\u0004אופן שישפכו המים אל תוך \u0003כלי, בין\u0004 שישפכו \u0003על גבי קרקע.\u0004 ואילו מים \u0003אחרונים\u0004 — \u0003אין נוטלין אלא ב\u0004אופן שישפכו המים אל תוך \u0003כלי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 הלכה זו בנוסח שונה: מים אחרונים \u0003אין נוטלין על גבי קרקע.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם,\u0006 בין שני הנוסחים\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין נטילת מים אחרונים על \u0003קינסא\u0004 \u0005[קיסמי עץ קטנים]\u0006 המונחים על הארץ. לנוסח שמים אחרונים ניטלים רק לתוך כלי — אין נוטלים מים אחרונים על קסמי עץ. ואילו לנוסח שמים אחרונים אינם ניטלים על גבי קרקע — נוטלים מים אחרונים על קסמי עץ.","ועוד בהבדל שבין סגי נטילות הידים הללו, \u0003מים ראשונים\u0004 — \u0003נוטלין בין ב\u0004מים \u0003חמין בין בצונן,\u0004 ואילו מים \u0003אחרונים\u0004 — \u0003אין נוטלין אלא בצונן,\u0004 ומדוע אין נוטלים במים חמים למים אחרונים? \u0003מפני ש\u0004מים \u0003חמין מפעפעין\u0004 (עושים כנקבים) \u0003את הידים, ואין\u0004 הם \u0003מעבירין את הזוהמא\u0004 (הלכלוך) שעל הידים. שנינו בברייתא זו כי \u0003מים ראשונים נוטלין בין בחמין בין בצונן.\u0004 ובהסבר הדברים \u0003אמר רב יצחק בר יוסף, אמר ר' ינאי: לא שנו\u0004 שנוטלים למים ראשונים במים חמים \u0003אלא\u0004 בזמן \u0003שאין היד\u0004"],["\u0003סולדת\u0004 (נכוית) \u0003בהן\u0004 מחמת החום. \u0003אבל\u0004 בזמן ש\u0003היד סולדת בהן\u0004 — \u0003אין נוטלין בהן\u0004 למים ראשונים.","\u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששונים אותה\u0006 הלכה של ר' ינאי \u0005על סוף\u0006 הברייתא\u0005],\u0006 ששנינו בה כי מים \u0003אחרונים אין נוטלין אלא בצונן, אבל בחמין\u0004 — \u0003לא.\u0004 ועל כך \u0003אמר רב יצחק בר יוסף, אמר ר' ינאי: לא שנו\u0004 שאין נוטלים בחמים, \u0003אלא\u0004 כאשר המים חמים עד \u0003שהיד סולדת בהן, אבל\u0004 כאשר \u0003אין היד סולדת בהן\u0004 — \u0003נוטלין\u0004 בהם למים אחרונים. ומסיקים: \u0003מכלל\u0004 נוסח זה אתה לומד שכך היא הלכה במים אחרונים, ואולם במים \u0003ראשונים, אף על פי\u0004 שהמים חמים עד \u0003שהיד סולדת בהן\u0004 — \u0003מותר\u0004 ליטול בהם.","שנינו בברייתא למעלה כי מים \u0003אמצעיים\u0004 הריהם \u0003רשות,\u0004 ובענין זה \u0003אמר רב נחמן: לא שנו\u0004 כן \u0003אלא\u0004 בנטילת ידים ש\u0003בין תבשיל לתבשיל\u0004 המוגשים בסעודה, \u0003אבל בין תבשיל לגבינה\u0004 — אין זו רשות, אלא \u0003חובה\u0004 היא ליטול \u0003ידיו.\u0004","ועוד שנינו בברייתא זו כי מים אחרונים הריהם חובה, ובענין זה \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מפני מה אמרו\u0004 חכמים כי \u0003מים אחרונים\u0004 הריהם \u0003חובה?\u0004 משום \u0003ש\u0004לפעמים במלח שבאוכל \u0003מלח סדומית יש, ש\u0004מלח זה \u0003מסמא\u0004 (מעוור) \u0003את העינים,\u0004 ולכן צריך לרחוץ את הידים כדי שלא יגע בידיו בעיניו בעוד המלח עליהן. \u0003אמר אביי: ו\u0004מלח סדומית זה מצוי בשיעורים קטנים ביותר, שלפעמים הוא \u0003משתכח כי קורטא בכורא\u0004 \u0005[נמצא כמו קורט ב\u0006מידת \u0005כור\u0006 של מלח רגיל\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 אדם ש\u0003כל מלחא מאי\u0004 \u0005[מדד מלח מה\u0006 דינו\u0005],\u0006 האם אף הוא צריך ליטול ידיו מפני חשש מלח סדומית? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי בתשובה: \u0003לא מבעיא\u0004 \u0005[לא נצרכה\u0006 לומר\u0005]\u0006 באדם זה שוודאי צריך נטילת ידים.","ועוד בענין מים אחרונים, \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 בטעם הדבר ש\u0003האי דלא משו מיא בתראי על ארעא\u0004 \u0005[זה שאין נוטלים מים אחרונים על הארץ]\u0006 הריהו \u0003משום זוהמא\u0004 (לכלוך). ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 כלומר, רבה בטעם הדבר שהוא \u0003משום דשריא\u0004 \u0005[ששורה]\u0006 \u0003רוח רעה עלייהו\u0004 \u0005[עליהם]\u0006 והעובר עליהם עלול להיפגע.","\u0003ו\u0004כיוצא בדבר \u0003אמר אביי\u0004 כי \u0003מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 בטעם הדבר ש\u0003האי דלא שקיל מידי מפתורא כי נקיט איניש כסא למשתי\u0004 \u0005[זה\u0006 שאמרו \u0005שאין לקחת דבר מן השולחן בזמן שאדם אוחז כוס לשתות\u0006 בו\u0005]\u0006 הרי זה \u0003שמא יארע דבר קלקלה בסעודה,\u0004 ויכעס אותו אדם האוחז בכוס, שכן חפץ היה בדבר שנלקח מן השולחן, ומתוך שהוא כועס ואינו יכול לדבר עלול הוא להיחנק. ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 בטעם הדבר שהוא \u0003משום דקשי\u0004 \u0005[שקשה,\u0006 שמזיק\u0005]\u0006 הדבר, שיש בו להביא \u0003לרוח צרדא\u0004 (בלבול ואובדן דעת).","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאין לעשות כן, \u0003אלא\u0004 בזה \u0003דשקיל ולא מהדר\u0004 \u0005[שנוטל\u0006 מן השולחן, \u0005ולא מחזיר],\u0006 \u0003אבל משקל ואהדורי\u0004 \u0005[לקחת ולהחזיר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ו\u0004כמו כן \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 שאין לעשות כן \u0003אלא\u0004 שלוקח דבר מן השולחן אל מ\u0003חוץ לארבע אמות\u0004 של מקום השולחן, \u0003אבל\u0004 זה שלוקח דבר מן השולחן ב\u0003תוך ארבע אמות\u0004 של השולחן — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ולא אמרן\u0004 \u0005[ולא אמרנו]\u0006 \u0003אלא מידי דצריך לסעודתא\u0004 \u0005[בדבר שצריך לסעודה],\u0006 \u0003אבל מידי דלא צריך לסעודתא\u0004 \u0005[דבר שלא צריך לסעודה]\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","ומסופר כי \u0003מר בר רב אשי קפיד אפילו אאסיתא ובוכנא דתבלי\u0004 \u0005[היה מקפיד\u0006 שלא לקחת דבר מהשולחן בשעה שאדם עומד ומחזיק כוס בידו, ו\u0005אפילו על מכתשת ובוכנה של תבלינים],\u0006 ככל \u0003מידי דצריכי לסעודתא\u0004 \u0005[הדברים שצריכים לסעודה].\u0006","\u0003ו\u0004עוד כיוצא בזה \u0003אמר אביי\u0004 כי \u0003מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 בטעם הדבר ש\u0003האי דכנשי נשווראה\u0004 \u0005[זה שאוספים\u0006 את \u0005הפירורים\u0006 של הלחם אחר האוכל\u0005]\u0006 הרי זה \u0003משום מנקירותא\u0004 \u0005[נקיון].\u0006 אולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 בטעם הדבר שהוא \u0003משום דקשי לעניותא\u0004 \u0005[שקשה,\u0006 יכול לגרום \u0005לעניות].\u0006","ובענין זה מסופר, \u0003ההוא גברא דהוה מהדר עליה שרא דעניותא,\u0004 \u0003ולא הוה יכיל ליה\u0004 \u0005[אדם אחד שהיה מחזר אחריו שר העניות,\u0006 לעשותו עני, \u0005ולא היה יכול לו]\u0006 משום \u0003דקא זהיר אנשוורא טובא\u0004 \u0005[שהיה זהיר ביותר בפירורים].\u0006 \u0003יומא חד כרך ליפתא איבלי\u0004 \u0005[יום אחד\u0006 אותו אדם \u0005כרך לחמו,\u0006 עשה סעודתו, \u0005על עשבים],\u0006 ונפלו בתוך כך פירורים אל בין העשבים. \u0003אמר\u0004 אותו שר: \u0003השתא\u0004 \u0005[עתה]\u0006 \u0003ודאי נפל בידאי\u0004 \u0005[יפול בידי],\u0006 שהרי אין הוא יכול לאסוף אחריו את הפירורים משם. \u0003בתר דאכיל\u0004 \u0005[אחרי שאכל]\u0006 אותו אדם, \u0003אייתי מרא, עקרינהו ליבלי, שדינהו לנהרא\u0004 \u0005[הביא מעדר, עקר את העשבים, זרק אותם לנהר],\u0006 \u0003שמעיה דקאמר\u0004 \u0005[שמע\u0006 את \u0005שר העניות,\u0006 \u0005שהוא אומר]:\u0006 \u0003ווי, דאפקיה ההוא גברא מביתיה\u0004 \u0005[אוי, שהוציאו אדם זה מביתו].\u0006","\u0003ו\u0004עוד כיוצא בזה \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 כי \u0003האי דלא שתי אופיא\u0004 \u0005[זה שאין שותים\u0006 את \u0005הקצף\u0006 שעל פני המשקה\u0005]\u0006 הרי זה \u0003משום מאיסותא\u0004 \u0005[מאיסות],\u0006 ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 שהוא \u0003משום דקשי\u0004 \u0005[שקשה,\u0006 שמזיק הדבר, שגורם\u0005]\u0006 \u0003לכרסם\u0004 (נזלת מרובה). ומעירים: \u0003מישתיה\u0004 \u0005[לשתות אותו]\u0006 — \u0003קשה\u0004 הדבר \u0003ל\u0004ענין \u0003כרסם, מינפח ביה\u0004 \u0005[לנפוח בו\u0006 בפה, בלא לשתותו\u0005]\u0006 כדי לפנות את הקצף מעל פני המשקה — \u0003קשיא לרישא\u0004 \u0005[קשה\u0006 הדבר \u0005לראש],\u0006 \u0003מדחייה\u0004 \u0005[לדחות אותו\u0006 בידים\u0005]\u0006 — \u0003קשיא לעניותא\u0004 \u0005[קשה\u0006 הדבר \u0005לעניות],\u0006 \u0003מאי תקנתיה\u0004 \u0005[מה\u0006 איפוא היא \u0005תקנתו],\u0006 שבכל זאת ישתמש במשקה? \u0003לשקעיה שקועי\u0004 \u0005[שישקעו\u0006 בפנים\u0005],\u0006 ואז יוכל לשתות.","\u0003לכרסם דחמרא\u0004 \u0005[לנזלת\u0006 הבאה מחמת קצף \u0005היין]\u0006 — התרופה היא \u0003שיכרא\u0004 \u0005[שיכר].\u0006 לנזלת הבאה מחמת קצף \u0003דשיכרא\u0004 \u0005[של שיכר]\u0006 — התרופה היא \u0003מיא\u0004 \u0005[מים].\u0006 לנזלת הבאה מחמת קצף \u0003דמיא\u0004 \u0005[של מים]\u0006 \u0003לית ליה תקנתא\u0004 \u0005[אין לו תקנה],\u0006 \u0003והיינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003בתר עניא אזלא עניותא\u0004 \u0005[אחר העני הולכת העניות],\u0006 שלא די לו שהוא עני, ושותה רק מים, אלא שגם אין תרופה למחלתו.","\u0003ו\u0004עוד כיוצא בזה \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 כי \u0003האי דלא אכלי ירקא מכישא דאסר גינאה\u0004 \u0005[זה שלא אוכלים ירק מאגודה שקשר הגנן]\u0006 הרי \u0003זה\u0004 \u0003משום דמיחזי כרעבתנותא\u0004 \u0005[שנראה\u0006 הדבר \u0005כרעבתנות],\u0006 שאינו ממתין להתיר הקשר אלא אוכל מיד. ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 בטעם הדבר שהוא \u0003משום דקשי\u0004 \u0005[שקשה,\u0006 מזיק הדבר\u0005]\u0006 \u0003ל\u0004ענין \u0003כשפים.\u0004","ומסופר ש\u0003רב חסדא ורבה בר רב הונא הוו קאזלי בארבא\u0004 \u0005[היו הולכים בסירה],\u0006 \u0003אמרה להו ההיא מטרוניתא\u0004 \u0005[להם גבירה אחת]:\u0006 \u0003אותבן בהדייכו\u0004 \u0005[הושיבו אותי יחד איתכם\u0006 בסירה\u0005]!\u0006 \u0003לא אותבוה\u0004 \u0005[לא הושיבוה],\u0006 \u0003אמרה מלתא\u0004 \u0005[דבר]\u0006 של כשפים ו\u0003אסרתה לארבא\u0004 \u0005[קשרה את הסירה]\u0006 למקומה, שלא תזוז. \u0003אמרו אינהו מילתא, שריוה\u0004 \u0005[אמרו הם דבר, התירו אותה\u0006 ממקומה\u0005].\u0006 \u0003אמרה להו\u0004 \u0005[להם]\u0006 אותה גבירה: \u0003מאי איעביד לכו\u0004 \u0005[מה אעשה לכם]\u0006 שאין הכשפים שולטים בכם, \u0003דלא מקנח לכו בחספא\u0004 \u0005[שאין אתם מקנחים עצמכם\u0006 לאחר עשיית צרכים \u0005בחרס],\u0006 \u0003ולא קטיל לכו כינה אמנייכו\u0004 \u0005[ואין אתם הורגים כינה על בגדיכם],\u0006 \u0003ולא אכיל לכו ירקא מכישא דאסר גינאה\u0004 \u0005[ואין אתם אוכלים ירק מאגודה שקשר הגנן].\u0006","\u0003ו\u0004עוד כיוצא בזה \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 בטעם הדבר ש\u0003האי דלא אכלי ירקא דנפל אתכא\u0004 \u0005[זה שלא אוכלים ירק שנפל על השולחן]\u0006 הרי זה \u0003משום מאיסותא\u0004 \u0005[מאיסות],\u0006 ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 שהוא \u0003משום\u0004 ש\u0003קשה\u0004 (מזיק) הדבר \u0003לריח הפה.\u0004 \u0003ו\u0004עוד \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר],\u0006 כי \u0003האי דלא יתבי תותי מרזיבא\u0004 \u0005[זה שלא יושבים תחת המרזב],\u0006 הרי זה \u0003משום שופכים\u0004 שיורדים דרך מרזב זה, ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 שהוא \u0003משום דשכיחי\u0004 \u0005[שמצויים]\u0006 \u0003מזיקין\u0004 שם.","ובענין זה מסופר, \u0003הנהו שקולאי דהוו דרו חביתא דחמרא\u0004 \u0005[אותם סבלים שהיו נושאים חבית יין],\u0006 \u0003בעו לאיתפוחי, אותבוה תותי מרזיבא\u0004 \u0005[רצו לנוח, הניחוה תחת המרזב]\u0006 — \u0003פקעה\u0004 \u0005[פקעה,\u0006 התפוצצה\u0005]\u0006 החבית, \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003מר בר רב אשי, אפיק שיפורי שמתיה\u0004 \u0005[הוציא שופרות, והחרים אותו,\u0006 את השד \u0005שבאותו מקום\u0006\u0005],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 אותו השד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר בר רב אשי: \u0003אמאי תעביד הכי\u0004 \u0005[מדוע עשית כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי אעביד\u0004 \u0005[איך אעשה],\u0006 \u0003כי אותביה באונאי\u0004 \u0005[כאשר הניחו\u0006 אלה את החבית \u0005באוזני]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את בדוכתא דשכיחי רבים, מאי בעית\u0004 \u0005[אתה במקום שמצויים\u0006 בו \u0005רבים, מה מעשיך]?\u0006 \u0003את הוא דשנית\u0004 \u0005[אתה הוא ששינית],\u0006 \u0003זיל שלים\u0004 \u0005[לך ושלם]\u0006 את מחיר חבית היין! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו השד למר בר רב אשי: \u0003השתא נמי ליקבע לי מר זימנא\u0004 \u0005[עכשיו גם כן יקבע לי אדוני זמן]\u0006 עד שאאסוף את הכסף, \u0003ואפרע, קבע ליה זימנא\u0004 \u0005[לו זמן].\u0006 \u0003כי מטא זימנא, איעכב\u0004 \u0005[כאשר הגיע הזמן, התעכב]\u0006 השד מלבוא ולשלם. \u0003כי אתא\u0004 \u0005[כאשר\u0006 לבסוף \u0005בא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר בר רב אשי: \u0003אמאי לא אתית\u0004 \u0005[מדוע לא באת]\u0006 \u0003בזמנך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל מילי דצייר וחתים וכייל ומני\u0004 \u0005[כל דבר ש\u0006הוא \u0005צרור וחתום ומדוד ומנוי]\u0006 \u0003לית לן רשותא למשקל מיניה\u0004 \u0005[אין לנו רשות לקחת ממנו],\u0006 ולכן לא מצאתי עד כה כסף, \u0003עד דמשכחינן מידי דהפקרא\u0004 \u0005[עד שאנו מוצאים דבר של הפקר],\u0006 ולכן היה צריך לחפש במשך זמן רב עד שמצא כסף.","\u0003ו\u0004עוד \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 כי \u0003האי דשדי מיא מפומא דחצבא\u0004 \u0005[זה ששופכים\u0006 מעט \u0005מים מפי הכד]\u0006 לפני ששותים ממנו, הרי זה \u0003משום ציבתא\u0004 \u0005[הקיסמים]\u0006 שיש בו, ואולם \u0003אמר לי מר\u0004 \u0005[אדוני]\u0006 שהוא \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 בכד \u0003מים הרעים.\u0004","ובענין זה מסופר, \u0003ההוא בר שידא דהוה בי\u0004 \u0005[בן שד אחד שהיה בבית]\u0006 \u0003רב פפא\u0004 והיה משרתו, \u0003אזל לאתויי מיא מנהרא\u0004 \u0005[הלך להביא מים מן הנהר]\u0006 \u0003איעכב\u0004 \u0005[התעכב].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי איעכבת\u0004 \u0005[מדוע התעכבת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003עד דחלפי\u0004 \u0005[שיחלפו]\u0006 ויצאו משם ה\u0003מים הרעים, אדהכי\u0004 \u0005[בתוך כך]\u0006"],["\u0003חזנהו דקא שדו מיא מפומא דחצבא\u0004 \u0005[ראה\u0006 אותו השד \u0005אותם,\u0006 את בני ביתו של רב פפא, \u0005שהם שופכים מים מפי הכד]\u0006 לפני שהם שותים ממנו, \u0003אמר\u0004 להם השד: \u0003אי הוה ידענא דרגיליתו למיעבד הכי, לא איעכבי\u0004 \u0005[אם הייתי יודע שאתם רגילים לעשות כך, לא הייתי מתעכב],\u0006 שכן הייתי מביא לכם מיד מים מהנהר, \u0005ואתם הייתם שופכים את המים הרעים שבהם.\u0006","ושבים לענין נטילת מים ראשונים ואחרונים. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 כי \u0003מים הראשונים\u0004 שלא ניטלו, גרמו לכך ש\u0003האכילו\u0004 אדם מישראל \u0003בשר חזיר,\u0004 ומים","\u0003אחרונים\u0004 שלא ניטלו גרמו ש\u0003הוציאו את\u0004 \u0003האשה מבעלה\u0004 בגט. שמעשה היה בחנווני מישראל שהיה מוכר בשר מבושל כשר לאדם מישראל הקונה אצלו, ואילו לגוי הקונה אצלו היה מוכר בשר שאינו כשר. ופעם אחת בא לסעוד אצלו אדם מישראל, ומאחר ואדם זה לא נטל את ידיו בנטילת ידים ראשונים לסעודה, סבור היה החנווני כי הוא גוי, ונתן לו לאכול מבשר חזיר. הרי, שגרמו מים ראשונים שלא ניטלו, שיאכל אדם מישראל בשר חזיר. וכן מסופר שהתארחו חכמים בבית האכסניה של אדם אחד, והפקידו את כספם למשמרת אצלו. ולמחרת כיחש אותו אדם וטען שלא קיבל מהם כל כסף. עמדו חכמים ופיתו אותו אדם לשתות יין איתם, וראו שעדשים דבוקות לו על שפמו (שלא נטל ידיו לאחר סעודתו, ולא העבירן על פניו ושפמו, כדרך נוטלי מים אחרונים), הלכו לאשתו של אותו אדם ואמרו לה כי בעלה שלחם להביא לו את כספם. וכסימן ששלוחיו הם אמרו לה שבעלה אמר להם שיאמרו לאשתו שאכל עדשים באותו יום. האמינה להם האשה על סמך זאת, ונתנה להם את כספם. ומשבא בעלה לביתו ונודע לו שאשתו מסרה להם את הכסף, כעס עליה וגירשה. הרי שמים אחרונים שלא ניטלו גרמו לגירושי אשה. ובענין זה עוד נמסר,","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, סיפר אף הוא כדברי רב דימי, בשינוי קטן, שכך \u0003אמר:\u0004 מים \u0003ראשונים\u0004 שלא ניטלו גרמו ש\u0003האכילו בשר נבלה\u0004 לאדם מישראל. ואילו מים \u0003אחרונים\u0004 שלא ניטלו גרמו ש\u0003הרגו את הנפש.\u0004 שבאותו מעשה לא גירש בעל האכסניה את אשתו, אלא הרגה. \u0003אמר רב נחמן בר יצחק, וסימניך\u0004 שתזכור ייחוס השמועות לאומרן: \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב דימי אפקה\u0004 \u0005[הוציא אותה],\u0006 שלגירסתו הבעל הוציא את אשתו. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רבין קטלה\u0004 \u0005[הרג אותה],\u0006 שכן לגירסתו הבעל הרג את אשתו.","\u0003ר' אבא מתני חדא מהני וחדא מהני\u0004 \u0005[היה שונה אחת מאלה\u0006 הנוסחות במים ראשונים \u0005ואחת מאלה\u0006 הנוסחות במים אחרונים\u0005],\u0006 ובשתיהן היה גורס \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שבמים ראשונים גרס שהם גרמו להאכלת בשר חזיר (שחמור מאכילת בשר נבילה, שהרי יש בו שני איסורי אכילה), ובמים אחרונים גרס שהם גרמו להריגת האשה.","ועוד בדין מים ראשונים לנטילת ידים לסעודה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדין \u0003חמי האור\u0004 (מים שנתחממו באש) לנטילת ידים. \u0003חזקיה אמר\u0004 ש\u0003אין נוטלים מהן לידים, ו\u0004אילו \u0003ר' יוחנן אמר\u0004 ש\u0003נוטלין מהם לידים. אמר ר' יוחנן\u0004 כראיה לשיטתו: בהלכה זו \u0003שאלתי את רבן גמליאל בנו של רבי, ואוכל טהרות\u0004 היה, ומקפיד בדיני נטילת ידים, \u0003ואמר לי\u0004 כי \u0003כל גדולי גליל עושין כן,\u0004 שנוטלים ידים בחמי האור.","וכן נחלקו חכמים אלה בדין \u0003חמי טבריא.\u0004 ש\u0003חזקיה אמר\u0004 כי \u0003אין נוטלין מהם\u0004 \u0003לידים\u0004 למים ראשונים, \u0003אבל מטבילין בהם\u0004 את \u0003הידים\u0004 (אם יש במים ארבעים סאה, כשיעור מקוה טהרה), ועולה הטבלה זו (אף שאין בה כלי) כנטילת ידים לסעודה. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי לצורך טהרתו של אדם הטמא, \u0003כל גופו טובל בהן,\u0004 ונטהר בכך. \u0003אבל לא\u0004 משמשים חמי טבריה לטבילת חלק מגופו, כ\u0003פניו ידיו ורגליו,\u0004 שאין הטבלת ידים בהם נחשבת כנטילה. ותוהים על דברי ר' יוחנן אלה:","\u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003כל גופו טובל בהם,\u0004 בחמי טבריה, שטבילה בהם מטהרת את הטמא, טבילת \u0003פניו ידיו ורגליו לא כל שכן\u0004 שתועיל, ומדוע אין טבילת ידים נחשבת כנטילה? \u0003אמר רב פפא\u0004 בהסבר שיטת ר' יוחנן וחזקיה: טבילת ידים בחמי טבריה הנמצאים \u0003במקומן\u0004 — \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים\u0006 בדבר, וסבורים \u0005שמותר],\u0006 וכמו כן לענין \u0003משקל מינייהו במנא\u0004 \u0005[לקחת מהם בכלי]\u0006 וליטול בהם את הידים — \u0003דכולי עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חלוקים שאסור].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו\u0006 חזקיה ור' יוחנן\u0005]\u0006 הרי זה בזמן \u0003דפסקינהו בבת בירתא\u0004 \u0005[שמשכם בתעלה],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה האוסר נטילה במים אלה, \u0005סבור]\u0006 כי \u0003גזרינן בת בירתא אטו מנא\u0004 \u0005[גוזרים אנו\u0006 במי \u0005תעלה משום\u0006 מי \u0005כלי].\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן המתיר נטילה בהם, \u0005סבור]\u0006 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 על מי תעלה משום מי כלי.","ומעירים: מחלוקתם של חזקיה ור' יוחנן הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בענין זה. ששנינו: \u0003מים שנפסלו\u0004 (שאינם ראויים עוד) \u0003מ\u0004לשמש ל\u0003שתיית בהמה,\u0004 כשהם נתונים \u0003בכלים\u0004 — הריהם \u0003פסולים\u0004 לנטילת ידים. אבל כשהם \u0003בקרקע,\u0004 לטבול בהם — הריהם \u0003כשרין,\u0004 שהריהם כמקוה כשר. \u0003ר' שמעון בן אלעזר אומר: אף\u0004 הכשרם של מים אלה ש\u0003בקרקע,\u0004 ולענין טבילה, הריהו דווקא בש \u0003טובל בהן\u0004 האדם הטמא את \u0003כל גופו, אבל לא\u0004 להטבלת \u0003פניו ידיו ורגליו.\u0004","ותוהים על דברי ר' שמעון בן אלעזר: \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאמרנו כי \u0003כל גופו טובל בהן, ידיו ורגליו לא כל שכן\u0004 שטובל בהם! והסקנו: \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003דפסקינהו בבת בירתא\u0004 \u0005[שמשכם בתעלה],\u0006 \u0003ובהא פליגי\u0004 \u0005[ובזה חלוקים\u0006 התנא הראשון ור' שמעון בן אלעזר\u0005]:\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' שמעון בן אלעזר האוסר טבילת \u0005ידים במימי תעלה,\u0006 \u0005סבור]\u0006 כי \u0003גזרינן בת בירתא אטו מנא\u0004 \u0005[גוזרים אנו\u0006 במי \u0005תעלה משום\u0006 מי \u0005כלי],\u0006 \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 התנא הראשון המתיר, \u0005סבור]\u0006 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","ובעיקר דין נטילת ידים לסעודה, \u0003אמר רב אידי בר אבין, אמר רב יצחק בר אשיאן: נטילת ידים ל\u0004אכילת \u0003חולין,\u0004 הריהי תקנת חכמים \u0003מפני סרך תרומה.\u0004 שכן קבעו חכמים כי נחשבות הידים כ\"שניות לטומאה\", ופוסלות במגען את התרומה, ולכן צריכים הכהנים אוכלי התרומה ליטול ידיהם לפני האכילה. והנהיגו כן חכמים אף בחולין, שאילו לא היו נוטלים ידים לחולין, היה נגרר הדבר אף לאכילת תרומה.","\u0003ועוד\u0004 טעם לנטילת ידים לחולין: \u0003משום מצוה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"משום \u0003מצוה\"? אמר אביי: מצוה לשמוע דברי חכמים\u0004 שתיקנו נטילת ידים זו. \u0003רבא אמר: מצוה לשמוע דברי ר' אלעזר בן ערך, דכתיב\u0004 \u0005[ש\u0006כן על ה\u0005נאמר]\u0006 בדינו של הזב הטמא \u0003\"וכל אשר יגע בו הזב וידיו לא שטף במים\"\u0004 (ויקרא טו, יא), \u0003אמר ר' אלעזר בן ערך: מכאן סמכו חכמים לנטילת ידים\u0004 (עשו סמך לדבריהם בענין חובת נטילת ידים) \u0003מן התורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי משמע\u0004 \u0005[מה משמע\u0006 הדבר מכתוב זה\u0005]?\u0006 ומסביר: אם תאמר שהוא משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וידיו לא שטף במים\",\u0004 והיה מקום לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003שטף\u0004 — הריהו \u0003טהור\u0004 — אין לומר כן, שהרי אין הזב נטהר בכך, כי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003טבילה\u0004 הוא \u0003בעי\u0004 \u0005[צריך]!\u0006 \u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 שכך \u0005נדייק בכתוב\u0006\u0005]:\u0006 כדרך שהזב טמא, \u0003ו\u0004כן הוא אדם \u0003אחר ש\u0004אינו זב, אבל \u0003לא שטף\u0004 ידיו — אף הוא כ\u0003טמא.\u0004 והרי זו אסמכתא מן הכתוב לנטילת ידים.","ועוד בדין נטילת ידים. \u0003אמר ר' אלעזר, אמר ר' אושעיא: לא אמרו\u0004 (תיקנו) חכמים \u0003נטילת ידים ל\u0004אכילת \u0003פירות אלא משום נקיות.\u0004 ומעירים: \u0003סבור מינה\u0004 \u0005[חשבו\u0006 החכמים \u0005מכאן\u0006 מתוך דבריו\u0005]\u0006 כי אמנם \u0003חובה הוא דליכא\u0004 \u0005[שאין]\u0006 ליטול ידיים לאכילת פירות, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מצוה איכא\u0004 \u0005[יש].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: לא חובה ולא מצוה\u0004 יש בדבר זה, \u0003אלא רשות\u0004 בלבד. \u0003ו\u0004מציינים כי \u0003פליגא\u0004 \u0005[חלוק]\u0006 רבא בדעתו זו על דעת \u0003רב נחמן,\u0004 שכן \u0003אמר רב נחמן: הנוטל ידיו לפירות אינו אלא מגסי הרוח,\u0004 שאין בכך אף רשות, אלא אסור לעשות כן.","ובענין זה \u0003אמר רבה בר בר חנה: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003ר' אמי ור' אסי, אייתו לקמייהו כלכלה דפירי\u0004 \u0005[הביאו לפניהם סל של פירות],\u0006 \u0003ואכלו\u0004 מהם \u0003ולא משו ידייהו\u0004 \u0005[ולא נטלו\u0006 קודם לכן \u0005ידיהם],\u0006 \u0003ולא יהבו\u0004 \u0005[נתנו]\u0006 \u0003לי מידי\u0004 \u0005[דבר]\u0006 לאכול, כדי שאוכל להצטרף אליהם לזימון. \u0003ובריך חד חד לחודיה\u0004 \u0005[ובירך כל אחד\u0006 מהם \u0005לעצמו].\u0006 \u0003שמע מינה תלת\u0004 \u0005[למד מכאן שלוש\u0006 הלכות\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אין נטילת ידים לפירות, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003אין מזמנין על הפירות, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003שנים שאכלו\u0004 — \u0003מצוה\u0004 להם \u0003ליחלק,\u0004 שכל אחד יברך לעצמו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שנים שאכלו\u0004 — \u0003מצוה\u0004 עליהם \u0003ליחלק. במה דברים אמורים?\u0004 בזמן \u0003שהיו שניהם סופרים,\u0004 כלומר, תלמידי חכמים, היודעים יפה לברך. \u0003אבל\u0004 אם היה \u0003אחד\u0004 מהם \u0003סופר ואחד\u0004 מהם היה \u0003בור\u0004 שאינו יודע לברך כהלכה — \u0003סופר מברך, ובור יוצא\u0004 ידי חובתו בשמיעת הברכה.","ועוד בדין נטילת ידים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נטילת ידים ל\u0004אכילת \u0003חולין\u0004 צריכה להיעשות בחלק כף היד ש\u0003עד הפרק\u0004 השני, באמצע אצבעות כף היד. נטילת ידים \u0003ל\u0004אכילת \u0003תרומה\u0004 —"],["\u0003עד הפרק\u0004 של מקום חיבור האצבעות לכף היד. \u0003קידוש ידים ורגלים במקדש\u0004 הריהו נעשה \u0003עד הפרק\u0004 של חיבור כף היד לזרוע. \u0003וכל דבר ש\u0004נחשב כ\u0003חוצץ בטבילה בגוף\u0004 האדם הטובל, שלא עלתה לו טבילתו בגלל חציצה זו, הריהו \u0003חוצץ\u0004 גם \u0003בנטילת ידים ל\u0004אכילת \u0003חולין, ו\u0004גם \u0003בקידוש ידים ורגלים במקדש.\u0004","ומסופר כי על דברים אלה שבברייתא \u0003אמר רב\u0004 לתלמידיו עם שהוא מראה להם את ידו: \u0003עד כאן,\u0004 עד הפרק השני שבכף היד, הריהו מקום נטילת ידים \u0003ל\u0004אכילת \u0003חולין.\u0004 ואילו \u0003עד כאן,\u0004 עד הפרק השלישי בכף היד, הריהו מקום נטילת ידים \u0003ל\u0004אכילת \u0003תרומה. ו\u0004אף \u0003שמואל\u0004 הראה לתלמידיו בידו היכן הוא מקומן של נטילות ידים. ואולם שלא כשיטת רב \u0003אמר: עד כאן,\u0004 עד סוף הפרק השלישי בכף היד, הריהו מקום נטילת ידים \u0003בין ל\u0004אכילת \u0003חולין בין ל\u0004אכילת \u0003תרומה,\u0004 שיש לנהוג בחולין \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 בהם כבתרומה. \u0003ו\u0004כיוצא בדבר אף \u0003רב ששת\u0004 הראה לתלמידיו בידו היכן הוא מקומן של נטילות ידים. ושלא כשיטות רב ושמואל \u0003אמר: עד כאן,\u0004 עד סוף הפרק השני, הריהו מקומם של נטילות ידים, \u0003בין\u0004 \u0003לחולין בין לתרומה,\u0004 שכן יש לנהוג בתרומה \u0003לקולא\u0004 \u0005[להקל]\u0006 בנטילת ידים בה כבחולין.","\u0003אמר בר הדיא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003ר' אמי, ואמר: עד כאן,\u0004 עד סוף הפרק השלישי, הריהו מקומה של נטילת ידים, \u0003בין לחולין בין לתרומה,\u0004 שכן יש לנהוג \u0003בנטילת ידים לחולין\u0004 \u0003לחומרא\u0004 כדרך שנוטלים לתרומה. \u0003ולא תימא\u0004 \u0005[ואל תאמר]\u0006 שנהג כן \u0003ר' אמי משום\u0004 ש\u0003כהן הוא\u0004 ואצלו יש חשש שיערב בין תרומה לחולין, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' מיישא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' יהושע בן לוי\u0004 ש\u0003הוא ליואי\u0004 \u0005[לוי],\u0006 ולא כהן, \u0003ו\u0004אף הוא \u0003אמר: עד כאן,\u0004 עד סוף הפרק השלישי, הריהו מקומה של נטילת ידים, \u0003בין לחולין בין לתרומה,\u0004 שיש לנהוג בנטילת ידים לחולין \u0003לחומרא,\u0004 כדרך שנוטלים לתרומה.","ועוד בדיני נטילת ידים. \u0003אמר רב:\u0004 מותר שיהא \u0003נוטל אדם את שתי ידיו\u0004 ב\u0003שחרית\u0004 (בבוקר) \u0003ומתנה עליהן\u0004 שעל סמך זה יוכל לאכול \u0003כל היום כולו,\u0004 ובלבד שייזהר מלכלוך ידיו ומטומאתן. וכן נמסר ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אבינא לבני\u0004"],["\u0003פקתא\u0004 \u0005[בקעה]\u0006 של \u0003ערבות,\u0004 שלא היו מים מצויים שם: \u0003כגון אתון\u0004 \u0005[אתם],\u0006 \u0003דלא שכיחי לכו מיא\u0004 \u0005[שאין מצויים לכם מים],\u0006 \u0003משו ידייכו מצפרא, ואתנו עלייהו לכולא יומא\u0004 \u0005[נטלו ידיכם מן הבוקר, והתנו עליהם לכל היום].\u0006 ומתוך הוראת ר' אבינא \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלדעתו \u0003בשעת הדחק\u0004 (כגון במקום שלא מצוי בו מים, וכפקתא דערבות) — \u0003אין\u0004 \u0005[כן]\u0006 יש לנהוג כך, ואולם ב\u0003שלא בשעת הדחק\u0004 — \u0003לא\u0004 נוהגים כן, \u0003ו\u0004נמצא איפוא כי \u0003פליגא\u0004 \u0005[חלוקה]\u0006 שיטתו של ר' אבינא על שיטת \u0003רב\u0004 שהתיר לנהוג כן בכל האופנים. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שר' אבינא הורה כן \u0003אפילו שלא בשעת הדחק נמי\u0004 \u0005[גם כן],\u0006 \u0003ו\u0004נמצא איפוא כי \u0003היינו\u0004 \u0005[זהו]\u0006 כשיטתו של \u0003רב.\u0004","ועוד בדיני נטילת ידים, \u0003אמר רב פפא: האי אריתא דדלאי\u0004 \u0005[זו תעלת ההשקיה],\u0006 שנהגו בהשקיית שדותיהם, שהיו מושכים מים מן הנהר באמצעות תעלות המובילות את המים אל השדות, ואת המים מן הנהר אל התעלות היו דולים בדליים — \u0003אין נוטלין ממנו\u0004 (ממימי התעלה) \u0003לידים,\u0004 וטעם הדבר: משום שהמים הללו \u0003לא אתו\u0004 \u0005[אינם באים]\u0006 \u0003מכח גברא\u0004 \u0005[אדם],\u0006 אלא מזרימת המים שבצינור. \u0003ו\u0004אולם \u0003אי מיקרב לגבי דולא\u0004 \u0005[אם קרוב\u0006 הנוטל ידיו \u0005אצל הדלי],\u0006 ובאופן \u0003דקאתו\u0004 \u0005[שבאים]\u0006 המים על ידיו \u0003מכח גברא\u0004 \u0005[האדם]\u0006 הדולה מן הנהר \u0003נוטלין ממנו לידים.\u0004","\u0003ואי בזיע דולא\u0004 \u0005[ואם מנוקב הדלי]\u0006 בו נשאבים המים מן הנהר, \u0003ב\u0004שיעור שבכדי \u0003כונס משקה\u0004 (שאם יונח הכלי על הנהר, חודרים לתוכו מים), ובשעה שדולה מים מהנהר בדלי זה, \u0003מילף לייפי\u0004 \u0005[דבוקים,\u0006 מחוברים\u0005]\u0006 המים שבדלי אל מי הנהר, שחלק מהם שב לאחור אל הנהר — המים שבדלי נחשבים כמחוברים למי הנהר, \u0003ו\u0004לכך \u0003מטביל בה את הידים.\u0004 אולם כלי שניקב בשיעור זה אינו כשר אלא לטבילת ידים, ואולם אין נוטלים ידים מכלי שכזה, שכן אין הוא נחשב עוד כ\"כלי\", שכך \u0003אמר רבא: כלי שניקב ב\u0004שיעור שהוא \u0003כונס משקה\u0004 — \u0003אין נוטלין ממנו לידים.\u0004","\u0003ו\u0004עוד בדין הכלי הראוי לנטילת ידים \u0003אמר רבא:\u0004 כל \u0003כלי שאין בו\u0004 מים בשיעור \u0003רביעית\u0004 — \u0003אין נוטלין ממנו לידים.\u0004 ושואלים על כך: \u0003איני\u0004 \u0005[האמנם כן]\u0006 הורה רבא, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא\u0004 כי כל \u0003כלי שאין\u0004 בו נפח שיהא \u0003מחזיק\u0004 (מכיל) \u0003רביעית\u0004 מים — \u0003אין נוטלין ממנו לידים,\u0004 ומכאן יש לדייק: כל כלי שאין בו שיעור כזה — איננו כשר לנטילה. \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא \u0003מחזיק\u0004 שיעור רביעית, \u0003אף על גב דלית ביה\u0004 \u0005[אף על פי שאין בו]\u0006 עכשיו רביעית מים הוא כשר לנטילה ממנו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שצריך שיהיה בכלי מים בשיעור רביעית — מדובר \u0003ל\u0004ענין נטילת ידים של \u0003חד\u0004 \u0005[אחד],\u0006 שכל הבא ליטול ידיו, צריך שיהיה בכלי שיעור זה. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שדי שיש בכלי שיעור רביעית, אף שאין בו רביעית מים בפועל — מדובר \u0003ל\u0004ענין נטילת ידים של \u0003תרי\u0004 \u0005[שנים],\u0006 שבתחילה היו בכלי זה מים בשיעור רביעית, ברם לאחר שהראשון נטל ידיו מכלי זה, לא נותרו בכלי מים בשיעור רביעית, ובכל זאת יצא השני ידי חובתו בנטילה מכלי זה, שכן המים הנותרים הינם כהמשכם של המים הראשונים שהיו ראויים לנטילה (\"שיירי טהרה\"). \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בדברי תנאים\u0005]:\u0006 \u0003מי\u0004 נטילה ששיעורם \u0003רביעית\u0004 — \u0003נוטלין\u0004 מהם \u0003לידים ל\u0004אדם \u0003אחד, ואפילו לשנים.\u0004","ועוד בענין הכלי לנטילת ידים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לאמימר\u0004 בשאלה: האם \u0003קפדיתו אמנא\u0004 \u0005[אתם מקפידים על הכלי]\u0006 לנטילת ידים שיהיה שלם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003אין\u0004 \u0005[כן].\u0006 חזר ושאלו: האם מקפידים אתם \u0003אחזותא\u0004 \u0005[על המראה]\u0006 של המים, שיהיה מראם כמראה מים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003אין\u0004 \u0005[כן].\u0006 הוסיף רב ששת ושאל: האם מקפידים אתם \u0003אשיעורא\u0004 \u0005[על השיעור]\u0006 של המים שיהיה רביעית, ולא פחות מכך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003אין\u0004 \u0005[כן].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן שונה את תשובת אמימר לרב ששת, \u0003ש\u0004\u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמנא ואחזותא\u0004 \u0005[על הכלי ועל המראה]\u0006 — \u0003קפדינן\u0004 \u0005[אנו מקפידים],\u0006 ואולם \u0003אשיעורא\u0004 \u0005[על השיעור]\u0006 — \u0003לא קפדינן\u0004 \u0005[אין אנו מקפידים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בדברי חכמים\u0005]:\u0006 \u0003מי רביעית נוטלין\u0004 מהם \u0003לידים ל\u0004אדם \u0003אחד, ואפילו לשנים.\u0004 הרי שאין צורך ברביעית מים לכל אחד. ודוחים:","\u0003ולא היא,\u0004 אין מכאן ראיה, כי \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד, \u0005שם]\u0006 הדין, שאין צורך ברביעית מים לנוטל השני, \u0003משום דקאתו\u0004 \u0005[שבאו]\u0006 המים \u0003משירי טהרה.\u0004 כיון שמתחילה היה בהם שיעור הראוי לטהרה.","ובענין נפח הכלי לנטילת ידים, נמסר כי \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב יעקב מנהר פקוד נטלא בת רביעתא\u0004 \u0005[כלי נטילה העשוי זכוכית בן,\u0006 שיש בו, שיעור \u0005רביעית].\u0006 וכן \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב אשי ב\u0004עיר \u0003הוצל כוזא בת רביעתא\u0004 \u0005[כלי נטילה העשוי חרס בן רביעית].\u0006","\u0003ו\u0004עוד בדיני הכלי הראוי לנטילת ידים, \u0003אמר רבא: מגופת\u0004 (מכסה) \u0003חבית ש\u0004עמד אדם ו\u0003תקנה\u0004 (התקין אותה) שתשמש לנטילת ידים. שחקק בתוכה, כדי שתוכל המגופה לשמש כבית קיבול לרביעית מים — \u0003נוטלין ממנה לידים,\u0004 אף שמעיקרה לא נועדה המגופה לשם כך. \u0003ו\u0004\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא האומרת \u0005גם כן כך]:\u0006 \u0003מגופת חבית שתקנה\u0004 — \u0003נוטלין ממנה לידים.\u0004 וכיוצא בדבר \u0003חמת וכפישה\u0004 שהן נאדות של עור \u0003שתקנן\u0004 שישמשו לנטילת ידים — \u0003נוטלין מהם לידים.\u0004 שמעיקרם נועדו לשמש ככלים לנוזלים. ואולם \u0003שק וקופה, אף על פי שמקבלים,\u0004 כלומר, שהם יכולים להכיל בתוכם מים — \u0003אין נוטלין מהם לידים.\u0004 שכן אין עיקר תפקידם להכיל מים בתוכם, לפי שרובם אינם ראויים לכך.","למעלה התבררו דיני נטילת ידים. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: \u0003מהו\u0004 הדין, האם מותר \u0003לאכול\u0004 פת \u0003במפה\u0004 (פיסת בד, כמטלית) הנתונה על ידו, ובלי ליטול ידיים? וצדדי השאלה: \u0003מי חיישינן דלמא נגע\u0004 \u0005[האם חוששים אנו שמא יגע]\u0006 בידיו בפת, אף שנתונה עתה מפה עליהן. ולכך הריהו צריך נטילת ידים, אף באופן זה. \u0003או\u0004 שמא \u0003לא\u0004 חוששים לדבר זה, ודי בנתינת המפה על ידיו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003וכשנתנו לו לר' צדוק\u0004 בחג הסוכות, \u0003אוכל\u0004 ששיעורו הוא \u0003פחות מכביצה\u0004 — היה \u0003נוטלו במפה\u0004 שעל ידיו, \u0003ו\u0004היה \u0003אוכלו חוץ לסוכה\u0004 (שלדעתו אין אדם חייב בחג הסוכות באכילת אוכל בשיעור כזה דווקא בסוכה), \u0003ואין\u0004 הוא \u0003מברך אחריו\u0004 ברכת המזון, שאין זו אכילה שיש בה שביעה. ונדייק מכאן: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן כי \u0003הא\u0004 \u0005[הרי]\u0006 שאם היה אוכל בשיעור \u0003כביצה\u0004 — \u0003בעי\u0004 \u0005[צריך]\u0006 היה \u0003נטילת ידים,\u0004 אף שאכל במפה על ידיו.","ודוחים: אין זו ראיה, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 כך יש לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה אוכל ששיעורו \u0003כביצה\u0004 — \u0003בעי\u0004 \u0005[צריך]\u0006 לאוכלו דווקא ב\u0003סוכה, ובעי\u0004 \u0005[וצריך]\u0006 לברך אחר אכילתו \u0003ברכה,\u0004 ברכת המזון, אך אפשר לומר שניתן לאכול אותו במפה, ובלא נטילת ידים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה שמסופר כי \u0003שמואל אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב דקאכיל\u0004 \u0005[שהוא אוכל]\u0006 \u0003במפה\u0004 על ידיו, ובלא נטילת \u0003ידים.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לרב:"],["האם \u0003עבדין כדין\u0004 \u0005[עושים כך],\u0006 כלומר, האם כך ראוי לאכול פת, בלא נטילת ידים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב לשמואל בתשובה: נטלתי לפני כן את ידי, ואולם משום ש\u0003דעתי קצרה עלי\u0004 (שאני איסטניס), איני רוצה לאכול בידים חשופות, ולכך שמתי עליהן מטפחת.","ועוד מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 מבבל לארץ ישראל, \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 את \u0003ר' אמי ור' אסי דקאכלי בבלאי חמתות\u0004 \u0005[שהם אוכלים\u0006 פת \u0005בבלאי חמת,\u0006 קרעי חמתות שהתבלו\u0005]\u0006 ששמו על ידיהם ובלי שנטלו ידים, \u0003אמר\u0004 להם ר' זירא: \u0003תרי גברי רברבי כוותייכו, ליטעו\u0004 \u0005[שני אנשים גדולים כמותכם, שיטעו]\u0006 \u0003ב\u0004דברי \u0003רב ושמואל\u0004 המסופרים למעלה? ו\u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"דעתי קצרה\" קאמר\u0004 \u0005[\u0006\u0005הוא\u0006 שרב \u0005אמר]\u0006 לשמואל, ולכך אכל בבגד על ידיו, ואולם הוא נטל את ידיו לפני כן, ולא התיר רב לאכול כך בלא נטילת ידים!","ואומרים: \u0003אשתמיטתיה הא דאמר\u0004 \u0005[נשמט ממנו,\u0006 מר' זירא, דין \u0005זה שאמר]\u0006 \u0003רב תחליפא בר אבימי\u0004 שכך \u0003אמר שמואל: התירו\u0004 חכמים לאכול פת ב\u0003מפה\u0004 הכרוכה על הידים ובלא \u0003נטילת ידים,\u0004 \u0003ל\u0004כהנים \u0003אוכלי תרומה,\u0004 שכן הכהנים הינם זריזים וזהירים במעשיהם, ולא יבואו לנגוע בפת. \u0003ולא התירו\u0004 לאכול כן ב\u0003מפה\u0004 הכרוכה על הידים, \u0003ל\u0004ישראלים \u0003אוכלי טהרות\u0004 (המקפידים על אכילת חולין שלהם, שתיאכל בטהרת המאכל והאדם האוכל), לפי שאין הם רגילים בהנהגות זריזות ובזהירות ככהנים. \u0003ור' אמי ור' אסי כהנים הוו\u0004 \u0005[היו],\u0006 הזהירים וזריזים במעשיהם, ולכך ראויים הם לאכול במפה, ובלא נטילת ידים.","ועוד בחובת נטילת ידים שלפני האכילה, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 אדם ה\u0003אוכל מחמת מאכיל,\u0004 כלומר, שהוא עצמו אינו נוגע באוכל אלא אחר מאכיל אותו, האם האוכל \u0003צריך נטילת ידים\u0004 לאכילה זו, \u0003או\u0004 \u0003לא,\u0004 שהרי אינו נוגע באוכל? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה שנמסר כי \u0003רב הונא בר סחורה הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב המנונא,\u0004 ומשמש לפניו. \u0003בלם ליה אומצא, ואכיל\u0004 \u0005[חתך לו\u0006 רב הונא בר סחורה לרב המנונא \u0005חתיכת בשר\u0006 ונתנה בפיו, \u0005ואכל],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא בר סחורה לרב המנונא: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003רב המנונא את\u0004 \u0005[אתה],\u0006 \u0003לא ספינא לך\u0004 \u0005[לא הייתי מאכיל אותך]\u0006 בלא נטילת ידים.","ומדייקים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 יכול היה רב המנונא לאכול באופן זה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שהריהו \u0003זהיר ולא נגע\u0004 \u0005[ואינו נוגע]\u0006 בידיו במאכל. ומכאן שאם אדם מואכל על ידי אחר, והאוכל נזהר מלגעת במאכל, מותרת לו אף בלא נטילת ידים. ודוחים \u0003:\u0004 \u0003לא,\u0004 אין זו ראיה. שכן אפשר לומר שרב המנונא \u0003זריז\u0004 היה, ולכך \u0003קדים ומשי ידיה מעיקרא\u0004 \u0005[הקדים ונטל ידיו מתחילה].\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ש\u0003אמר ר' זירא\u0004 שכך \u0003אמר רב: לא יתן אדם פרוסה לתוך פיו של\u0004 ה\u0003שמש\u0004 המשרת בסעודה, \u0003אלא אם כן יודע בו\u0004 בשמש \u0003שנטל\u0004 את \u0003ידיו. ו\u0004בדינו של \u0003השמש\u0004 נאמר שהריהו \u0003מברך על כל כוס וכוס\u0004 של יין שנותנים לו מן הסעודה, שאינו יודע אם יתנו לו כוס נוספת, ולכך לאחר שתיית כל כוס הריהו מסיח דעתו משתיית יין. \u0003ו\u0004אולם הוא \u0003אינו מברך על כל פרוסה ופרוסה\u0004 שניתנת לו. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי אף \u0003מברך\u0004 השמש \u0003על כל פרוסה ופרוסה\u0004 הניתנת לו.","\u0003אמר רב פפא: בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003רב ור' יוחנן לא קשיא\u0004 \u0005[אינו קשה]\u0006 מדברי האחד על חבירו, שאפשר לומר שאינם חולקים, וכל אחד מדבר במקרה שונה. כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב שהשמש אינו מברך על כל פרוסה ופרוסה — מדובר בסעודה \u0003דאיכא\u0004 \u0005[שיש]\u0006 בה \u0003אדם חשוב,\u0004 ולכך בטוח השמש שהאדם החשוב ידאג שתהיה לו פת כל צורכו, ואינו מסיח דעתו מלאכול. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוחנן שהשמש מברך על כל פרוסה ופרוסה — מדובר בסעודה \u0003דליכא\u0004 \u0005[שאין]\u0006 בה \u0003אדם חשוב,\u0004 ולכך אין השמש בטוח שיזכה לפרוסה נוספת, ומסיח דעתו, ומשום כך לכשתנתן לו פרוסה נוספת הריהו צריך לברך עליה.","\u0003מכל מקום הא קאמר\u0004 \u0005[הרי הוא,\u0006 רב, \u0005אומר]\u0006 בתחילת דבריו כי שאין לתת פרוסה לתוך פי השמש \u0003אלא אם כן יודע\u0004 הנותן בשמש זה \u0003שנטל\u0004 את \u0003ידיו.\u0004 ומכאן ראיה שהמואכל על ידי אחר צריך ליטול ידיו! ודוחים: אף מכאן אין להביא ראיה, שכן \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד דינו\u0005]\u0006 של ה\u0003שמש, דטריד\u0004 \u0005[ש\u0006הוא \u0005טרוד]\u0006 ונוגע בדברים שונים בלי לשים לב, ולכך אין לו לאכול בלא נטילת ידים.","ועוד בענין נתינת אוכל לשמש המשרת בשעת הסעודה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יתן אדם\u0004 המתארח \u0003פרוסה\u0004 מן הסעודה שלפניו \u0003לשמש\u0004 המשרת את הסועדים, \u0003בין\u0004 בזמן \u0003שהכוס\u0004 נמצאת \u0003בידו\u0004 של השמש, \u0003בין\u0004 בזמן \u0003שהכוס בידו של בעל הבית.\u0004 וטעם הדבר: \u0003שמא\u0004 מתוך כך \u0003יארע דבר קלקלה בסעודה,\u0004 שמא בעל הבית יכעס, וכיון שהוא שותה עתה, עלול היין להזיק לו. או שיטרד בעל הבית משום שיחשוש שלא יספיק האוכל לאורחיו, ומתוך שהוא מתבונן הנה והנה, עלולה הכוס להישמט מידו. וכן הוא בכוס הנמצאת ביד השמש, שמתוך שהוא מקבל מאת האורחים עלול הוא לשפוך את היין שבכוסו. \u0003והשמש שלא נטל ידיו\u0004 — \u0003אסור ליתן פרוסה לתוך פיו.\u0004","למעלה הובאה בעייתם של חכמים בדינו של האוכל מחמת מאכיל לענין נטילת ידים, ועתה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 מה דינו של ה\u0003מאכיל\u0004 את האחר, האם הוא \u0003צריך נטילת ידים,\u0004 שהרי הוא מכניס בידו לתוך פיו של חבירו, \u0003או\u0004 שמא \u0003אינו צריך,\u0004 שהרי הוא אינו אוכל?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה \u0003דתני דבי\u0004 \u0005[ששנה\u0006 בבריייתא החכם \u0005של בית]\u0006 מדרשו של \u0003מנשה: רבן שמעון בן גמליאל אומר\u0004 כי ה\u0003אשה\u0004 המאכילה את ילדה התינוק ביום הכיפורים, הריהי \u0003מדיחה\u0004 (שוטפת) \u0003את ידה\u0004 ה\u0003אחת במים,\u0004 אף שיום הכיפורים אסור ברחיצה, \u0003ונותנת פת לבנה\u0004 ה\u0003קטן. אמרו עליו על שמאי הזקן שלא רצה להאכיל\u0004 ביום הכיפורים את התינוק אפילו בהדחה \u0003בידו אחת,\u0004 שלא רצה להדיח אפילו את ידו האחת ונמנע בשל כך מלהאכיל את התינוק, \u0003וגזרו עליו\u0004 חכמים \u0003שיאכיל בשתי ידיו.\u0004 ומכאן ראיה שהמאכיל, אף שהוא עצמו אינו אוכל, הריהו צריך ליטול ידיו.","\u0003אמר אביי:\u0004 אין זו ראיה, שכן סיבתה של הדחת הידים \u0003התם\u0004 \u0005[שם]\u0006 אינה משום מצות נטילת ידים, אלא \u0003משום שיבתא\u0004 \u0005[רוח רעה]\u0006 השורה על ידי אדם שלא נטל ידיו בבוקר, ומגע יד שכזו עלול להזיק, ולכך הצריכו חכמים למאכיל את התינוק ליטול ידיו בבוקר, ואף ביום הכיפורים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה שמסופר \u0003דאבוה\u0004 \u0005[שאביו]\u0006 של \u0003שמואל אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003שמואל דקא בכי\u0004 \u0005[שהוא בוכה]\u0006 כשהיה עדיין ילד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו של שמואל: \u0003אמאי קא בכית\u0004 \u0005[מדוע אתה בוכה]?\u0006 אמר לו שמואל: \u0003דמחיין רבאי\u0004 \u0005[שהיכה אותי רבי,\u0006 מורי\u0005],\u0006 שאל אותו האב: \u0003אמאי\u0004 \u0005[מדוע]\u0006 היכה אותך? השיב שמואל: מפני ש\u0003אמר לי\u0004 רבי, \u0003קא ספית לבראי ולא משית ידיה\u0004 \u0005[אתה מאכיל את בני, ולא נטלת את ידיך].\u0006 שאל אותו אביו: \u0003ואמאי לא משית\u0004 \u0005[ומדוע לא נטלת ידיך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל בתמיהה: \u0003הוא,\u0004 בנו של רבי, \u0003אכיל, ואנא משינא\u0004 \u0005[אוכל, ואני אטול\u0006 ידי\u0005]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו של שמואל לבנו: \u0003לא מיסתייה דלא גמיר\u0004 \u0005[לא די לו\u0006 לרבך, \u0005שלא למד]\u0006 כראוי, שהרי המאכיל את חבירו אינו צריך ליטול את ידיו, \u0003מימחא נמי מחי\u0004 \u0005[גם כן מכה\u0006 הוא\u0005]!\u0006 \u0003ו\u0004מסכמים, \u0003הלכתא\u0004 \u0005[הלכה]\u0006 היא: מי ש\u0003אוכל מחמת מאכיל\u0004 אף על פי שאינו נוגע — הריהו \u0003צריך נטילת ידים,\u0004 ואולם ה\u0003מאכיל\u0004 את חבירו — \u0003אינו צריך נטילת ידים.\u0004","\u0003צורר\u0004 (מניח באריזה אחת) \u0003אדם בשר וגבינה במטפחת אחת, ובלבד שלא יהו נוגעין זה בזה. רבן שמעון בן גמליאל אומר: שני אכסנאין\u0004 (אורחים באכסניה אחת) הזרים זה לזה, \u0003אוכלין על שלחן אחד, זה בשר וזה גבינה, ואין חוששין\u0004 שמא יבוא האחד לאכול ממאכלו של חבירו, וייכשל באיסור בשר בחלב.","שנינו במשנה שאמנם מותר לארוז יחד בשר וגבינה, ואולם מותנה הדבר שלא יגעו זה בזה, ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נוגע זה בזה\u0004 הבשר והגבינה, \u0003מאי הוי\u0004 \u0005[מה נהיה]\u0006 בכך? והלא \u0003צונן בצונן הוא,\u0004 ואין האחד בולע מחבירו במגע. \u0003אמר אביי\u0004 בהסבר הדבר: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 שבמגע של צונן בצונן \u0003קליפה\u0004 של מקום המגע \u0003לא בעי\u0004 \u0005[אינו צריך],\u0006 שכן לא בלע האחד מחבירו, ואולם \u0003הדחה\u0004 (שטיפה) \u0003מי לא בעי\u0004 \u0005[האם אינו צריך]?!\u0006 ולכך אסרו חכמים על מגע בשר וגבינה, מפני החשש שיבוא לאוכלם בלא הדחה.","עוד שנינו במשנתנו כי \u0003רבן שמעון בן גמליאל אומר\u0004 ש\u0003שני אכסנאין אוכלין על שולחן\u0004 אחד. ובענין זה \u0003אמר רב חנן בר אמי, אמר שמואל: לא שנו\u0004 הלכה זו \u0003אלא\u0004 בזמן \u0003שאין\u0004 האכסנאים הללו \u0003מכירין זה את זה\u0004 שאז אינם באים לאכול האחד ממאכל חבירו, \u0003אבל\u0004 בזמן שהם \u0003מכירין זה את זה\u0004 — \u0003אסור,\u0004 שיש לחשוש שיבואו לאכול זה ממאכליו של זה.","ומביאים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא האומרת \u0005גם כן כך],\u0006 \u0003רבן שמעון בן גמליאל אומר: שני אכסנאים שנתארחו לפונדק אחד, זה בא מן הצפון וזה בא מן הדרום, זה בא בחתיכתו\u0004 של בשר, \u0003וזה בא בגבינתו\u0004 — הריהם \u0003אוכלין על שלחן אחד, זה בשר וזה גבינה, ואין חוששין\u0004 שיבוא האחד לאכול ממאכלו של חבירו.","\u0003ולא אסרו\u0004 חכמים לנהוג כן \u0003אלא\u0004 בזמן ששניהם \u0003בתפיסה\u0004 (בכריכה, בחפיסה) \u0003אחת,\u0004 שהרי זו סעודה משותפת. ותוהים: \u0003תפיסה אחת סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 להשמיענו שאסור, הרי פשוט הוא! \u0003אלא\u0004 בא להשמיענו שאסורה אכילה שכזו, אף ב\u0003כעין תפיסה אחת,\u0004 אם יש בין האוכלים מידה של היכרות, שאין האחד מקפיד על השני אם יאכל \u0003ממאכלו שלו. ולכך אסורה אכילת שניהם על שולחן אחד.\u0004","למעלה הובא כי אם מכירים הסועדים זה את זה, אסור להם לאכול על שולחן אחד, זה בשר וזה גבינה. ומביאים עוד בענין זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר בר שלמיא לאביי\u0004 בשאלה: אם היו סועדים אלה \u0003שני אחין, ו\u0004אולם הם \u0003מקפידין זה על זה,\u0004 ואינם אוכלים זה מזה, \u0003מהו\u0004 הדין, האם מותר להם לאכול בשר וגבינה יחד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בפתגם שנאמר במקום אחר: אילו נתיר לאלו, \u0003יאמרו כל הסריקין אסורין, וסריקי בייתוס מותרין?!\u0004 שכן אסרו חכמים לעשות בפסח מצות סרוקות (משורטטות), שמפני משך הזמן הנדרש לכך, עלולות המצות להחמיץ. ושאל בייתוס בן זונין את חכמים שהרי אפשר לעשות כן בתבנית קבועה, ואין פעולה זו נמשכת זמן רב. ואמרו לו חכמים שאם נתיר באופן זה, יבואו אנשים לתהות מדוע כל הסריקים אסורים, ודווקא של בייתוס מותרים. וכיוצא בזה לענייננו, שאף שני אחים המקפידים זה על זה, אסורים לאכול על שולחן אחד בשר וגבינה. שלא חילקו חכמים בגזירותיהם.","אמר לו רב יימר לאביי: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה אומר שאסור הדבר אף באופן זה, מעתה הלכה \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אסי, אמר ר' יוחנן:\u0004 אף שאסרו חכמים לכבס בחול המועד, מכל מקום \u0003מי שאין לו אלא חלוק אחד\u0004 בלבד הריהו \u0003מותר לכבסו בחולו של מועד.\u0004 ואף בענין זה \u0003יאמרו:\u0004"],["\u0003כל הסריקין אסורין וסריקי בייתוס מותרין!\u0004 השיב אביי לרב יימר בר שלמיא: אין להקשות מהיתר כיבוס בחול המועד למי שיש לו רק חלוק אחד, שכן \u0003התם הא\u0004 \u0005[שם הרי]\u0006 כבר \u0003אמר מר בר רב אשי\u0004 בטעם היתר זה, שהוא משום ש\u0003איזורו\u0004 (חגורתו) \u0003מוכיח עליו\u0004 שהרי זה חלוקו היחיד. שכן האיזור משמש את כל החלוקים שיש לאדם. ואדם שיש לו שני חלוקים ויותר הרי כאשר הוא מסיר חלוק אחד ולובש תחתיו אחר, הריהו נוטל את האיזור מהראשון ומעבירו לזה שהוא לובש עתה. ואת הראשון הריהו מכבס בלא איזור. ולכן כאשר מכבס אדם את חלוקו עם האיזור שעליו — הרי זה מוכיח לכל הרואים, שאין לו אלא חלוק אחד. ולכך לא הוסר האיזור לפני הכביסה, מפני שלא היה טעם להסירו, שהרי אין לו חלוק אחר לאזור בו את איזורו\u0003. ויודעים כל הרואים מדוע התירו לו חכמים לכבס בחול המועד.\u0004","\u0003טיפת חלב שנפלה על החתיכה\u0004 של בשר המתבשלת בתוך קדירה רותחת, ונבלעה איפוא בחתיכת הבשר. ולא בחש בקדירה, ולא התפשט החלב אל מעבר לחתיכת הבשר הזו. \u0003אם יש בה ב\u0004טיפת החלב הזו שיעור שיהא \u0003נותן טעם באותה חתיכה\u0004 של בשר, שאין בחתיכת הבשר פי ששים כנגד טיפת החלב שנפלה לתוכה — אותו הבשר \u0003אסור.\u0004 ואם מיד לאחר נפילת טיפת החלב \u0003ניער\u0004 (בחש) \u0003את הקדרה,\u0004 ונכנסה אותה חתיכה בתוך הרוטב שבקדירה עוד לפני שבלעה את החלב וקיבלה טעם ממנו, נמצא איפוא שהתערבה טיפת החלב בכל הנמצא בקדירה. לכך \u0003אם יש בה ב\u0004טיפת החלב הזו שיעור שיהא \u0003נותן טעם באותה קדרה\u0004 —","\u0003אסור\u0004 כל הנמצא בקדירה. שנינו במשנתנו שטיפת חלב הנבלעת בחתיכת בשר, אם היא נותנת טעם בחתיכת הבשר, נאסר הבשר בכך. ובענין זה שטעם איסור אוסר את הבולעו \u0003אמר אביי:\u0004 הלכה זו שדי ב\u0003טעמו\u0004 של דבר איסור שנבלע בדבר היתר לאוסרו בכך, \u0003ולא\u0004 דווקא \u0003ממשו בעלמא\u0004 \u0005[בסתם,\u0006 בכל האיסורים, ולא בבשר בחלב בלבד\u0005]\u0006 — הריהי \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 ולא מדברי חכמים. שמהלכה זו בבשר בחלב (כמבואר במשנתנו), נלמדת ההלכה בשאר איסורים.","וההוכחה לכך: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שאין זה אלא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 מעתה יש לדון: \u0003מבשר בחלב מאי טעמא לא גמרינן\u0004 \u0005[מה טעם אין אנו לומדים]\u0006 שטעם איסור הנבלע בדבר אחר הריהו אוסרו בכך? — משום שכל עיקרו של איסור \u0003בשר בחלב\u0004 \u0003חדוש הוא,\u0004 שהרי כל אחד לעצמו הינו דבר היתר, ורק משעה שהתבשלו יחד הריהם נאסרים כאחד. ואולם \u0003אי\u0004 \u0005[אם]\u0006 אכן איסור בשר בחלב \u0003חדוש הוא\u0004 — מעתה נאמר כי \u0003אף על גב דליכא\u0004 \u0005[אף על פי שאין בו]\u0006 \u0003נותן טעם נמי\u0004 \u0005[גם כן]\u0006 יהיה אסור! ומאחר ואין אנו אומרים כן, הרי זו ראיה שאין בשר בחלב דבר חידוש, ונלמד ממנו לשאר איסורים, שהטעם אוסר מן התורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: אין זו ראיה, שכן בשר בחלב חידוש הוא. ואולם אין התורה אוסרתו כל זמן שלא נתן החלב טעם בבשר, כי \u0003דרך בשול אסרה תורה,\u0004 ודרך בישול קשורה לנתינת טעם.","שנינו במשנתנו שאם אין בחתיכת הבשר כדי ששים לבטל את טיפת החלב שנפלה עליה, הריהי אסורה. ובעניינה של חתיכה זו \u0003אמר רב: כיון ש\u0004החלב \u0003נתן טעם בחתיכה\u0004 של הבשר — ה\u0003חתיכה עצמה נעשית נבלה,\u0004 כלומר, איסור לעצמו, ואם לא הוציאה מיד מן הקדירה, הריהי חוזרת \u0003ואוסרת\u0004 את \u0003כל החתיכות כולן\u0004 שבקדירה. ואף אם יש בכל החתיכות שבקדירה פי ששים כנגד חתיכה זו, הריהן אסורות, \u0003מפני שהן\u0004 מין ב\u0003מינה\u0004 של החתיכה, ומין במינו אינו בטל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: מכדי\u0004 \u0005[הרי]\u0006 \u0003רב כמאן\u0004 \u0005[כ\u0006שיטתו של \u0005מי]\u0006 \u0003אמר לשמעתיה\u0004 \u0005[את הלכתו\u0006 זו\u0005]?\u0006 — \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 כי \u0003מין במינו לא בטיל\u0004 \u0005[אינו בטל],\u0006 מעתה \u0003לימא פליגא\u0004 \u0005[האם נאמר\u0006 שרב \u0005חולק]\u0006 על \u0003רבא\u0004 בהסבר שיטת ר' יהודה.","שכן \u0003אמר רבא: קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יהודה\u0004 כי \u0003כל\u0004 תערובת איסור והיתר \u0003שהוא\u0004 של \u0003מין ומינו ו\u0004יש עוד \u0003דבר אחר\u0004 של היתר — אומרים אנו: \u0003סלק את מינו כמי שאינו\u0004 בתערובת זו, \u0003ו\u0004אם ההיתר \u0003שאינו מינו רבה עליו,\u0004 על האיסור, הריהו \u0003מבטלו.\u0004 ואף בקדירה זו שלפנינו, אף ששאר החתיכות הן ממינה של חתיכת הבשר שנפלה עליה טיפת החלב, ואולם יש בקדירה זו רוטב, שאינו ממינה של חתיכת הבשר, ויבטל הוא את חתיכת הבשר האסורה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא למר זוטרא בנו של רב מרי: \u0003אי\u0004 \u0005[אם]\u0006 אכן \u0003נפל\u0004 האיסור \u0003ברוטב רכה,\u0004 שאינה ממין הבשר — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהיה הדין, שהרוטב מבטל את טיפת החלב, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 ש\u0003נפל ברוטב עבה,\u0004 המורכב ממשקעי בשר, והריהו ממין הבשר, ולכך אין הוא מבטל משום שהוא מין במינו.","ודנים עוד בבירור שיטת רב שחתיכת הבשר שנפל עליה חלב נעשית חתיכת איסור לעצמה: \u0003ומאי קסבר\u0004 \u0005[ומה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 שדבר ש\u0003אפשר לסוחטו\u0004 ולהוציא את האיסור ממנו — הריהו \u0003מותר,\u0004 אף \u0003חתיכה\u0004 זו \u0003אמאי\u0004 \u0005[מדוע]\u0006 היא \u0003נעשית נבלה,\u0004 והרי אפשר לה לטיפת החלב שבתוכה שתיסחט ותצא מחתיכה זו אל שאר החתיכות, ומאחר ואינה מין במינו עם שאר חתיכות הבשר, הריהי מתבטלת בתוכן! \u0003אלא קסבר\u0004 \u0005[סבור הוא]\u0006 שדבר ש\u0003אפשר לסוחטו אסור.\u0004","\u0003דאיתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שנחלקו אמוראים בדבר זה, ש\u0003רב ור' חנינא ור' יוחנן דאמרי\u0004 \u0005[שאומרים]\u0006 שאפילו דבר ש\u0003אפשר לסוחטו\u0004 הריהו \u0003אסור,\u0004 ואילו \u0003שמואל ור' שמעון בר רבי וריש לקיש דאמרי\u0004 \u0005[שאומרים]\u0006 כי דבר ש\u0003אפשר לסוחטו\u0004 \u0003מותר.\u0004","ושואלים על הסבר זה: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003רב\u0004 ש\u0003אפשר לסוחטו\u0004 \u0003אסור? והאיתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו חכמים בדינו של \u0003כזית בשר שנפל לתוך יורה\u0004 (סיר) \u0003של חלב\u0004 (שאין שיעור זה של בשר נותן טעם בחלב שביורה), ש\u0003אמר רב\u0004 כי ה\u0003בשר אסור,\u0004 שהרי בלע מן החלב שנתן בו טעמו, \u0003ו\u0004אילו ה\u0003חלב מותר,\u0004 מפני שהבשר לא נתן בו טעם. \u0003ו\u0004אולם \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שלדעת רב \u0003אפשר לסוחטו\u0004 — \u0003אסור,\u0004"],["ה\u0003חלב אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותר?\u0004 והלא מאחר שבלע הבשר מן החלב, חלב זה שבתוכו \u0003חלב נבלה הוא,\u0004 ולכשיחזור ויפלט אל שאר החלב שביורה, הריהו אוסר את כל החלב, משום מין במינו, ושיטת רב היא כדעת ר' יהודה שאין מין במינו בטל!","ודוחים: \u0003לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רב\u0004 כי אכן דבר ש\u0003אפשר לסוחטו אסור, ו\u0004טעם הדבר שאין החלב שנכנס בבשר חוזר ואוסר את שאר החלב, כי \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הוא \u0005שם]\u0006 דין בשר בחלב, \u0003ש\u0004\u0003אמר\u0004 בו \u0003קרא\u0004 \u0005[הפסוק]:\u0006 \u0003\"לא תבשל גדי בחלב אמו\"\u0004 (שמות כג, יט) — דווקא \u0003גדי\u0004 (ושאר בשר מן הבהמה) שהתבשל עם החלב הוא ש\u0003אסרה תורה, ולא חלב\u0004 שהתבשל עם הבשר.","ותוהים: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003רב\u0004 כי דווקא \u0003גדי\u0004 שהתבשל בחלב הוא ש\u0003אסרה תורה ולא חלב\u0004 שהתבשל בבשר? \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 בדינו של \u0003חצי זית בשר וחצי זית חלב שבשלן זה עם זה,\u0004 ש\u0003אמר רב\u0004 שכל האוכל שני חצאי כזית אלה הריהו \u0003לוקה על אכילתו,\u0004 שכן יש כאן כזית של איסור. \u0003ו\u0004אולם הוא \u0003אינו לוקה על בשולו\u0004 של חצי זית מזה וחצי זית מזה, ומפני שלא בישל דבר שיש בו שיעור. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שלשיטת רב \u0003גדי אסרה תורה, ולא חלב,\u0004 אף על ה\u0003אכילה\u0004 של חצי זית הבשר וחצי זית החלב הללו \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003לוקה?\u0004 והלא רק \u0003חצי שיעור\u0004 של איסור \u0003הוא\u0004 זה, שאין כאן כזית בשר, אלא חצי זית בלבד!","\u0003אלא\u0004 כך יש לומר בהסבר שיטת רב: \u0003לעולם\u0004 יש לומר ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רב\u0004 כי לא רק הבשר שהתבשל עם חלב אסור, אלא אף ה\u0003חלב\u0004 שהתבשל עם בשר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור, ו\u0004טעם הדבר שהתיר רב את החלב כשנפל כזית בשר לתוך יורה של חלב: שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שנפל\u0004 כזית הבשר \u0003לתוך יורה רותחת,\u0004 שבמקרה שכזה \u0003מבלע בלע\u0004 \u0005[לבלוע\u0006 הרי כזית הבשר אמנם \u0005בולע\u0006 מן החלב\u0005],\u0006 ונאסר בכך. ואולם \u0003מפלט לא פלט\u0004 \u0005[לפלוט\u0006 את החלב שבתוכו, \u0005אינו פולט],\u0006 ולכך אין החלב נאסר.","ושואלים על הסבר זה: \u0003סוף סוף כי נייח, הדר פליט\u0004 \u0005[כאשר נחה\u0006 היורה \u0005מרתיחתה,\u0006 \u0005חוזר\u0006 הבשר \u0005ופולט\u0006 את החלב האסור שבתוכו\u0005]!\u0006 ומשיבים: מדובר כאן \u0003כשקדם וסילקו\u0004 את כזית הבשר, לפני שהיורה נחה מרתיחתה.","למעלה הובאה הלכה משמו של רב בדינם של חצי כזית בשר וחצי כזית חלב שבישלם יחד, ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לעצמה]:\u0006 \u0003חצי זית בשר וחצי זית חלב שבשלן זה עם זה, אמר רב:\u0004 האוכל שני חצאי זית אלה \u0003לוקה על אכילתו,\u0004 שהרי אכל כזית שלם של איסור, \u0003ו\u0004אולם \u0003אינו לוקה על בשולו,\u0004 שכן לא בישל כשיעור בשר וכשיעור חלב. ותוהים: \u0003מה נפשך,\u0004 באיזה צד אתה רוצה לומר? \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר ששני חצאי זית אלה \u0003מצטרפין\u0004 זה לזה לענין אכילה — לענין \u0003בשול נמי\u0004 \u0005[גם כן]\u0006 יצטרפו \u0003ו\u0004\u0003לילקי\u0004 \u0005[ילקה]\u0006 אף על הבישול! ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מצטרפין\u0004 לענין הבישול — לענין ה\u0003אכילה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצטרפו, \u0003ולא\u0004 \u0003לילקי\u0004 \u0005[ילקה]\u0006 על האכילה!","ומשיבים: \u0003לעולם\u0004 אכן חצי זית בשר וחצי זית חלב \u0003לא מצטרפי\u0004 \u0005[אינם מצטרפים]\u0006 לא לענין בישול ולא לענין אכילה, \u0003ו\u0004אולם כאן מדובר \u0003ב\u0004חצי זית בשר וחצי זית חלב ש\u0003בא\u0004 כל אחד מהם \u0003מיורה גדולה\u0004 שבה התבשלו חתיכת בשר בשיעור גדול וחתיכת גבינה בשיעור גדול, ועמד וחתך מזה כחצי זית ומזה כחצי זית ואכלם כאחד, שהרי זה נחשב לו לאכילת איסור של כזית שלם.","\u0003ו\u0004אילו \u0003לוי\u0004 חלק על רב בדבר זה, ו\u0003אמר\u0004 כי חצי זית בשר וחצי זית חלב כשם שהם מצטרפים לענין אכילה ללקות עליהם, \u0003אף\u0004 מצטרפים לענין בישול, והריהו \u0003לוקה על בשולו\u0004 של זה. \u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתין\u0004 \u0005[בברייתות\u0006 שלו\u0005]:\u0006 \u0003כשם שלוקה על אכילתו, כך לוקה על בשולו. ובאי זה\u0004 דרגת \u0003בשול אמרו\u0004 שלוקים עליו כמי שעבר על איסור בישול בשר בחלב? \u0003בבשול\u0004 כזה \u0003שאחרים\u0004 (גויים) \u0003אוכלין אותו מחמת בשולו,\u0004 שנעשה ראוי לאכילה מחמת הבישול.","למעלה נדון ענין \"אפשר לסוחטו\", \u0003ו\u0004מביאים עוד בענין זה. \u0003אפשר לסוחטו עצמו,\u0004 אם מותר או אסור — מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003טפת חלב שנפלה על החתיכה\u0004 של בשר רותח, \u0003כיון שנתנה\u0004 הטיפה \u0003טעם בחתיכה\u0004 — הרי \u0003החתיכה עצמה נעשת נבלה, ו\u0004הריהי \u0003אוסרת\u0004 את \u0003כל החתיכות כולן\u0004 שהתבשלו עימה בקדירה, ואף שיש בכל החתיכות פי ששים כנגד חתיכה זו, \u0003מפני שהן מינה,\u0004 ואין מין במינו מתבטל. אלו \u0003דברי ר' יהודה. ו\u0004","אילו \u0003חכמים אומרים\u0004 שאין החתיכה שנפלה עליה טיפת החלב נאסרת אלא \u0003עד שתתן\u0004 טיפת החלב \u0003טעם\u0004 אף \u0003ברוטב ובקיפה וב\u0004שאר ה\u0003חתיכות\u0004 שבקדירה. ואולם אם אינה נותנת טעם בהם, אינה אוסרת אף לא את החתיכה שנפלה עליה, שכן נסחט ממנה טעם החלב והתפשט בכל הקדירה.","ובהכרעת הדין במחלוקתם זו \u0003אמר רבי: נראין דברי ר' יהודה ב\u0004אופן \u0003שלא ניער\u0004 את הקדירה \u0003ושלא כסה\u0004 אותה, \u0003ו\u0004אילו \u0003דברי חכמים\u0004 נראים \u0003ב\u0004אופן \u0003שניער\u0004 את הקדירה \u0003וכסה\u0004 אותה.","ומעתה יש לברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא ניער ולא כסה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ש\u0003לא ניער כלל, ולא כסה כלל\u0004 — הלא במקרה כזה החתיכה שעליה נפלה טיפת החלב \u0003מבלע בלע\u0004 \u0005[לבלוע\u0006 אמנם \u0005בולעת],\u0006 ואולם \u0003מפלט לא פלט\u0004 \u0005[לפלוט אינה פולטת],\u0006 ואין איפוא מקום לאסור (כשיטת ר' יהודה) את שאר החתיכות.","\u0003ואלא\u0004 צריך לומר בכוונת דברי רבי ש\u0003לא ניער בתחלה\u0004 לפני שהחתיכה הראשונה בלעה מטיפת החלב שנפלה עליה, \u0003אלא בסוף,\u0004 לאחר שבלעה, \u0003ו\u0004כיוצא בזה, \u0003לא כסה בתחלה אלא בסוף\u0004 — אם כן, \u0003אמאי\u0004 \u0005[מדוע]\u0006 נאסרות כל החתיכות שבקדירה (לשיטת ר' יהודה), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בלע\u0004 החתיכה הראשונה מן החלב, \u0003והא\u0004 \u0005[והרי]\u0006 שב ו\u0003פלט!\u0004","הרי מכאן נסיק כי \u0003קסבר\u0004 \u0005[סבור הוא\u0006 רבי\u0005]\u0006 שכל ש\u0003אפשר לסוחטו\u0004 — \u0003אסור,\u0004 ומאחר שנאסרה החתיכה הראשונה, הרי היא עצמה איסור, וכל הנסחט ממנה הריהו אסור. ולכך כל שאר החתיכות אסורות, שהרי טעם הבשר האסור הנסחט מהחתיכה הראשונה נבלע בחתיכות האחרות, והרי זו תערובת מין במינו, שאין האיסור בטל בה."],["ושואלים: \u0003מכלל\u0004 דברי רבי שנראים לו דברי ר' יהודה (האוסר את כל החתיכות שבקדירה) רק כאשר לא ניער בתחילה (ונאסרה החתיכה הראשונה) וניער וכיסה בסוף, יש להסיק כי \u0003ר' יהודה\u0004 עצמו \u0003סבר\u0004 \u0005[סבור]\u0006 שאף \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003ניער מתחלה ועד סוף וכסה מתחלה ועד סוף\u0004 — גם כן \u0003אסור\u0004 כל מה שבקדירה, ועל כך יש להקשות, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא כן, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא בלע\u0004 בשר החתיכה הראשונה \u0003כלל\u0004 יותר משאר \u0003החתיכות שבקדירה? שכיון שבחש מייד עם נפילת החלב על החתיכה הראשונה, החלב נבלע בכל החתיכות שבקדירה בשווה, והריהו מתבטל בהן (אם יש בהן ששים כנגדו)?\u0004","ומשיבים: טעם ר' יהודה הוא, שכן \u0003אימא\u0004 \u0005[אמור,\u0006 יש מקום לחשוש ולומר\u0005]\u0006 שבתחילה \u0003לא ניער יפה יפה, ולא כסה יפה יפה,\u0004 ויתכן שבאותה עת החלב לא נבלע בשאר החתיכות אלא רק בחתיכה הראשונה. ולאחר מכן כשהמשיך לנער יפה יפה, אז חוזרת חתיכה זו ואוסרת את כל החתיכות, שכן סבור ר' יהודה שאפשר \u0003לסוחטו אסור. ואף רבי סבור כן, ואולם אין הוא סבור כר' יהודה לענין חשש זה כאשר ניער וכיסה מתחילה ועד סוף.\u0004","וממשיכים בביאור דברי רבי בהכרעת מחלוקת ר' יהודה וחכמים. \u0003אמר מר\u0004 \u0005[החכם,\u0006 רבי\u0005]\u0006 כי נראים דברי ר' יהודה באופן שלא ניער ושלא כיסה, \u0003ו\u0004נראים \u0003דברי חכמים כשניער וכסה.\u0004 ודנים בדבריו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ניער\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"כסה\"\u0004 שאמר רבי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ש\u0003ניער בסוף\u0004 לאחר שכבר בלעה החתיכה הראשונה מן החלב ונאסרה, \u0003ולא ניער בתחלה\u0004 מיד עם נפילת החלב על חתיכת הבשר. \u0003ו\u0004כיוצא בזה ש\u0003כסה בסוף\u0004 לאחר שכבר נאסרה החתיכה הראשונה, \u0003ולא כסה בתחלה\u0004 — \u0003האמרת\u0004 \u0005[הרי אמרת]\u0006 כבר ש\u0003נראין דברי ר' יהודה בהא\u0004 \u0005[ב\u0006אופן \u0005זה]?\u0006 \u0003אלא\u0004 צריך לומר שכך היא כוונת רבי: \u0003\"ניער\"\u0004 — \u0003מתחלה ועד סוף, ו\"כסה\"\u0004 — \u0003מתחלה ועד סוף.\u0004","שאז נראית שיטת חכמים המתירים את הנמצא בקדירה, ואולם \u0003מכלל\u0004 הדברים יש להסיק \u0003דרבנן סברי\u0004 \u0005[שחכמים\u0006 עצמם \u0005סבורים]\u0006 שלא רק באופן זה כל הקדירה מותרת, אלא גם כאשר \u0003ניער\u0004 רק \u0003בסוף ולא ניער בתחלה,\u0004 וכן כאשר \u0003כסה\u0004 רק \u0003בסוף ולא כסה בתחלה\u0004 — כל הנמצא בקדירה \u0003מותר.\u0004 ואף החתיכה הראשונה, אף שנאסרה בתחילה כאשר בלעה מן החלב, הריהי חוזרת ומותרת, שאנו אומרים שנסחט ממנה החלב שהיה בה, והתפשט לכל הקדירה.","\u0003אלמא קסברי\u0004 \u0005[מכאן\u0006 ש\u0005הם סבורים]\u0006 שדבר] ש\u0003אפשר לסוחטו\u0004 — הריהו \u0003מותר.\u0004 הרי שיש מחלוקת תנאים בנושא של אפשר לסוחטו, שלדעת ר' יהודה (וכן היא דעת רבי) אפשר לסוחטו — אסור, ואילו לדעת חכמים אפשר לסוחטו — מותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא\u0004 בדחיית הדברים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה יודע ש\u0003באפשר לסוחטו פליגי\u0004 \u0005[חלוקים]\u0006 ר' יהודה וחכמים? \u0003דלמא\u0004 \u0005[שמא]\u0006 נאמר כך: \u0003אפשר לסוחטו\u0004 — ל\u0003דברי הכל\u0004 (ואף לדברי חכמים) הריהו \u0003אסור, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה של \u0003מין במינו קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003ור' יהודה\u0004 הולך במחלוקת זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 כי כל תערובת איסור בהיתר של \u0003מין במינו לא בטיל\u0004 \u0005[אין\u0006 האיסור \u0005בטל],\u0006 \u0003ו\u0004אף \u0003רבנן\u0004 \u0005[חכמים]\u0006 הולכים \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 כי תערובת איסור בהיתר של \u0003מין במינו בטיל\u0004 \u0005[בטל]\u0006 האיסור. ולכך במקרה שלפנינו, שהוא תערובת מין במינו (חתיכת הבשר הראשונה שנאסרה בין שאר הנמצא בקדירה) ר' יהודה אוסר וחכמים מתירים! דחה רבינא:","\u0003האי מאי\u0004 \u0005[זה\u0006 ההסבר \u0005מה\u0006 טיבו\u0005]?\u0006 אין זה נראה, שכן \u0003אי אמרת בשלמא דרבנן\u0004 \u0005[נניח אם אתה אומר שחכמים]\u0006 \u0003במין במינו הכא\u0004 \u0005[כאן,\u0006 במקרה זה\u0005]\u0006 \u0003כר' יהודה סבירא להו\u0004 \u0005[סבורים הם]\u0006 \u0003ובאפשר לסוחטו פליגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 וכדרך שהוסבר למעלה — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003רבי: נראין דברי ר' יהודה בהא\u0004 \u0005[ב\u0006אופן \u0005זה]\u0006 בשלא ניער וכיסה בתחילה אלא בסוף, \u0003ו\u0004נראים \u0003דברי חכמים בהא\u0004 \u0005[ב\u0006אופן \u0005זה],\u0006 כשניער וכיסה מתחילה ועד סוף, וכפי שהתפרש.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כהצעתך זו, שב\u0003אפשר לסוחטו\u0004 ל\u0003דברי הכל אסור,\u0004 \u0003והכא\u0004 \u0005[וכאן]\u0006 אין ר' יהודה וחכמים חלוקים בדין החתיכה הראשונה, שלדעת הכל היא נאסרת, ונחלקו רק האם היא אוסרת את שאר החתיכות, שכן \u0003במין במינו קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 מעתה \u0003האי\u0004 \u0005[זה]\u0006 שאמר רבי שנראים דברי חכמים בשניער תחלה, ואין נראים באופן זה דברי ר' יהודה. והרי אף חכמים סבורים כר' יהודה שמא לא ניער יפה יפה, ולכך נאסרה החתיכה הראשונה, ואולם הם סבורים כי הניעור בסוף אינו אוסר את הנמצא בקדירה (שהרי זו תערובת מין במינו), ואולם החתיכה הראשונה עומדת באיסורה (שכן לדעתם, אפשר לסוחטו הריהו אסור). מעתה היה לרבי לומר \u0003נראין דברי ר' יהודה\u0004 שכל החתיכות נאסרות, כאשר ניער רק בסוף, ומטעם שמין במינו אינו בטל, \u0003ואין נראין\u0004 דברי ר' יהודה שבניעור מתחילה יש לחשוש שמא לא ניער יפה יפה, ולכך יש לאסור את הכל הוא ש\u0003מבעי ליה\u0004 \u0005[צריך היה\u0006 לרבי לומר\u0005],\u0006 \u0003ותו לא מידי\u0004 \u0005[ושוב אין דבר]\u0006 נוסף שיש לומר. ונדחתה בכך הצעתו של רב אחא מדיפתי.","הרוצה לאכול את \u0003הכחל\u0004 (עטין) של בהמה שנשחטה, המלא חלב — הריהו \u0003קורעו\u0004 לפני בישולו, \u0003ומוציא את חלבו\u0004 מתוכו, ואחר כך רשאי הוא לבשלו. ואם עבר ובישלו ב\u0003לא\u0004 ש\u0003קרעו\u0004 לפני כן — \u0003אינו עובר עליו\u0004 בבישולו ובאכילתו משום בשר וחלב, ללקות על כך, שכן אין החלב שבכחל נחשב \"חלב\" האסור בתורה. והוא הדין ברוצה לאכול את \u0003הלב\u0004 המלא בדם — בתחילה \u0003קורעו ומוציא את דמו\u0004 הכנוס בתוכו, ומולחו ומוציא בכך את הדם שבבשרו, ולאחר מכן הריהו מבשלו ואוכלו. ואם מלחו ו\u0003לא קרעו\u0004 — הריהו קורעו לאחר מליחתו, ומוציא את דמו, ומותר באכילה. ואם לא קרעו ואכלו — \u0003אינו עובר עליו\u0004 להתחייב על אכילתו עונש כרת."],["שנינו במשנתנו שיש לקרוע את הכחל לפני בישולו. ואם בישלו בלא שקרעו, אינו עובר עליו. ובביאור דברים אלה \u0003אמר ר' זירא, אמר רב:\u0004 כוונת הלשון \u0003\"אינו עובר עליו\"\u0004 לומר שאין איסור מן התורה בדבר, \u0003ו\u0004אף \u0003מותר\u0004 לכתחילה לאוכלו אם נתבשל בלא קריעה, אפילו מדברי חכמים. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 \u0003\"אינו עובר עליו\",\u0004 משמע \u0003כי\u0004 \u0003מיעבר\u0004 \u0005[לעבור]\u0006 על איסור תורה, שילקה על כך, \u0003הוא\u0004 ש\u0003לא עבר,\u0004 ואולם \u0003הא איסורא איכא\u0004 \u0005[הרי איסור יש]\u0006 באכילה זו!","ומשיבים: \u0003בדין הוא דאיסורא נמי ליכא\u0004 \u0005[שאיסור גם כן אין\u0006 בכך\u0005],\u0006 \u0003ואיידי דבעא למיתנא סיפא\u0004 \u0005[ו\u0006אולם \u0005מתוך שרצה לשנות בסוף\u0006 המשנה\u0005]\u0006 בדינו של \u0003הלב,\u0004 ש\u0003קורעו ומוציא את דמו,\u0004 ואם \u0003לא קרעו\u0004 — \u0003אינו עובר עליו.\u0004 ו\u0003התם\u0004 \u0005[שם]\u0006 בענין הלב, באמת \u0003מיעבר\u0004 \u0005[לעבור]\u0006 על איסור תורה, לענין שילקה על כך, \u0003הוא\u0004 ש\u0003לא עבר,\u0004 אבל \u0003הא איסורא איכא\u0004 \u0005[הרי איסור יש\u0006 בזה\u0005],\u0006 לכך \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן בראש\u0006 המשנה\u0005]\u0006 אותו הלשון \u0003\"אינו עובר עליו\",\u0004 אף שאכן גם איסור אין בדבר.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לומר שאפשר לסייע לו,\u0006 לרב\u0005],\u0006 ממה ששנינו בברייתא: \u0003הכחל\u0004 — \u0003קורעו ומוציא את חלבו, לא קרעו\u0004 — \u0003אינו עובר עליו. הלב\u0004 — \u0003קורעו ומוציא את דמו, לא קרעו\u0004 — \u0003קורעו לאחר בשולו ומותר.\u0004 ונדייק בדברים: דווקא ה\u0003לב הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003קריעה\u0004 לאחר הבישול, אם לא נקרע קודם לכן, \u0003אבל כחל לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003קריעה\u0004 לאחר שבישלו.","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לדייק באופן הפוך: דווקא בלב שנינו כן, משום ש\u0003לב הוא\u0004 זה \u0003דסגי ליה\u0004 \u0005[שדי לו]\u0006 \u0003בקריעה\u0004 לאחר בישול, כדי להתירו לאכילה. \u0003אבל כחל\u0004 — \u0003לא סגי ליה\u0004 \u0005[אין די לו]\u0006 \u0003בקריעה\u0004 לאחר בישול, והוא נאסר. עד כאן הובא נוסח דברים אחד בסוגיה זו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את מהלך הסוגיה באופן שונה, שכך \u0003אמר ר' זירא אמר רב:\u0004 כחל שהתבשל בלא קריעה — \u0003אינו עובר עליו\u0004 מדין תורה משום אכילת בשר בחלב. \u0003ו\u0004אולם \u0003אסור\u0004 לאוכלו מדברי חכמים. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לסייע לו],\u0006 ממה ששנינו: \u0003אינו עובר עליו.\u0004 ונדייק מכאן: \u0003מיעבר\u0004 \u0005[לעבור]\u0006 \u0003הוא\u0004 ש\u0003לא עבר,\u0004 ואולם \u0003הא איסורא איכא\u0004 \u0005[הרי איסור יש\u0006 בזה\u0005].\u0006","ודוחים: \u0003בדין הוא דאיסורא נמי ליכא\u0004 \u0005[שאיסור גם כן אין\u0006 בזה\u0005],\u0006 והיה מקום לשנות במשנתנו \"ומותר\", \u0003ו\u0004אולם \u0003איידי דבעא למיתנא סיפא\u0004 \u0005[מתוך שרצה לשנות\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 בדינו של \u0003הלב,\u0004 ש\u0003קורעו ומוציא את דמו,\u0004 ואם \u0003לא קרעו\u0004 — \u0003אינו עובר עליו.\u0004 שכן \u0003התם\u0004 \u0005[שם,\u0006 בענין הלב\u0005]\u0006 \u0003מיעבר\u0004 \u0005[לעבור]\u0006 \u0003הוא\u0004 ש\u0003לא עבר,\u0004 ואולם \u0003הא איסורא איכא\u0004 \u0005[הרי איסור יש\u0006 בזה\u0005],\u0006 מה שאין כן בכחל, שאין בו איסור. \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005התחלת\u0006 המשנה\u0005]\u0006 לשון זו \u0003\"אינו עובר עליו\".\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לשיטת רב ממה ששנינו בברייתא כי \u0003הכחל\u0004 — \u0003קורעו ומוציא את חלבו, לא קרעו\u0004 — \u0003אינו עובר עליו. הלב\u0004 — \u0003קורעו ומוציא את דמו, לא קרעו\u0004 — \u0003קורעו לאחר בשולו, ומותר.\u0004 ונדייק: דווקא \u0003לב הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003קריעה\u0004 לאחר בישולו, \u0003אבל כחל\u0004 — \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003קריעה!\u0004","ודוחים: אין זו ראיה, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 דווקא \u0003לב הוא\u0004 זה \u0003דסגי ליה\u0004 \u0005[שדי לו]\u0006 \u0003בקריעה\u0004 לאחר בישולו, ומשום שאין הדם נבלע בו בבישול. \u0003אבל כחל\u0004 — \u0003לא סגי ליה\u0004 \u0005[אין די לו]\u0006 \u0003בקריעה,\u0004 שכן נתבשל בשר הכחל בחלב, והריהו נבלע בו, ולכך הוא אסור באכילה.","ומעירים: \u0003תניא כלישנא קמא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה]\u0006 של \u0003רב: כחל שבשלו בחלבו\u0004 — \u0003מותר.\u0004 לעומת זאת, \u0003קבה\u0004 של טלה או של עגל שיש בה חלב, שכן הריהם יונקים חלב אל תוך קיבתם, \u0003שבשלה בחלבה\u0004 בחלב שיש בה — בשר הקיבה \u0003אסור\u0004 באכילה.","\u0003ומה הפרש\u0004 יש \u0003בין זה לזה? זה\u0004 (החלב שבקיבה) הריהו מוגדר כ\"חלב\" משעה שיצא מעטין הבהמה שממנה ינקו הטלה או העגל, והינו \u0003כנוס במעיו\u0004 של הגדי או העגל. ובישולם יחד הריהו בישול בשר בחלב. \u0003ו\u0004אילו \u0003זה\u0004 (החלב \u0003שבכחל) אינו מוגדר כ\u0004\"חלב\" שהרי לא יצא מעטין בהמה, ו\u0003אין\u0004 זה כחלב ה\u0003כנוס במעיו,\u0004 אלא הריהו מובלע בבשר, ולכך אם התבשלו כאחד אין הוא נאסר בכך. אכן מדברי חכמים יש מלכתחילה לקורעו.","שנינו במשנתנו כי יש לקרוע את הכחל קודם בישולו, ומבררים: \u0003כיצד קורעו? אמר רב יהודה: קורעו שתי וערב\u0004 (לאורך ולרוחב) \u0003וטחו\u0004 (דוחקו בכח) \u0003בכותל\u0004 שהוא משטח קשה, ומתוך כך נסחט הכחל ויוצא החלב שבתוכו. ומביאים בענין זה כי \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003קרע לי\u0004 כחל לפני שתצלנו, \u0003ואנא איכול\u0004 \u0005[ואני אוכל\u0006 אותו\u0005].\u0006 ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' אלעזר, \u0005משמיע לנו]\u0006 בכך? והלא הלכה מפורשת ב\u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא\u0004 שכך יש לעשות! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה הוא משמיע לנו]:\u0006 \u0003דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 לצליה שיקרענו \u0003שתי וערב וטחו בכותל,\u0004 כפי שאמר רב יהודה, אלא די בחיתוך אחד, לאורך או לרוחב, ובלא דחיקה על משטח קשה.","ומביאים עוד בענין אכילת כחל, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003ילתא לרב נחמן\u0004 בעלה: \u0003מכדי\u0004 \u0005[הרי]\u0006 כלל נקוט בידינו כי \u0003כל\u0004 דבר \u0003דאסר לן רחמנא\u0004 \u0005[שאסר לנו הכתוב],\u0006 \u0003שרא לן כוותיה\u0004 \u0005[התיר לנו\u0006 דבר אחר שהריהו \u0005כמותו\u0006 בטעמו\u0005],\u0006 למשל: \u0003אסר לן דמא\u0004 \u0005[לנו\u0006 אכילת \u0005דם]\u0006 — \u0003שרא לן כבדא\u0004 \u0005[התיר לנו\u0006 אכילת \u0005כבד]\u0006 שמלא דם, ויש בו מעין טעם דם. וכיוצא בדבר, אסר לנו הכתוב ביאת האשה ה\u0003נדה\u0004 — התיר לנו ביאת אישה כשיש לה \u0003דם טוהר\u0004 בימים שלאחר לידה. שאף אם רואה בהם דם, אינה נטמאת בכך, ומותרת לבעלה בימים אלה. אסר לנו הכתוב אכילת","\u0003חלב בהמה\u0004 — התיר לנו אכילת \u0003חלב חיה,\u0004 הדומה לו בטעמו. אסר לנו הכתוב אכילת \u0003חזיר\u0004 — התיר לנו אכילת \u0003מוחא\u0004 \u0005[מוח]\u0006 של הדג \u0003שיבוטא\u0004 שטעמו דומה לזה של חזיר. אסר לנו הכתוב \u0003גירותא\u0004 (מין דג טמא) — התיר לנו \u0003לישנא דכוורא\u0004 \u0005[לשון של דג]\u0006 הדומה לו בטעמו.","אסר לנו ביאת \u0003אשת איש\u0004 — התיר לנו \u0003גרושה בחיי בעלה,\u0004 שיש בדבר דמיון לביאת אשת איש. אסר לנו הכתוב ביאת \u0003אשת אח\u0004 — התיר לנו את \u0003יבמה\u0004 במצות ייבום (אם מת האח בלא זרע). אסר לנו את ה\u0003גויה\u0004 — התיר לנו \u0003את\u0004 \u0003יפת תאר\u0004 (שבויית מלחמה). ואם כן, כיון שאסרה עלינו התורה אכילת בשר בחלב, \u0003בעינן למיכל בשרא בחלבא\u0004 \u0005[רוצה אני לאכול\u0006 דבר שיש בו טעם \u0005בשר בחלב]!\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן לטבחי\u0004 \u0005[לטבחים]:\u0006 \u0003זויקו\u0004 \u0005[שפדו,\u0006 צלו על שיפוד\u0005]\u0006 \u0003לה כחלי\u0004 \u0005[כחלים]\u0006 ותאכל מהם. ושואלים על הוראת רב נחמן: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 ש\u0003קורעו\u0004 לכחל קודם בישולו, וכאן \u0003עשה בלא קריעה! ומשיבים:\u0004 הדין \u0003ההוא,\u0004 דין הקריעה, נאמר \u0003ל\u0004בישול ב\u0003קדרה\u0004 בלבד, א בל לא לצליה. ושואלים:","\u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 בברייתא שהובאה למעלה כי הכחל \u0003שבשלו\u0004 (שצלאו) בחלבו הריהו מותר, ונדייק: \u0003דיעבד\u0004 \u0005[כשנעשה]\u0006 כבר הדבר — \u0003אין\u0004 \u0005[כן]\u0006 מותר לאוכלו, אבל \u0003לכתחלה\u0004 — \u0003לא\u0004 ינהג כן, אלא יקרענו, ושלא כדברי רב נחמן! ומשיבים: \u0003הוא הדין\u0004 ש\u0003אפילו לכתחלה\u0004 מותר לצלות את הכחל בלא לקורעו, \u0003ואיידי דקא בעי למיתנא סיפא\u0004 \u0005[ומתוך שהוא\u0006 התנא \u0005רוצה לשנות בסוף]\u0006 \u0003קבה\u0004"]]};
